		fmt = '8. ซองแดงที่ได้รับแล้วหากยังไม่ได้เปิด จะสามารถเปิดในกิลด์ใหม่ได้ในระหว่างที่ยังอยู่ในระยะเวลาที่กำหนด'
	},
	[1019] = {
		id = 1019,
		fmt = '9. เมื่อเปลี่ยนกิลด์แล้วต้องรอจนถึงวันถัดไปจึงจะสามารถใช้ฟังก์ชันซองแดงได้'
	},
	[2001] = {
		id = 2001,
		fmt = '1. ทุกวันสามารถท้าทายอีเธอร์พาร์คได้ครั้งหนึ่ง'
