	[2002] = {
		id = 2002,
		fmt = '2. ทุกวันเวลา 05:00 จะมีการรีเซ็ตความคืบหน้าและอันดับในการท้าทายอีเธอร์พาร์ค'
	},
	[2003] = {
		id = 2003,
		fmt = '3. รางวัลอันดับจะถูกส่งทางอีเมลเมื่อมีการรีเซ็ต'
