	[2011] = {
		id = 2011,
		fmt = '1. อีเธอร์พาร์คมีทั้งหมด 7 ชั้น แต่ละชั้นมีห้อง 7-12 ห้อง และในแต่ละห้องจะมีตัวเลือก 1 ถึง 4 ตัวเลือกให้เลือก'
	},
	[2012] = {
		id = 2012,
		fmt = '2. เมื่อเลือกตัวเลือกแล้ว ผลลัพธ์ที่ได้จะขึ้นอยู่กับตัวเลือกนั้นๆ'
	},
	[2013] = {
		id = 2013,
		fmt = '3. การเลือกแต่ละครั้งจะมีผลต่อการเลือกในห้องถัดไป และตัวเลือกถัดไปจะปรากฏเมื่อคลิกที่ตัวเลือก'
