	},
	[2015] = {
		id = 2015,
		fmt = '5. ตัวเลือกการท้าทายมอนสเตอร์ต้องทำการต่อสู้ และหากชนะการต่อสู้จะได้รับคะแนนเท่านั้น โปเกมอนที่มีระดับสูงกว่า 10 เท่านั้นที่สามารถเข้าร่วมการท้าทายมอนสเตอร์ได้'
	},
	[2016] = {
		id = 2016,
		fmt = '6. ขึ้นอยู่กับระดับ, ผลการต่อสู้สูงสุดที่เคยทำได้ และผลการแสดงในวันก่อนหน้า ผู้เล่นสามารถกดข้ามการต่อสู้ในบางระดับได้ การข้ามจะทำให้ผ่านด่านโดยไม่มีความเสียหายและได้รับคะแนนเต็ม'
	},
	[2017] = {
		id = 2017,
		fmt = '7. ตัวเลือกที่มีการเพิ่มพลังหรือเสริมการฟื้นฟูจะช่วยในการต่อสู้และเพิ่มคะแนนได้มาก'
	},
	[2018] = {
		id = 2018,
		fmt = '8. ตัวเลือกที่เป็นกล่องสมบัติสามารถให้รางวัลมากมาย และสามารถใช้เพชรในการเปิดเพิ่มเติมเพื่อรับรางวัลมากขึ้น'
	},
	[2019] = {
		id = 2019,
		fmt = '9. ตัวเลือกเหตุการณ์จะเกิดผลลัพธ์แบบสุ่มหรือขึ้นอยู่กับการเลือกของผู้เล่น'
	},
	[2101] = {
		id = 2101,
		fmt = '1. การจับโปเกมอนแบ่งเป็นการจับโปเกมอนที่อยู่ประจำแผนที่และการจับโปเกมอนที่เกิดจากโอกาส'
	},
	[2102] = {
		id = 2102,
		fmt = '2. การจับโปเกมอนที่ประจำแผนที่จะปรากฏหลังจากผ่านด่านในแผนที่นั้นๆ ส่วนการจับโปเกมอนจากโอกาสจะปรากฏในระหว่างการท้าทายหรือทำภารกิจสะสม'
	},
	[2103] = {
		id = 2103,
		fmt = '3. เมื่อโปเกมอนประจำแผนที่ปรากฏจะปรากฏบนแผนที่และสามารถคลิกจับได้ ผู้เล่นสามารถพยายามจับจนกว่าจะสำเร็จ เมื่อจับได้แล้วจะหายไป'
	},
	[2104] = {
		id = 2104,
		fmt = '4. โปเกมอนที่เกิดจากโอกาสจะรวมอยู่ใน【ลูกบอลโปเกมอน】ที่มุมขวาบนของหน้าจอ ด้านนี้จะมีการจำกัดจำนวนครั้งและเวลา หากเกินจำนวนครั้งหรือเวลาที่กำหนด หรือหลังจากจับได้แล้วจะหายไป'
	},
	[2105] = {
		id = 2105,
		fmt = '5. สามารถใช้ลูกบอลโปเกมอนประเภทต่างๆ ในการจับโปเกมอน โดยมีอัตราความสำเร็จแตกต่างกันไปตามชนิดของลูกบอล'
	},
	[2106] = {
		id = 2106,
		fmt = '6. การเพิ่มระดับการจับโปเกมอนสามารถเพิ่มอัตราความสำเร็จในการจับได้'
	},
	[2107] = {
		id = 2107,
		fmt = '7. ขอให้โชคดีในการจับโปเกมอนที่คุณต้องการ'
	},
	[10001] = {
		id = 10001,
		fmt = '1. ในสนามแข่ง การต่อสู้จะเกิดขึ้นอัตโนมัติ ผู้เล่นไม่สามารถควบคุมได้'
	},
	[10002] = {
		id = 10002,
		fmt = '2. หากชนะการต่อสู้ และฝ่ายป้องกันมีอันดับสูงกว่าฝ่ายโจมตี อันดับของทั้งสองฝ่ายจะสลับที่กัน'
	},
	[10003] = {
		id = 10003,
		fmt = '3. หากการต่อสู้ถึงขีดจำกัดจำนวนรอบ ฝ่ายโจมตีจะเป็นฝ่ายแพ้'
