	[10007] = {
		id = 10007,
		fmt = '7. ทุกวันเวลา #C0xF76B45# 21:00#C0x5B545B# จะมีการคำนวณรางวัลอันดับ โดยส่งผ่านทางอีเมลให้กับผู้เล่นที่ติดอันดับ (99999 อันดับแรก)'
