	[11006] = {
		id = 11006,
		fmt = '7. หากหัวหน้ากิลด์ไม่ได้ออนไลน์เป็นเวลา 5 วัน จะมีการโอนตำแหน่งให้กับผู้ที่มีคะแนนสูงสุดและเข้าเงื่อนไขการออนไลน์ในช่วงเวลาดังกล่าว'
