	[12002] = {
		id = 12002,
		fmt = '2. บางชั้นในทดสอบจะมีหีบสมบัติ ไม่เพียงแต่รับรางวัลที่กำหนดไว้เท่านั้น แต่ยังสามารถใช้เพชรเพื่อเปิดรางวัลที่มากขึ้นได้'
	},
	[12003] = {
