		fmt = '3. ในหีบสมบัติมีโอกาสได้รับสัตว์เลี้ยง'
	},
	[12004] = {
		id = 12004,
		fmt = '4. บางชั้นสามารถใช้ดาวจากการทดสอบเพื่อซื้อบัฟเสริม ซึ่งจะช่วยให้การท้าทายต่อไปง่ายขึ้นมาก'
	},
	[12005] = {
		id = 12005,
		fmt = '5. การทดสอบสัตว์เลี้ยงจะรีเซ็ตทุกวันเวลา 05:00'
