	[13001] = {
		id = 13001,
		fmt = '1. ผู้เล่นสามารถทำกิจกรรมที่เปิดใน 8 วันแรกของกิจกรรมให้เสร็จสมบูรณ์ได้ หากเกิน 8 วัน กิจกรรมจะปิดอัตโนมัติ'
	},
	[13002] = {
		id = 13002,
		fmt = '2. ทำเป้าหมายทั้งหมดให้เสร็จสามารถรับรางวัลทั้งหมดของเป้าหมายทั้งหมด หรือในวันที่ 8 จะสามารถรับรางวัลสุดท้ายตามระดับความคืบหน้าที่ทำไว้'
	},
	[13003] = {
		id = 13003,
		fmt = '3. รางวัลเป้าหมายทั้งหมดสามารถรับได้เพียงครั้งเดียว หลังจากรับแล้วไม่สามารถรับได้อีก โปรดระมัดระวังในการรับ'
	},
	[14001] = {
		id = 14001,
		fmt = 'สัตว์เลี้ยงเทพที่มีปีกหกใบส่องแสงสว่าง พร้อมร่างกายที่ห่มผ้าขาวบริสุทธิ์ ถือเป็นสิ่งที่ดีสมบูรณ์ ถูกเรียกว่าผู้ที่นำความสุขมาให้ และจะไม่หยุดโจมตีศัตรูจนกว่าจะทำลายสิ่งชั่วร้าย'
	},
	[14002] = {
		id = 14002,
		fmt = 'คำท้าทายสวรรค์: ใช้หมัดขนาดใหญ่ที่ส่องแสงสีทองโจมตีศัตรูทั้งหมด ทำให้เกิดความเสียหายมหาศาล และมีโอกาส 30% ที่จะลดความโกรธ 300 และ 15% ที่จะควบคุมเป้าหมาย'
	},
	[14003] = {
		id = 14003,
		fmt = 'ไม้เท้าวิเศษ: ใช้ไม้เท้าศักดิ์สิทธิ์ของเทพเจ้าสัตว์เลี้ยงโจมตีเป้าหมายเดียว ทำความเสียหายมหาศาล มีโอกาส 20% ที่จะปิดการใช้ทักษะของศัตรู และทำความเสียหายเพิ่มเติม 60% ต่อศัตรูที่มีคุณสมบัติป้องกัน'
	},
	[14004] = {
		id = 14004,
		fmt = 'เสริมพลังโจมตีระดับเทพ: เพิ่มพลังโจมตีของตัวเอง'
	},
	[14005] = {
		id = 14005,
		fmt = 'การปกป้องของเทพเจ้าสัตว์เลี้ยง: เพิ่มอัตราการควบคุมของสัตว์เลี้ยงประเภททักษะในทีม'
	},
	[14006] = {
		id = 14006,
		fmt = 'เพิ่มความเสียหาย: สกิลทั่วไปที่ทำให้เกิดความเสียหายสูงขึ้น โดยเพิ่มอัตราความเสียหาย'
	},
	[14007] = {
		id = 14007,
		fmt = 'การลดความเสียหาย: สกิลทั่วไปที่ลดความเสียหายที่ได้รับจากศัตรู โดยเพิ่มอัตราการป้องกันความเสียหาย'
	},
	[15001] = {
		id = 15001,
		fmt = 'เวลาการเปิดกิจกรรมเริ่มตั้งแต่วันที่ 3 ของการเปิดเซิร์ฟเวอร์ เวลา 05:00 ถึง 08:00 ของวันที่ 8 การมอบรางวัลจะขึ้นอยู่กับอันดับพลังการต่อสู้ในวันที่ 7 เวลา 21:30 (ส่งผ่านอีเมล)'
	},
	[15002] = {
		id = 15002,
		fmt = 'ในวันที่ 7 เวลา 21:30 จะมีการมอบรางวัลตามพลังการต่อสู้ (รางวัลจะมอบตามพลังการต่อสู้สูงสุด ไม่สะสม)'
	},
	[15003] = {
		id = 15003,
		fmt = 'หากพลังการต่อสู้เท่ากัน จะใช้เวลาจัดอันดับตามลำดับเวลา'
	},
	[15004] = {
		id = 15004,
		fmt = 'การรับรางวัลอันดับที่ 1-10 ต้องมีพลังการต่อสู้ 45,000'
	},
	[16001] = {
		id = 16001,
		fmt = '1. การใช้งานในกิจกรรมนี้จะรีเซ็ตทุกวันเวลา 05:00'
	},
	[16002] = {
		id = 16002,
		fmt = '2. กดค้างที่ลูกศรขึ้นลงหรือขยายเพื่อปรับความแรงและมุมของกระบอกปืน'
	},
	[16003] = {
		id = 16003,
		fmt = '3. กิจกรรมนี้สามารถรับเหรียญทอง, เพชร, และชิ้นส่วนของหมีน้ำแข็ง'
	},
	[16004] = {
		id = 16004,
		fmt = '4. เมื่อยิงถูกเป้าหมายจะได้รับคะแนน +1 ทุกครั้ง ทุกๆ การได้คะแนนจะได้รับรางวัลตามจำนวนคะแนนที่ถึง'
	},
