	[18001] = {
		id = 18001,
		fmt = '#C0xFFFFF5D6#1. เวลาสมัคร: #C0xFF4FF701# 10:00-19:50'
	},
	[18002] = {
		id = 18002,
		fmt = '#C0xFFFFF5D6#2. เวลาการแข่งขัน: #C0xFF4FF701# 20:00-20:55'
	},
	[19001] = {
		id = 19001,
		fmt = '#C0xFFF5D6#1. ผู้เล่นสามารถส่งซองแดงและรับซองแดงในซองแดงกิลด์ได้ โดยมีจำนวนจำกัด ดังนั้นต้องรีบหน่อยนะ'
	},
	[19002] = {
		id = 19002,
		fmt = '#C0xFFF5D6#2. ซองแดงกิลด์จะรีเฟรชอัตโนมัติทุกวันเวลา 19:00'
	},
	[19003] = {
		id = 19003,
		fmt = '#C0xFFF5D6#3. การอัพเกรดเทคโนโลยีซองแดงในสถาบันวิจัยจะช่วยเพิ่มจำนวนและมูลค่าของซองแดงกิลด์'
	},
	[19004] = {
		id = 19004,
		fmt = '#C0xFFF5D6#4. การส่งและรับซองแดงจะต้องเลือกด้วยตนเองจากผู้เล่น'
	},
	[19005] = {
		id = 19005,
		fmt = '#C0xFFF5D6#5. ผู้เล่นสามารถรับซองแดงที่ตัวเองส่งได้'
	},
	[19006] = {
		id = 19006,
		fmt = '#C0xFFF5D6#6. มูลค่าของซองแดงที่ได้รับจะเป็นแบบสุ่ม มันจะเหมือนกับการช่วยคุณยายข้ามถนน'
	},
	[19007] = {
		id = 19007,
		fmt = '#C0xFFF5D6#7. การเพิ่มระดับ VIP จะช่วยเพิ่มจำนวนครั้งในการส่งและรับซองแดง'
	},
	[19008] = {
		id = 19008,
		fmt = '#C0xFFF5D6#8. ซองแดงที่ผู้เล่นส่งจะมีอายุ 24 ชั่วโมง หากหมดอายุแล้วจะหายไปและยอดคงเหลือจะไม่สามารถคืนได้'
	},
	[20001] = {
		id = 20001,
		fmt = 'ยินดีต้อนรับสู่สงครามกิลด์! สงครามกิลด์จะมีฤดูกาลละหนึ่งสัปดาห์ ทุกฤดูกาลมีรางวัลมากมาย ร่วมมือกับเพื่อนร่วมทีมและไปต่อสู้กันเถอะ!'
	},
	[20002] = {
		id = 20002,
		fmt = '1. การแข่งขันแบ่งเป็น 2 ช่วง: รอบคัดเลือก 4 วัน (วันอังคารถึงวันศุกร์) และรอบชิงชนะเลิศ 1 วัน (วันเสาร์)'
	},
	[20003] = {
		id = 20003,
		fmt = '2. เวลาสมัครการแข่งขันประจำวัน: #C0xF76B45# 9:30-20:50'
	},
	[20004] = {
		id = 20004,
		fmt = '3. เวลาเริ่มการแข่งขัน: #C0xF76B45# 21:00'
	},
	[20005] = {
		id = 20005,
		fmt = '4. เงื่อนไขการสมัคร: ผู้เล่นที่มีระดับเทรนเนอร์ 40 ขึ้นไป และระดับกิลด์ 4 ขึ้นไปสามารถสมัครได้เท่านั้น ต้องสมัครเพื่อเข้าร่วมการแข่งขันในวันนั้น'
	},
	[20006] = {
		id = 20006,
		fmt = '5. ผู้เล่นที่มี VIP ระดับ 3 ขึ้นไป ระบบจะสมัครอัตโนมัติครึ่งชั่วโมงก่อนเริ่มการแข่งขันทุกวัน'
	},
	[21001] = {
		id = 21001,
		fmt = '1. ในระหว่างรอบคัดเลือก ตั้งแต่วันอังคารถึงวันพฤหัสบดีจะจำกัดประเภทของโปเกมอนที่จะใช้ในการแข่งขัน สามารถดูข้อกำหนดได้ที่หน้าสมัครหรือหน้าจัดทีม ในวันศุกร์ไม่มีการจำกัดประเภทของโปเกมอน'
	},
	[21002] = {
		id = 21002,
		fmt = '2. สำหรับรอบที่มีข้อจำกัดประเภทโปเกมอน หากโปเกมอนของคุณมีคุณสมบัติที่ตรงกับข้อกำหนดใดข้อกำหนดหนึ่ง คุณสามารถเข้าร่วมการแข่งขันในวันนั้นได้ โดยสามารถใช้โปเกมอนในสายวิวัฒนาการเดียวกันได้แค่ครั้งเดียวในวันนั้น'
	},
	[21003] = {
		id = 21003,
		fmt = '3. ในรอบคัดเลือกสามารถส่งโปเกมอนได้ 2 ทีม ทีมละ 3 ตัว'
	},
	[21004] = {
		id = 21004,
		fmt = '4. หากทีมแรกแพ้ ทีมที่สองสามารถเข้าร่วมการแข่งขันในรอบถัดไปได้'
	},
	[21005] = {
		id = 21005,
		fmt = '5. รูปแบบการแข่งขันเป็นแบบการต่อสู้แบบมัลติเพลเยอร์ คุณจะได้เจอกับผู้เล่นจากกิลด์อื่นๆ (หากจำนวนผู้เล่นเหลือน้อย อาจต้องต่อสู้กับสมาชิกในกิลด์ของตัวเองเพื่อจัดอันดับ)'
	},
	[21006] = {
		id = 21006,
		fmt = '6. ผู้เล่นที่ชนะสามารถไปต่อในรอบถัดไปและต่อสู้กับคู่ต่อสู้ที่เหลือ'
	},
	[21007] = {
		id = 21007,
		fmt = '7. หลังจากการแข่งขันทุกครั้ง จะเก็บค่าพลังชีวิตและความโกรธที่เหลือไว้'
	},
	[21008] = {
		id = 21008,
		fmt = '8. สงครามกิลด์มีระบบคะแนน โดยจะได้รับคะแนนส่วนตัวตามนี้: ชนะ 1 คน = 2 คะแนน, แพ้ = 1 คะแนน'
	},
	[21009] = {
		id = 21009,
		fmt = '9. ผู้เล่นที่ชนะจะสามารถเพิ่มคะแนนกิลด์และดาวการต่อสู้ของกิลด์ได้ โดยดาวการต่อสู้สามารถใช้ในการเพิ่มบัฟคุณสมบัติในรอบสุดท้าย'
	},
	[21010] = {
		id = 21010,
		fmt = '10. อันดับของกิลด์ในวันนั้นจะขึ้นอยู่กับคะแนนรวมของกิลด์ในวันนั้น'
	},
	[21011] = {
		id = 21011,
		fmt = '11. การต่อสู้ระหว่างสองฝ่ายจะมีสูงสุด 10 รอบ หากไม่สามารถตัดสินผลได้ในเวลาที่กำหนด ฝ่ายที่มีเปอร์เซ็นต์พลังชีวิตสูงกว่าจะเป็นผู้ชนะ'
	},
	[22001] = {
		id = 22001,
		fmt = '1. ในระหว่างรอบคัดเลือก 4 วัน กิลด์ที่ได้อันดับ 8 อันดับแรกจะเข้าสู่รอบชิงชนะเลิศ ทุกคนที่มีคุณสมบัติสามารถสมัครอัตโนมัติในช่วงเตรียมตัวรอบชิงชนะเลิศ'
	},
	[22002] = {
		id = 22002,
		fmt = '2. ในรอบชิงชนะเลิศ สามารถใช้โปเกมอนทุกประเภทได้'
	},
	[22003] = {
		id = 22003,
		fmt = '3. การแข่งขันรอบชิงชนะเลิศเป็นการแข่งขันระหว่างกิลด์แบบคัดออก，จนกว่าจะหาผู้ชนะ'
	},
	[22004] = {
		id = 22004,
		fmt = '4. ในรอบชิงชนะเลิศ รูปแบบการแข่งขันจะเป็นการต่อสู้แบบ Wheel War ระหว่างกิลด์ ใช้โปเกมอน 3 ทีมในการแข่งขัน โดยแต่ละทีมสามารถใช้ได้สูงสุด 4 ตัว'
	},
	[22005] = {
		id = 22005,
		fmt = '5. ในการแข่งขันระหว่างกิลด์ จะมีการแข่งขันตามลำดับทีม ทีมที่ชนะจะสามารถไปต่อในการแข่งขันรอบถัดไป ฝ่ายที่แพ้จะต้องออกจากการแข่ง จนกว่าจะมีทีมทั้งหมดของฝ่ายหนึ่งพ่ายแพ้ ฝ่ายที่ชนะจะได้รับชัยชนะ'
	},
	[22006] = {
		id = 22006,
		fmt = '6. กิลด์ที่ชนะสามารถไปต่อในการแข่งขันกับกิลด์ที่ชนะอื่นๆ จนกว่าจะชนะและได้รับตำแหน่งแชมป์'
	},
	[22007] = {
		id = 22007,
		fmt = '7. ในซีรีส์การต่อสู้รอบสุดท้าย สถานะของสัตว์เลี้ยงจะคงอยู่ แม้ว่าจะชนะ แต่พลังชีวิตของโปเกมอนก็จะไม่ฟื้นคืน และโปเกมอนที่เสียชีวิตจะไม่ฟื้นคืน'
	},
	[22008] = {
		id = 22008,
		fmt = '8. หลังจากการต่อสู้จบในสงครามกิลด์ รางวัลจะถูกแจกตามอันดับ เพื่อเพิ่มคะแนนให้กับกิลด์'
	},
	[22101] = {
		id = 22101,
		fmt = '1. ในระหว่างรอบคัดเลือก กิลด์ที่ชนะการแข่งขันในแต่ละวันจะได้รับดาวการต่อสู้ 1 ดวง'
	},
	[22102] = {
		id = 22102,
		fmt = '2. ก่อนเริ่มการแข่งขันรอบสุดท้าย ผู้จัดการของกิลด์ที่มีดาวการต่อสู้สามารถใช้ดาวการต่อสู้เพื่อเพิ่มบัฟคุณสมบัติและค่าความสามารถในการแข่งขันรอบสุดท้าย'
	},
	[22103] = {
		id = 22103,
		fmt = '3. เมื่อการตั้งค่าบัฟเสร็จสิ้น จะใช้ดาวการต่อสู้ 1 ดวง และไม่สามารถเปลี่ยนแปลงได้หลังจากการตั้งค่า'
	},
	[22104] = {
		id = 22104,
		fmt = '4. หลังจากตั้งค่าบัฟแล้ว การเปลี่ยนแปลงค่าความสามารถนี้จะมีผลกับโปเกมอนทั้งหมดที่เข้าร่วมในรอบสุดท้าย'
	},
	[22201] = {
		id = 22201,
		fmt = '1. ในระหว่างการแข่งขันรอบสงครามกิลด์ครั้งแรก สัตว์เลี้ยงในทีมจะได้รับบัฟเพิ่มคุณสมบัติการโจมตี การป้องกัน ความเร็ว และอื่นๆ'
	},
	[22202] = {
		id = 22202,
		fmt = '2. เมื่อการแข่งขันดำเนินไป บัฟนี้จะค่อยๆ ลดลง และสัตว์เลี้ยงจะรู้สึกเหนื่อยล้า ความสามารถในการต่อสู้จะลดลง'
	},
	[22203] = {
		id = 22203,
		fmt = '3. หลังจากนั้น ทุกครั้งที่เข้าร่วมการต่อสู้ สถานะการโจมตี การป้องกัน ความเร็ว และปริมาณการรักษาของโปเกมอนในทีมจะลดลง'
	},
	[22301] = {
		id = 22301,
		fmt = '1. ในระหว่างช่วงการสมัครรอบสุดท้าย (วันเสาร์เวลา 9:30-20:50) สามารถทำนายผลการแข่งขันได้'
	},
	[22302] = {
		id = 22302,
		fmt = '2. การเดิมพันแชมป์จะมีอัตราต่อรองที่สูงขึ้นและรางวัลมากขึ้น สูงสุดไม่เกิน 1,000,000 ทองคำ'
	},
	[22303] = {
		id = 22303,
		fmt = '3. หลังจากการแข่งขันสิ้นสุด รางวัลจะถูกแจกผ่านทางอีเมล โดยการทำนายแชมป์จะได้รับเงินตามอัตราต่อรองที่เดิมพันไว้ ส่วนทำนายอันดับที่ 2 จะได้รับคืนครึ่งหนึ่งของจำนวนเงินที่เดิมพัน'
	},
	[23001] = {
		id = 23001,
		fmt = '1. หลังจากการแข่งขันสิ้นสุด รางวัลทั้งหมดจะถูกส่งผ่านทางอีเมล'
	},
	[23002] = {
		id = 23002,
		fmt = '2. การแข่งขันประจำวันประกอบด้วยรางวัลสมัคร รางวัลชนะส่วนตัว และรางวัลอันดับกิลด์ รางวัลอันดับกิลด์จะมอบให้กับสมาชิกของกิลด์ที่เข้าร่วมการแข่งขัน'
	},
	[23003] = {
		id = 23003,
		fmt = '3. การสมัครรอบคัดเลือกและรอบชิงชนะเลิศจะได้รับรางวัลการเข้าร่วมหนึ่งรายการ'
	},
	[23004] = {
		id = 23004,
