	[36001] = {
		id = 36001,
		fmt = '#C0xFFF5D6#สัตว์ประหลาดปีศาจพยายามทำลายและปรับปรุงโลกของสัตว์เลี้ยง โดยปล่อยเกียร์มืดจำนวนมากและควบคุมสัตว์เลี้ยงจำนวนมาก ทุกวันจะปล่อยสัตว์เลี้ยงบางตัวออกมาอาละวาด เพื่อช่วยโลกของสัตว์เลี้ยงให้ปลอดภัย มาร่วมมือกันในการทำความสะอาดสัตว์เลี้ยงที่ถูกควบคุมโดยเกียร์มืดกันเถอะ'
	},
	[36002] = {
		id = 36002,
		fmt = '#C0xFFF5D6#1. ทุกวันเวลา 12:00 จะรีเฟรชการจัดสัตว์เลี้ยงมืดใหม่'
	},
	[36003] = {
		id = 36003,
		fmt = '#C0xFFF5D6#2. ทุกวันเวลา 12:00 นักเรียกสัตว์ทั่วโลกสามารถสร้างหรือเข้าร่วมทีมกับนักเรียกคนอื่นเพื่อร่วมกันต่อสู้กับสัตว์เลี้ยงที่ถูกควบคุมโดยเกียร์มืด'
	},
	[36004] = {
		id = 36004,
		fmt = '#C0xFFF5D6#3. การร่วมทีมในการทำความสะอาดสัตว์เลี้ยงจะได้รับเศษส่วนของสัตว์เลี้ยงที่เกี่ยวข้อง'
	},
	[36005] = {
		id = 36005,
		fmt = '#C0xFFF5D6#4. หากคุณต้องการทำความสะอาดสัตว์เลี้ยงบางตัว คุณต้องมีสัตว์เลี้ยงนั้นก่อน'
	},
	[36006] = {
		id = 36006,
		fmt = '#C0xFFF5D6#5. ทุกครั้งที่ชนะในการต่อสู้จะได้รับสองกล่องรางวัล กล่องแรกเปิดฟรี กล่องที่สองต้องใช้เพชรในการเปิด ทั้งสองกล่องมีโอกาสได้รับเศษส่วนของสัตว์เลี้ยง'
	},
	[36007] = {
		id = 36007,
		fmt = '#C0xFFF5D6#6. ในภารกิจการทำความสะอาดทุกครั้ง ยิ่งมีผู้เล่นมากที่เสร็จสิ้นการต่อสู้ทั้งหมด ยิ่งจะได้รับรางวัลเพิ่มเติม รางวัลพิเศษจะถูกส่งผ่านอีเมล โดยเงื่อนไขคือผู้เล่นต้องทำการต่อสู้ทั้งหมดเอง'
	},
	[36008] = {
		id = 36008,
		fmt = '#C0xFFF5D6#7. ทีมที่มี 3, 4 หรือ 5 คนที่เสร็จสิ้นการต่อสู้จะได้รับรางวัลพิเศษในระดับต่างๆ'
	},
	[36009] = {
		id = 36009,
		fmt = '#C0xFFF5D6#8. หลังจากเลือกเป้าหมายการทำความสะอาดแล้ว คุณไม่สามารถออกจากทีมได้จนกว่าจะชนะการต่อสู้'
	},
	[36010] = {
		id = 36010,
		fmt = '#C0xFFF5D6#9. ทุกวันเวลา 12:00 ทีมเก่าจะถูกยกเลิกโดยอัตโนมัติ และต้องสร้างทีมใหม่'
	},
	[36011] = {
		id = 36011,
		fmt = '#C0xFFF5D6#10. ผู้เล่นสามารถคลิกที่อวตารของตัวเองในทีมเพื่อเปลี่ยนสัตว์เลี้ยงที่ใช้ในการต่อสู้'
	},
	[37001] = {
		id = 37001,
		fmt = '1. การแข่งขันรอบคัดเลือก, รอบ 8 ทีม, และรอบชิงแชมป์เป็นการต่อสู้แบบ 3 ต่อ 3 แบบล้อเลื่อน'
	},
	[37002] = {
		id = 37002,
		fmt = '2. การเลือกสัตว์เลี้ยงเข้าสู่สนาม, สัตว์เลี้ยงที่มีค่าการโจมตีสูงกว่าจะเริ่มต้นการโจมตีก่อน; หากค่าการโจมตีเท่ากัน สัตว์เลี้ยงที่มีพลังรวมสูงกว่าจะเริ่มต้นการโจมตีก่อน'
	},
	[37003] = {
		id = 37003,
		fmt = '3. การต่อสู้ระหว่างสัตว์เลี้ยง 2 ตัว, รอบการต่อสู้สูงสุดคือ 10 รอบ'
	},
	[37004] = {
		id = 37004,
		fmt = '4. หากทั้งสองฝ่ายยังไม่ตายภายใน 10 รอบ, ฝ่ายที่มีเปอร์เซ็นต์เลือดสูงกว่าจะชนะ'
	},
	[37005] = {
		id = 37005,
		fmt = '5. ฝ่ายที่มีสัตว์เลี้ยงที่ยังมีชีวิตอยู่สุดท้ายจะชนะ'
	},
	[38001] = {
		id = 38001,
		fmt = '1. ในวันแรก ผู้เล่นสามารถเดิมพันจำนวนการชนะของตนในรอบคัดเลือกว่าเป็นเลขคี่หรือเลขคู่'
	},
	[38002] = {
		id = 38002,
		fmt = '2. ในวันที่สอง ผู้เล่นสามารถเดิมพันเกี่ยวกับผู้เล่นที่มีพลังรวมสูงสุด 20 อันดับในการแข่งขัน'
	},
	[38003] = {
		id = 38003,
		fmt = '3. เดิมพันชนะ, อัตราต่อรองยิ่งสูง, ผลตอบแทนยิ่งใหญ่. ทุกๆ รอบสูงสุดจะได้รับ 1,000,000 ทอง'
	},
	[38004] = {
		id = 38004,
		fmt = '4. หากฝ่ายที่เดิมพันเข้าสู่รอบ 4 ทีมสุดท้ายจะได้รับคืน 1.5 เท่าของเงินเดิมพัน, หากไม่เข้าสู่รอบ 4 ทีมสุดท้ายจะได้รับคืนครึ่งหนึ่ง'
	},
	[39001] = {
		id = 39001,
		fmt = '1. เวลาเปิดรับสมัคร: #C0xF76B45# 10:00 - 19:50'
	},
	[39002] = {
		id = 39002,
		fmt = '2. เวลาแข่งขัน: #C0xF76B45# 20:00 - 20:55'
	},
	[39003] = {
		id = 39003,
		fmt = '3. ในการสมัคร, สามารถเลือกสัตว์เลี้ยงได้สูงสุด 10 ตัว, หลังจากสมัครสำเร็จแล้วสามารถเปลี่ยนแปลงทีมได้'
	},
	[39004] = {
		id = 39004,
		fmt = '4. การแข่งขันแบ่งเป็น 2 ส่วนคือรอบคัดเลือกและรอบ 8 ทีม, 8 ทีมที่ผ่านการคัดเลือกจะเข้าสู่รอบ 8 ทีม'
	},
	[39005] = {
		id = 39005,
		fmt = '5. ก่อนการแข่งขัน 1 นาที, ผู้เล่นไม่สามารถปรับเปลี่ยนทีมได้'
	},
	[39006] = {
		id = 39006,
		fmt = '6. ผู้เล่นที่มี VIP3 หรือสูงกว่าจะสมัครโดยอัตโนมัติ 50 นาทีก่อนเวลาปิดรับสมัคร'
	},
	[39007] = {
		id = 39007,
		fmt = '7. ในช่วงการต่อสู้, ทั้งสองฝ่ายจะต่อสู้สูงสุด 10 รอบ, หากไม่สามารถตัดสินผลได้ใน 10 รอบ, หากทั้งสองฝ่ายมีเปอร์เซ็นต์เลือดสูงกว่า 90%, ฝ่ายที่ทำความเสียหายได้มากที่สุดจะชนะ, ถ้าฝ่ายใดฝ่ายหนึ่งมีเปอร์เซ็นต์เลือดต่ำกว่า 90%, ฝ่ายที่มีเปอร์เซ็นต์เลือดสุดท้ายสูงกว่าจะชนะ'
	},
	[39008] = {
		id = 39008,
		fmt = '8. การแข่งขันมีการจัดอันดับคะแนน, คะแนนขึ้นอยู่กับความเสียหายที่สัตว์เลี้ยงทำได้, ยิ่งทำความเสียหายมาก คะแนนยิ่งสูง'
	},
	[39009] = {
		id = 39009,
		fmt = '9. ทุกวันเวลา 10:00 สามารถเริ่มเดิมพันได้, อัตราต่อรองยิ่งสูง ผลตอบแทนยิ่งมาก, สูงสุดที่ได้รับ 1,000,000 ทอง'
	},
	[39010] = {
		id = 39010,
		fmt = '10. หากฝ่ายที่เดิมพันเข้าสู่รอบ 8 ทีมสุดท้าย, และไม่ชนะ, จะได้รับเงินเดิมพันคืนบางส่วน; หากไม่เข้าสู่รอบ 8 ทีมสุดท้าย จะไม่ได้รับการคืนเงิน'
	},
	[40001] = {
		id = 40001,
		fmt = '1. รอบคัดเลือกเป็นระบบคัดเลือกโดยสะสมคะแนน, มีทั้งหมด 10 รอบการแข่งขัน, ทุกการแข่งขันใช้เวลา 4 นาที, คะแนนจะสะสมจากการชนะ, หากคะแนนเท่ากันจะจัดอันดับจากคะแนนที่ได้'
	},
	[40002] = {
		id = 40002,
		fmt = '2. ในแต่ละการแข่งขัน, ผู้เล่นจะเลือกสัตว์เลี้ยง 1 ตัวในการต่อสู้'
	},
	[40003] = {
		id = 40003,
		fmt = '3. หากผู้เล่นสะสมแพ้ 3 ครั้งจะถูกคัดออกจากการแข่งขัน'
	},
	[40004] = {
		id = 40004,
		fmt = '4. ผู้เล่นสามารถสะสมคะแนนจากการชนะ, หลังจากรอบคัดเลือกจะจัดอันดับ 8 ทีมที่ดีที่สุดเพื่อเข้าสู่รอบ 8 ทีม'
	},
	[40005] = {
		id = 40005,
		fmt = '5. สัตว์เลี้ยงไม่สามารถใช้ซ้ำในการแข่งขันเดียวกัน'
	},
	[41001] = {
		id = 41001,
		fmt = '1. รอบ 8 ทีมเป็นระบบคัดออก, รวมถึงรอบ 4 ทีม, รอบรองชนะเลิศ, รอบชิงแชมป์ และรอบชิงที่สาม โดยการแข่งขันแต่ละรอบมีเวลา 5 นาที'
	},
	[41002] = {
		id = 41002,
		fmt = '2. ในแต่ละการแข่งขัน, ผู้เล่นต้องส่งสัตว์เลี้ยง 3 ตัวเข้าแข่งขัน, ใช้ระบบล้อเลื่อนในการออกสู้ตามลำดับ'
	},
	[41003] = {
		id = 41003,
		fmt = '3. หากสัตว์เลี้ยงทั้ง 3 ตัวถูกทำลายทั้งหมด, ฝ่ายนั้นจะแพ้'
	},
	[41004] = {
		id = 41004,
		fmt = '4. สัตว์เลี้ยงไม่สามารถใช้งานซ้ำ'
	},
	[42001] = {
		id = 42001,
		fmt = '1. หลังจากแต่ละการแข่งขัน, ผู้เล่นจะได้รับกล่องรางวัล'
	},
	[42002] = {
		id = 42002,
		fmt = '2. ชนะจะได้รับกล่องทอง, แพ้จะได้รับกล่องเงิน'
	},
	[42003] = {
		id = 42003,
		fmt = '3. ทั้งสองกล่องมีโอกาสได้รับของขวัญจากเซลล์ควอทซ์และไอเทมอื่นๆ'
	},
	[42004] = {
		id = 42004,
		fmt = '4. รางวัลตามอันดับในวันนั้นจะได้รับผ่านอีเมลหลังจากการแข่งขันเสร็จสิ้น'
	},
	[43001] = {
		id = 43001,
		fmt = '#C0xFFF5D6#1. เริ่มต้นผู้เล่นสามารถเล่นได้ 5 ครั้งต่อวัน โดยสามารถเพิ่มจำนวนการเล่นได้จากการพัฒนาเทคโนโลยี สุ่มธาตุไฟ ในศูนย์วิจัย'
	},
	[43002] = {
		id = 43002,
		fmt = '#C0xFFF5D6#2. ฟังก์ชันนี้เริ่มต้นสามารถหมุนฟรีได้ 5 ครั้ง และสามารถเพิ่มจำนวนการหมุนฟรีได้จากการพัฒนาเทคโนโลยีที่เกี่ยวข้องในศูนย์วิจัย'
	},
	[43003] = {
		id = 43003,
		fmt = '#C0xFFF5D6#3. ธาตุไฟ ที่หมุนออกมาจะไม่หายไป'
	},
	[43004] = {
		id = 43004,
		fmt = '#C0xFFF5D6#4. ยิ่งมีจำนวนธาตุไฟ มาก, รางวัลยิ่งใหญ่ขึ้น, ผู้เล่นจะได้รับชิ้นส่วน ของธาตุไฟ และจำนวนเหรียญกิลด์จำนวนมาก'
	},
	[44001] = {
		id = 44001,
		fmt = '1. เวลาการเปิดของดันเจี้ยนกิลด์: วันจันทร์ถึงวันเสาร์ 9:30 - 23:30, วันอาทิตย์ปิดทำการ;'
	},
	[44002] = {
		id = 44002,
		fmt = '2. วันจันทร์, พุธ, ศุกร์ เวลา 5:00 น. ระบบจะรีเซ็ตดันเจี้ยนโดยอัตโนมัติ และจะรีเซ็ตเฉพาะดันเจี้ยนที่มีความยากสูงสุดในตอนนั้น; วันอังคาร, พฤหัสบดี, เสาร์ เวลา 23:30 น. ดันเจี้ยนกิลด์จะปิดและจะทำการคำนวณคะแนนและแจกของรางวัลอันดับความเสียหาย;'
	},
	[44003] = {
		id = 44003,
		fmt = '3. ผู้เล่นสามารถท้าทายได้ 3 ครั้งต่อวัน, โดยทุกดันเจี้ยนใช้จำนวนท้าทายเดียวกัน, รีเซ็ตจำนวนการท้าทายทุกวันเวลา 5:00 น. ในระหว่างการท้าทายมีโอกาสได้รับกล่องบอสกิลด์;'
	},
	[44004] = {
		id = 44004,
		fmt = '4. เมื่อผ่านดันเจี้ยนปัจจุบันแล้ว ดันเจี้ยนถัดไปจะถูกปลดล็อก ดันเจี้ยนที่ผ่านไปแล้วจะไม่สามารถทำซ้ำได้จนกว่าจะมีการรีเซ็ตรายเดือน;'
	},
	[44005] = {
		id = 44005,
		fmt = '5. หลังจากทำการท้าทายดันเจี้ยนแต่ละแห่ง จะได้รับรางวัลตามอันดับความเสียหายจากการเข้าร่วม;'
	},
	[44006] = {
		id = 44006,
		fmt = '6. ทุกดันเจี้ยนมีรางวัลแรกที่ผ่าน ดันเจี้ยนที่ผ่านแล้วจะได้รับรางวัลนี้เพียงครั้งเดียวต่อผู้เล่น;'
	},
	[44007] = {
		id = 44007,
		fmt = '7. สำหรับแต่ละดันเจี้ยน ถ้าผ่านจำนวนกิลด์และเวลาที่ใช้ในดันเจี้ยน ผู้เล่นภายในกิลด์จะได้รับโบนัสเพิ่มทั้งในเรื่องของการโจมตี, การป้องกัน, และเลือด ซึ่งโบนัสเหล่านี้จะมีผลเฉพาะในดันเจี้ยนที่กำลังเล่นอยู่;'
	},
	[44008] = {
		id = 44008,
		fmt = '8. ในต้นเดือนของแต่ละเดือน จะมีการรีเซ็ตดันเจี้ยนทั้งหมด, หลังจากรีเซ็ตแล้วเมื่อผ่านดันเจี้ยนหนึ่งแล้ว สมาชิกทุกคนในกิลด์สามารถรับรางวัลการกำจัดบอสได้ (ไม่ใช่รางวัลการผ่านครั้งแรก);'
	},
	[44009] = {
		id = 44009,
		fmt = '9. รางวัลการกำจัดบอส (ไม่ใช่รางวัลการผ่านครั้งแรก) จะได้รับเพียง 1 ครั้งต่อผู้เล่นในแต่ละดันเจี้ยนในรอบการรีเซ็ต;'
	},
	[44010] = {
		id = 44010,
		fmt = '10. เมื่อเปลี่ยนกิลด์ ผู้เล่นจะไม่สามารถทำการท้าทายดันเจี้ยนกิลด์ได้ในวันนั้น ต้องรอจนถึงเวลา 5:00 น. ในวันถัดไป;'
	},
	[44011] = {
		id = 44011,
		fmt = '11. ผู้เล่นที่ช่วยบอสกิลด์ให้เสียชีวิตจะได้รับรางวัลเหรียญและเพชรเพิ่มเติม, การกำจัดบอสตัวเดียวกันในช่วงการรีเซ็ตเดือนนั้นจะได้รับรางวัลเพียงครั้งเดียว;'
	},
	[44012] = {
		id = 44012,
		fmt = '12. รางวัลการกำจัดบอสทั้งหมดต้องทำการรับจากกล่องรางวัล, รางวัลจากการเข้าร่วมและรางวัลจากการช่วยเหลือจะได้รับในขณะที่คำนวณ; รางวัลอันดับความเสียหายจะส่งให้ผ่านทางอีเมล;'
	},
	[45001] = {
		id = 45001,
		fmt = '1. สมาชิกทุกคนสามารถขอพรได้ 1 ครั้งต่อวัน โดยการโพสต์พรที่ต้องการให้ได้รับชิ้นส่วนของโปเกมอนที่ต้องการในกิลด์'
	},
	[45002] = {
		id = 45002,
		fmt = '2. การขอพรจะต้องใช้โปเกมอนที่คุณมีในปัจจุบันเท่านั้นเป็นเป้าหมายในการขอพร'
	},
	[45003] = {
		id = 45003,
		fmt = '3. โปเกมอนที่มีคุณภาพต่างกันจะได้รับจำนวนชิ้นส่วนสูงสุดที่แตกต่างกัน, โปเกมอนที่มีคุณภาพสูงจะได้รับชิ้นส่วนที่น้อยลง'
	},
	[45004] = {
		id = 45004,
		fmt = '4. ผู้เล่นสามารถมอบชิ้นส่วนโปเกมอนที่ตนเองมีให้แก่สมาชิกคนอื่นได้ เพื่อช่วยให้เขาบรรลุความปรารถนา โดยสามารถมอบได้สูงสุด 1 ชิ้นส่วนต่อสมาชิก 1 คน'
	},
	[45005] = {
		id = 45005,
		fmt = '5. ชิ้นส่วนโปเกมอนที่มอบให้จะถูกส่งผ่านทางอีเมลไปยังกล่องจดหมายของสมาชิกที่ได้รับ'
	},
	[45006] = {
		id = 45006,
		fmt = '6. การมอบชิ้นส่วนโปเกมอนที่มีคุณภาพต่างกันจะได้รับรางวัลเป็นจิตวิญญาณโปเกมอนและคะแนนความช่วยเหลือที่แตกต่างกัน'
	},
	[45007] = {
		id = 45007,
		fmt = '7. ทุกวันเวลา 5:00 น. รายการขอพรทั้งหมดจะถูกรีเซ็ต'
	},
	[46001] = {
		id = 46001,
		fmt = '#C0xFFF5D6#1. ทุกครั้งที่เข้าร่วมการแข่งขัน ผู้เล่นจะได้รับรางวัลกล่องสมบัติ'
	},
	[46002] = {
		id = 46002,
		fmt = '#C0xFFF5D6#2. ชนะจะได้รับกล่องทองคำ แพ้จะได้รับกล่องเงิน'
	},
	[46003] = {
		id = 46003,
		fmt = '#C0xFFF5D6#3. กล่องทั้งสองแบบมีโอกาสได้รับแหวน, เหรียญตรา และไอเทมอื่น ๆ'
	},
	[46004] = {
		id = 46004,
		fmt = '#C0xFFF5D6#4. อันดับของศึกเจ้าแห่งราชาจะได้รับรางวัลอันดับ ซึ่งรวมถึงเศษชิ้นส่วนแองเจิลมอนและไอเทมหายากอื่น ๆ'
	},
	[47001] = {
		id = 47001,
		fmt = '1. ฝังโลหะผสมลงในช่องเมทริกซ์ของโปเกมอนเพื่อรับค่าพลังจากโลหะผสม ช่องเมทริกซ์จะปลดล็อกตามระดับของทีม'
	},
	[47002] = {
		id = 47002,
		fmt = '2. วางโลหะผสมลงในช่องเมทริกซ์ตามประเภทที่กำหนดเพื่อเปิดใช้งานบัฟของเมทริกซ์ ซึ่งจะช่วยเพิ่มพลังให้โปเกมอนมากขึ้น'
	},
	[47003] = {
		id = 47003,
		fmt = '3. เอฟเฟกต์ของเมทริกซ์มีคุณภาพแตกต่างกัน หากโลหะผสมทั้งหมดในเมทริกซ์มีคุณภาพเดียวกัน เอฟเฟกต์เมทริกซ์จะเพิ่มขึ้นตามคุณภาพนั้น'
	},
	[47004] = {
		id = 47004,
		fmt = '4. เมื่อโปเกมอนเปิดใช้งานเอฟเฟกต์เมทริกซ์ และมีช่องเมทริกซ์ว่างอยู่ สามารถเลือกฝังโลหะผสมที่ชอบโดยไม่กระทบต่อเอฟเฟกต์ที่เปิดใช้งาน'
	},
	[47005] = {
		id = 47005,
		fmt = '5. โลหะผสมที่เหลือสามารถนำไปหลอมเป็นสารสกัดโลหะผสม และใช้สารสกัดนี้ในการเพิ่มระดับของโลหะผสมอื่น ๆ ได้'
	},
	[48001] = {
		id = 48001,
		fmt = 'ทำภารกิจรายวันในรายการให้ครบเพื่อรับคะแนนสะสม'
	},
	[48002] = {
		id = 48002,
		fmt = 'เมื่อสะสมคะแนนรายวันถึง 20, 40, 60, 80 และ 100 สามารถเปิดกล่องรางวัลสะสมได้'
	},
	[48003] = {
		id = 48003,
		fmt = 'ภารกิจบางอย่าง เช่น การออนไลน์สะสม, การใช้พลังงาน ฯลฯ สามารถทำได้เป็นช่วง และแต่ละช่วงจะได้รับคะแนนสะสมของตัวเอง'
	},
	[49001] = {
		id = 49001,
		fmt = '1. ในกล่องสมบัติพิเศษ ทุกครั้งที่เปิดกล่องจะได้รับ 10 คะแนน ซึ่งใช้จัดอันดับผู้เล่น'
	},
	[49002] = {
		id = 49002,
		fmt = '2. ทุกครั้งที่เปิดกล่องอุปกรณ์ 10 ครั้ง จะได้รับโลหะผสมตื่นรู้และกล่องเศษชิ้นส่วนเอนกประสงค์ (ไม่ออกเศษตื่นรู้)'
	},
	[49003] = {
		id = 49003,
		fmt = '3. กิจกรรมสิ้นสุดเวลา 21:30 ของวันสุดท้าย และไม่สามารถเปิดกล่องต่อได้ อันดับ 30 อันดับแรกจะได้รับรางวัลผ่านอีเมล'
	},
	[49004] = {
		id = 49004,
		fmt = '4. อันดับ 1 ต้องมีคะแนนอย่างน้อย 7000 แต้ม'
	},
	[49005] = {
		id = 49005,
		fmt = '5. อันดับ 2-3 ต้องมีคะแนนอย่างน้อย 5000 แต้ม'
	},
	[49006] = {
		id = 49006,
		fmt = '6. อันดับ 4-6 ต้องมีคะแนนอย่างน้อย 3500 แต้ม'
	},
	[49007] = {
		id = 49007,
		fmt = '7. อันดับ 7-10 ต้องมีคะแนนอย่างน้อย 2000 แต้ม'
	},
	[49008] = {
		id = 49008,
		fmt = '8. อันดับ 11-20 ต้องมีคะแนนอย่างน้อย 1000 แต้ม'
	},
	[49009] = {
		id = 49009,
		fmt = '9. หากคะแนนไม่ถึงเกณฑ์ที่กำหนด จะได้รับรางวัลตามคะแนนที่ทำได้เท่านั้น'
	},
	[50001] = {
		id = 50001,
		fmt = '1. ระหว่างกิจกรรม ทุกการเติมเงิน 6 หยวน จะได้รับค้อนสำหรับทุบไข่ทองคำ 1 อัน (สูงสุด 10 อันต่อวัน)'
	},
	[50002] = {
		id = 50002,
		fmt = '2. ในการทุบไข่ ต้องมีค้อนและคลิกไข่ที่ต้องการเพื่อรับรางวัล'
	},
	[50003] = {
		id = 50003,
		fmt = '3. แต่ละครั้งที่ทุบไข่ จะใช้ค้อน 1 อันและสกุลเงินในเกม (ขึ้นอยู่กับการตั้งค่า) มีโอกาสได้รับรางวัลคูณ 3, 6 หรือ 10 เท่า'
	},
	[50004] = {
		id = 50004,
		fmt = '4. หากได้รับรางวัล 10 เท่า ไข่จะถูกรีเซ็ตเป็น 3 ฟองใหม่ หากไม่ได้รางวัล 10 เท่า สามารถทุบต่อได้จนกว่าจะได้รับ'
	},
	[50005] = {
		id = 50005,
		fmt = '5. มีโอกาสได้รับรางวัล 10 เท่าตั้งแต่การทุบครั้งแรก แต่หากไม่สำเร็จ ระบบรับประกันว่าใน 3 ครั้งต้องมี 1 ครั้งได้ 10 เท่า'
	},
	[51001] = {
		id = 51001,
		fmt = '1. กิจกรรมบอสจำกัดเวลาเปิดให้ท้าทายบอสได้วันละ 3 ครั้ง ใช้หมดแล้วสามารถใช้เพชรซื้อเพิ่มได้ รีเซ็ตจำนวนครั้งเวลา 05:00 ทุกวัน'
	},
	[51002] = {
		id = 51002,
		fmt = '2. กระดานคะแนนจัดอันดับตามความเสียหายสูงสุดต่อครั้ง ไม่ใช่ความเสียหายรวม'
	},
	[51003] = {
		id = 51003,
		fmt = '3. ทุกการท้าทายจะได้รับเหรียญทองและไอเทมรางวัล'
	},
	[51004] = {
		id = 51004,
		fmt = '4. ทุกวันเวลา 05:00 กระดานคะแนนจะถูกรีเซ็ต และรางวัลจะถูกแจกตามอันดับ'
	},
	[51005] = {
		id = 51005,
		fmt = '5. บอสจำกัดเวลามีคุณสมบัติที่แตกต่างกัน ควรอ่านคำอธิบายก่อนท้าทาย'
	},
	[51006] = {
		id = 51006,
		fmt = '6. แนะนำให้เปิดฟังก์ชันขยายหน้าจอในระบบเมื่อท้าทายบอสจำกัดเวลา - โอเมกามอน'
	},
	[52001] = {
		id = 52001,
		fmt = 'แตะ (กดค้าง) บริเวณซ้ายหรือขวาของหน้าจอเพื่อควบคุมการเคลื่อนที่ของอากูมอนไปทางซ้ายหรือขวา'
	},
	[52002] = {
		id = 52002,
		fmt = 'ก่อนที่พลังชีวิตจะหมด ยิ่งลงไปในชั้นลึกมากเท่าไร โอกาสได้รับรางวัลยิ่งสูงขึ้น'
	},
	[52003] = {
		id = 52003,
		fmt = 'แตะ (กดค้าง) บริเวณซ้ายหรือขวาของหน้าจอเพื่อควบคุมการเคลื่อนที่ของโปเกมอนไปทางซ้ายหรือขวา'
	},
	[52004] = {
		id = 52004,
		fmt = 'ก่อนที่พลังชีวิตจะหมด ยิ่งลงไปในชั้นลึกมากเท่าไร โอกาสได้รับรางวัลยิ่งสูงขึ้น'
	},
	[53001] = {
		id = 53001,
		fmt = '1. ได้รับโปเกมอนที่กำหนดไว้จะเปิดใช้งานเอฟเฟกต์พันธะ'
	},
	[53002] = {
		id = 53002,
		fmt = '2. โปเกมอนรูปแบบวิวัฒนาการใด ๆ ในซีรีส์เดียวกันสามารถเปิดใช้งานพันธะได้'
	},
	[53003] = {
		id = 53003,
		fmt = '3. แม้โปเกมอนที่เกี่ยวข้องจะถูกแยกส่วน เอฟเฟกต์พันธะยังคงอยู่'
	},
	[54001] = {
		id = 54001,
		fmt = '1. ได้รับโปเกมอนที่กำหนดไว้จะเปิดใช้งานเอฟเฟกต์พันธะ'
	},
	[54002] = {
		id = 54002,
		fmt = '2. โปเกมอนรูปแบบวิวัฒนาการใด ๆ ในซีรีส์เดียวกันสามารถเปิดใช้งานพันธะได้'
	},
	[54003] = {
		id = 54003,
		fmt = '3. แม้โปเกมอนที่เกี่ยวข้องจะถูกแยกส่วน เอฟเฟกต์พันธะยังคงอยู่'
	},
	[55001] = {
		id = 55001,
		fmt = '1. กิจกรรมจัดอันดับพลังต่อสู้เปิดตั้งแต่วันที่ 1 เวลา 05:00 ถึงวันที่ 7 เวลา 21:30 โดยรางวัลจะถูกแจกตามพลังต่อสู้ของผู้เล่นในวันที่ 7 เวลา 21:30'
	},
	[55002] = {
		id = 55002,
		fmt = '2. รางวัลจัดอันดับแบ่งเป็นรางวัลอันดับและรางวัลพลังต่อสู้ ซึ่งจะถูกแจกทางอีเมลในวันที่ 7 เวลา 21:30'
	},
	[55003] = {
		id = 55003,
		fmt = '3. รางวัลพลังต่อสู้ขึ้นอยู่กับระดับพลังของผู้เล่นและจะไม่ได้รับซ้อนกัน'
	},
	[55004] = {
		id = 55004,
		fmt = '4. หากมีผู้เล่นที่มีพลังต่อสู้เท่ากัน จะจัดอันดับตามลำดับที่ถึงพลังนั้นก่อน'
	},
	[55005] = {
		id = 55005,
		fmt = '5. ผู้ที่ต้องการติด 1-10 อันดับแรก ต้องมีพลังต่อสู้อย่างน้อย 80000'
	},
	[56001] = {
		id = 56001,
		fmt = '1. คะแนนพรสวรรค์สามารถใช้ในการอัปเกรดสกิลพรสวรรค์'
	},
	[56002] = {
		id = 56002,
		fmt = '2. กล่องรางวัลด่านหลักสามารถให้คะแนนพรสวรรค์ได้'
	},
	[56003] = {
		id = 56003,
		fmt = '3. รางวัลอันดับในอารีน่าสามารถให้คะแนนพรสวรรค์ได้'
	},
	[56004] = {
		id = 56004,
		fmt = '4. กิจกรรมพิเศษบางอย่างอาจมีโอกาสได้รับคะแนนพรสวรรค์ รอติดตามกิจกรรม!'
	},
	[57001] = {
		id = 57001,
		fmt = '1. ด่านที่ผ่านครั้งแรกจะได้รับรางวัลครั้งแรก'
	},
	[57002] = {
		id = 57002,
		fmt = '2. รีเซ็ตด่านได้วันละครั้ง หากระดับ VIP สูงขึ้นจะได้รับโอกาสรีเซ็ตเพิ่ม รีเซ็ตเวลา 05:00 ทุกวัน'
	},
	[57003] = {
		id = 57003,
		fmt = '3. ด่านที่ผ่านไปแล้วไม่สามารถท้าทายซ้ำได้'
	},
	[57004] = {
		id = 57004,
		fmt = '4. ระบบออโต้เคลียร์สามารถเล่นได้ถึงด่านที่เคยผ่านมาก่อนหน้านี้และรับรางวัลตามนั้น'
	},
	[57005] = {
		id = 57005,
		fmt = '5. ด่านที่เลือกเล่นอาจมีเงื่อนไขพิเศษกำหนด'
	},
	[58001] = {
		id = 58001,
		fmt = '1. เทรนเนอร์สามารถใช้ระบบคืนชีพเพื่อรีเซ็ตโปเกมอนในกระเป๋ากลับสู่สภาพเริ่มต้น'
	},
	[58002] = {
		id = 58002,
		fmt = '2. เนื้อหาที่คืนชีพ ได้แก่ ระดับโปเกมอน, คุณภาพพัฒนา, ทักษะ และอุปกรณ์'
	},
	[58003] = {
		id = 58003,
		fmt = '3. หลังจากคืนชีพแล้ว จะได้รับทรัพยากรฝึกฝนคืน 100% ซึ่งสามารถนำไปใช้พัฒนาโปเกมอนตัวอื่นได้'
	},
	[58004] = {
		id = 58004,
		fmt = '4.การเกิดใหม่ของโปเกมอนต้องใช้เพชร ยิ่งโปเกมอนเป้าหมายได้รับการพัฒนามาก การใช้เพชรจะยิ่งเพิ่มขึ้น；ขีดจำกัดการใช้เพชรสูงสุดคือ 100#Icommon/icon/icon_diamond.png-56-56#'
	},
	[58005] = {
		id = 58005,
		fmt = '5.โปเกมอนที่ไม่เคยได้รับการเพิ่มระดับ เลื่อนขั้นคุณภาพ เพิ่มระดับสกิล หรือเพิ่มระดับอุปกรณ์เสริมใด ๆ จะไม่สามารถเกิดใหม่ได้ และจะไม่ปรากฏในหน้าต่างเลือกโปเกมอนสำหรับเกิดใหม่'
	},
	[59001] = {
		id = 59001,
		fmt = '1.《คู่มือพัฒนาโปเกเด็กซ์แห่งชาติ》ข้อแรก：\nโปเกมอนนับร้อยนับพัน การแยกสลายคือหยาดน้ำตา โปรดใช้คู่หูโปเกมอนของคุณให้ดี^_^'
	},
	[59002] = {
		id = 59002,
		fmt = '2.เทรนเนอร์สามารถใช้ระบบแยกสลายเพื่อแปลงโปเกมอนที่ไม่ได้ใช้งานในกระเป๋าเป็นหินวิญญาณโปเกมอน；โปเกมอนที่อยู่ในทีม อยู่ระหว่างการฝึกในกิลด์ หรือถูกล็อกจะไม่สามารถแยกสลายได้'
	},
	[59003] = {
		id = 59003,
		fmt = '3.แต่ละครั้งสามารถเลือกโปเกมอนเพื่อแยกสลายได้สูงสุด 5 ตัวพร้อมกัน'
	},
	[59004] = {
		id = 59004,
		fmt = '4.เนื้อหาของการแยกสลายโปเกมอน รวมถึง：การเกิดใหม่ของโปเกมอน（จะคืนทรัพยากรที่ใช้ในการเกิดใหม่）และการได้รับหินวิญญาณโปเกมอนจากการแยกสลาย'
	},
	[59005] = {
		id = 59005,
		fmt = '5.การแยกสลายโปเกมอนต้องใช้เพชร โดยจะใช้เพชรเท่ากับจำนวนที่ต้องใช้ในการเกิดใหม่ของโปเกมอนที่เลือก；สูงสุดไม่เกิน 100#Icommon/icon/icon_diamond.png-56-56# ต่อโปเกมอน 1 ตัว'
	},
	[59006] = {
		id = 59006,
		fmt = '6.หินวิญญาณโปเกมอนที่ได้รับจากการแยกสลายสามารถนำไปแลกเปลี่ยนเป็นไอเทมหายากและชิ้นส่วนโปเกมอนได้ที่ร้านค้าชิ้นส่วน'
	},
	[60001] = {
		id = 60001,
		fmt = '1.เทรนเนอร์สามารถใช้ระบบเกิดใหม่ของไอเทมพกพาเพื่อนำไอเทมพกพาในกระเป๋ากลับสู่สถานะเริ่มต้น'
	},
	[60002] = {
		id = 60002,
		fmt = '2.เนื้อหาของการเกิดใหม่ของไอเทมพกพารวมถึง：ระดับการเสริมแกร่งของไอเทมและระดับการพัฒนาไอเทม'
	},
	[60003] = {
		id = 60003,
		fmt = '3.หลังจากการเกิดใหม่ของไอเทมพกพา จะได้รับทรัพยากรการเสริมแกร่งคืน 100% และไอเทมพกพาแบบเดียวกัน'
	},
	[60004] = {
		id = 60004,
		fmt = '4.การเกิดใหม่ของไอเทมพกพาต้องใช้เพชร โดยยิ่งไอเทมที่เกิดใหม่ได้รับการพัฒนามากเท่าไหร่ การใช้เพชรก็จะยิ่งมากขึ้น ขีดจำกัดการใช้เพชรคือ 50#Icommon/icon/icon_diamond.png-56-56#'
	},
	[61001] = {
		id = 61001,
		fmt = '1.การมอบของขวัญสามารถเพิ่มระดับความสนิทสนมได้'
	},
	[61002] = {
		id = 61002,
		fmt = '2.ทุกครั้งที่ระดับความสนิทสนมเพิ่มขึ้น 1 ระดับจะช่วยเพิ่มค่าพลังพื้นฐาน'
	},
	[61003] = {
		id = 61003,
		fmt = '3.เมื่อระดับความสนิทสนมถึงระดับที่กำหนด จะปลดล็อกความสามารถพิเศษ'
	},
	[61004] = {
		id = 61004,
		fmt = '4.ความสนิทสนมจะถูกแชร์ให้กับโปเกมอนที่อยู่ในสายวิวัฒนาการเดียวกัน'
	},
	[61005] = {
		id = 61005,
		fmt = '5.การใช้ปุ่ม【อัปเกรดอัตโนมัติ】จะใช้ของขวัญความสนิทสนมที่มีอยู่ทั้งหมด'
	},
	[61006] = {
		id = 61006,
		fmt = '6.การใช้ปุ่ม【อัปเกรดด่วน】สามารถเลือกระดับที่ต้องการเพิ่ม และใช้ของขวัญความสนิทสนมตามที่เลือก'
	},
	[62001] = {
		id = 62001,
		fmt = '1.ทุกวันระบบจะสุ่มคุณสมบัติ 4 ประเภท และในแต่ละประเภทจะสุ่มสร้างเป้าหมายโปเกมอน 3 ตัว ผู้เล่นสามารถเลือกหนึ่งในคุณสมบัติธาตุและเลือกโปเกมอนเป้าหมายเพื่อท้าทายได้ โดยสามารถท้าทายได้วันละ 3 ครั้ง และทุกครั้งที่ท้าทายสำเร็จจะได้รับรางวัล รวมสูงสุด 3 ครั้ง'
	},
	[62002] = {
		id = 62002,
		fmt = '2.ผู้เล่นสามารถสร้างห้องหรือเข้าร่วมห้องของคุณสมบัติธาตุที่เลือกได้อย่างรวดเร็ว หากโปเกมอนเป้าหมายของคุณสมบัติธาตุที่เลือกยังไม่ได้ถูกปลดล็อก จะไม่สามารถเข้าร่วมได้'
	},
	[62003] = {
		id = 62003,
		fmt = '3.หลังจากสร้างหรือเข้าร่วมห้องแล้ว หากผู้เล่นได้ทำการต่อสู้แล้วจะไม่สามารถออกจากห้องได้ และเมื่อมีการรีเซ็ตในวันถัดไป ห้องจะถูกยุบโดยอัตโนมัติ และผู้เล่นจะถูกนำออกจากห้อง'
	},
	[62004] = {
		id = 62004,
		fmt = '4.ในระหว่างเข้าสู่หน้าจอบุฟเฟอร์การต่อสู้ ผู้เล่นสามารถควบคุมการจัดตำแหน่งของโปเกมอนของผู้เล่นคนอื่นได้'
	},
	[62005] = {
		id = 62005,
		fmt = '5.การต่อสู้ระหว่างผู้เล่นเป็นอิสระต่อกันและจะไม่มีผลกระทบซึ่งกันและกัน'
	},
	[62006] = {
		id = 62006,
		fmt = '6.ผู้เล่นสามารถเปลี่ยนโปเกมอนที่ใช้ต่อสู้ได้ตลอดเวลา แม้จะทำการท้าทายสำเร็จแล้วก็สามารถเปลี่ยนได้'
	},
	[62007] = {
		id = 62007,
		fmt = '7.เมื่อมีผู้เล่น 3 คน, 4 คน และ 5 คน ทำการท้าทายสำเร็จ จะได้รับรางวัลเป้าหมายพิเศษ โดยมีเงื่อนไขว่าผู้เล่นจะต้องทำการท้าทายสำเร็จก่อน'
	},
	[62008] = {
		id = 62008,
		fmt = '8.เวลา 12:00 ของทุกวันจะมีการรีเซ็ตสิทธิ์ในการท้าทายและสถานะของห้อง'
	},
	[62009] = {
		id = 62009,
		fmt = '9.เมื่อเข้าร่วมห้องท้าทายครบ 2 ชั่วโมง หรือในช่วงเวลา 06:00-11:59 ของทุกวัน ผู้เล่นสามารถเช่ายืมสมาชิกทีมระดับสูงได้ฟรี หากทีมเต็มแล้วจะไม่สามารถเช่ายืมเพิ่มได้'
	},
	[62010] = {
		id = 62010,
		fmt = '10.สมาชิกทีมระดับสูงถือเป็นสมาชิกที่ไม่เป็นทางการ ดังนั้นในห้องจะไม่แสดงอวาตาร์หรือข้อมูลอื่นๆ สามารถดูได้เฉพาะในหน้าจอการจัดทีมเท่านั้น'
	},
	[63001] = {
		id = 63001,
		fmt = '1. การทำภารกิจประจำวันของบัตรผ่านจะได้รับค่าประสบการณ์สำหรับบัตรผ่านเพื่ออัปเกรดบัตรผ่าน'
	},
	[63002] = {
		id = 63002,
		fmt = '2. หลังจากบัตรผ่านอัปเกรดแล้วจะได้รับรางวัลตามระดับที่กำหนด'
	},
	[63003] = {
		id = 63003,
		fmt = '3. ภารกิจประจำวันจะรีเฟรชทุกวันในเวลา 5 โมงของวันถัดไป'
	},
	[63004] = {
		id = 63004,
		fmt = '4. ภารกิจประจำสัปดาห์จะรีเฟรชทุกวันจันทร์เวลา 5 โมง'
	},
	[63005] = {
		id = 63005,
		fmt = '5. ผู้เล่นสามารถซื้อ #C0xF76B45##F48#บัตรผ่านระดับอาจารย์#C0x5b545b##F40# เพื่อรับรางวัลเพิ่มเติม'
	},
	[63006] = {
		id = 63006,
		fmt = '6. ภายในช่วงกิจกรรม, บัตรผ่านระดับอาจารย์และแพ็คเกจทองของบัตรผ่านระดับอาจารย์สามารถซื้อได้เพียงเลือกระหว่างสองอย่างและจำกัดซื้อเพียง 1 ครั้งเท่านั้น, #C0xF76B45##F48#การคลิกปุ่มราคาทันที#C0x5b545b##F40# จะนับว่าซื้อสำเร็จ'
	},
	[64001] = {
		id = 64001,
		fmt = '1. ผู้เล่นจะมีโอกาสสุ่มฟรีหนึ่งครั้งทุกวัน, เวลารีเซ็ตคือเวลา 5 โมงของวันถัดไป'
	},
	[64002] = {
		id = 64002,
		fmt = '2. หลังจากแต่ละครั้งที่สุ่ม, ผู้เล่นจะได้รับคะแนนที่สอดคล้อง, และจะมีการจัดอันดับตามคะแนนของผู้เล่น'
	},
	[64003] = {
		id = 64003,
		fmt = '3. การจัดอันดับคะแนนของผู้เล่นจะได้รับการอัปเดตแบบเรียลไทม์'
	},
	[64004] = {
		id = 64004,
		fmt = '4. เมื่อคะแนนของผู้เล่นเท่ากัน, จะจัดอันดับตามลำดับเวลาที่ได้คะแนนนั้น, โดยผู้ที่ได้ก่อนจะอยู่ด้านหน้า'
	},
	[64005] = {
		id = 64005,
		fmt = '5. การจัดอันดับจะแสดงผู้เล่น 30 อันดับแรก'
	},
	[65001] = {
		id = 65001,
		fmt = '1. เมื่อผู้เล่นได้คะแนนตามที่กำหนดแล้วสามารถรับรางวัลคะแนน, โดยแต่ละระดับของคะแนนสามารถรับได้เพียงครั้งเดียว'
	},
	[65002] = {
		id = 65002,
		fmt = '2. กิจกรรมจะมีการสรุปรางวัลที่เวลา 21:30 ของวันสุดท้าย'
	},
	[65003] = {
		id = 65003,
		fmt = '3. เมื่อสิ้นสุดกิจกรรม, ระบบจะส่งรางวัลตามอันดับคะแนนผ่านทางอีเมล'
	},
	[65004] = {
		id = 65004,
		fmt = '4. รางวัลอันดับจะถูกแจกจ่ายตามคะแนนและอันดับของผู้เล่น, หากผู้เล่นไม่ได้คะแนนตามข้อกำหนดของอันดับที่กำหนดจะได้รับรางวัลตามระดับคะแนนที่ตรงกับตนเอง'
	},
	[66001] = {
		id = 66001,
		fmt = '1. การทำภารกิจประจำวันจะได้รับเหรียญสิทธิพิเศษ'
	},
	[66002] = {
		id = 66002,
		fmt = '2. รางวัลรายวันของบัตรเดือนจะได้รับเหรียญสิทธิพิเศษ'
	},
	[66003] = {
		id = 66003,
		fmt = '3. เหรียญสิทธิพิเศษสามารถใช้ในการอัปเกรดทักษะสิทธิพิเศษ'
	},
	[66004] = {
		id = 66004,
		fmt = '4. นอกจากนี้ยังมีโอกาสได้รับเหรียญสิทธิพิเศษในกิจกรรมส่งเสริมการดำเนินงานปกติ, กรุณาติดตามข่าวสาร'
	},
	[67001] = {
		id = 67001,
		fmt = '1. ส่วนประกอบของเครื่องสำรวจสามารถอัปเกรดได้, โดยการอัปเกรดแต่ละครั้งจะใช้วัสดุที่เกี่ยวข้อง'
	},
	[67002] = {
		id = 67002,
		fmt = '2. เมื่อส่วนประกอบทั้งหมดของเครื่องสำรวจตัวเดียวได้รับการเปิดใช้งาน, เครื่องสำรวจสามารถถูกเปิดใช้งานได้'
	},
	[67003] = {
		id = 67003,
		fmt = '3. สำหรับเครื่องสำรวจขั้นสูง, ระดับของส่วนประกอบต้องตรงกับระดับของเครื่องสำรวจที่อัปเกรด'
	},
	[67004] = {
		id = 67004,
		fmt = '4. ผู้เล่นสามารถแยกส่วนประกอบที่เกินมาออกเพื่อรับเหรียญล่าสมบัติ'
	},
	[67005] = {
		id = 67005,
		fmt = '5. เหรียญล่าสมบัติสามารถใช้ซื้อสินค้าในร้านค้าสำรวจ'
	},
	[67006] = {
		id = 67006,
		fmt = '6. ผู้เล่นมีโอกาสล่าสมบัติฟรีหนึ่งครั้งต่อวัน'
	},
	[67007] = {
		id = 67007,
		fmt = '7. คุณสมบัติของเครื่องสำรวจจะได้รับการปรับแก้ในงานประชุมควอตซ์'
	},
	[68001] = {
		id = 68001,
		fmt = '1. การทำภารกิจให้เสร็จทุกวันจะได้รับจำนวนครั้งในการสุ่ม'
	},
	[68002] = {
		id = 68002,
		fmt = '2. จำนวนครั้งในการสุ่มที่ได้รับในแต่ละวันมีขีดจำกัด'
	},
	[68003] = {
		id = 68003,
		fmt = '3. การสุ่มจะได้รับรางวัล 100%'
	},
	[68004] = {
		id = 68004,
		fmt = '4. เวลา 5 โมงของวันถัดไปจะรีเซ็ตโอกาสในการสุ่มที่ได้รับจากการทำภารกิจและจำนวนครั้งฟรี'
	},
	[68005] = {
		id = 68005,
		fmt = '5. จำนวนครั้งในการสุ่มสามารถสะสมและใช้ได้'
	},
	[68006] = {
		id = 68006,
