		fmt = '5. สำหรับทุกครั้งที่ทายถูก ผู้เล่นจะได้รับรางวัลคืนตามอัตราต่อรอง แต่ถ้าทายผิดจะได้รับคืนเพียงครึ่งหนึ่งของจำนวนเงินเดิมพัน'
	},
	[82006] = {
		id = 82006,
		fmt = '6. อัตราต่อรองจะปรับเปลี่ยนตามจำนวนผู้ที่วางเดิมพัน'
	},
	[82007] = {
		id = 82007,
		fmt = '7. การทายผู้เข้าสู่รอบ 4 ทีมไม่สามารถซ้ำกับการทายแชมป์ได้'
	},
	[82008] = {
		id = 82008,
		fmt = '8. จำนวนเงินเหรียญทองมีจำกัดสูงสุด 1,500,000 เหรียญ และเหรียญแทนมีจำกัดสูงสุด 1,500 เหรียญ'
	},
	[83001] = {
		id = 83001,
		fmt = '1. ในส่วนของการคืนชาติกับหินเวทย์ ผู้เล่นสามารถรีเซ็ตหินเวทย์ที่เคยฝึกฝนแล้วกลับสู่สถานะเริ่มต้น'
	},
	[83002] = {
		id = 83002,
		fmt = '2. การคืนชาติกับหินเวทย์รวมถึง: การเสริมพลังหินเวทย์'
	},
	[83003] = {
		id = 83003,
		fmt = '3. หลังจากคืนชาติกับหินเวทย์แล้ว จะคืนทรัพยากรการฝึกฝน 100% เพื่อให้สามารถใช้ฝึกหินเวทย์อื่นได้อีกครั้ง'
	},
	[83004] = {
		id = 83004,
		fmt = '4. การคืนชาติกับหินเวทย์ต้องใช้เพชร และหินเวทย์ที่มีระดับการฝึกฝนสูงจะต้องใช้เพชรมากขึ้น; การใช้เพชรในการคืนชาติกับหินเวทย์แต่ละอันมีจำกัดสูงสุดที่ 10#Icommon/icon/icon_diamond.png-56-56#'
	},
	[83005] = {
		id = 83005,
		fmt = '5. หินเวทย์ที่ยังไม่ถูกฝึกฝนไม่สามารถทำการคืนชาติกับได้ และจะไม่ปรากฏในหน้าหินเวทย์ที่เลือกคืนชาติกับ'
	},
	[84001] = {
		id = 84001,
		fmt = '1. เทรนเนอร์สามารถแยกหินเวทย์ส่วนเกินได้โดยไม่เสียค่าใช้จ่ายในส่วนของการแยกหินเวทย์'
	},
	[84002] = {
		id = 84002,
		fmt = '2. สำหรับหินเวทย์ที่ถูกฝึกฝนแล้ว หลังจากแยกจะคืนวัสดุเสริมพลังและเหรียญทองที่ใช้ไป 100%'
	},
	[84003] = {
		id = 84003,
		fmt = '3. หินเวทย์ที่ถูกฝังอยู่นั้นไม่สามารถแยกได้ และไม่สามารถดูได้ในส่วนของการแยกหินเวทย์'
	},
	[84004] = {
		id = 84004,
		fmt = '4. ในการแยกแต่ละครั้ง สามารถเลือกหลายอันพร้อมกันโดยแบ่งตามคุณภาพ หรือกดค้างเพื่อเลือกหลายอัน'
	},
	[84005] = {
		id = 84005,
		fmt = '5. หลังจากแยกหินเวทย์แล้ว จะได้รับวัสดุเสริมพลังหินเวทย์ ซึ่งสามารถใช้ในการเสริมพลังหินเวทย์อื่นได้'
	},
	[85001] = {
		id = 85001,
		fmt = '1. ในช่วงเวลากิจกรรม ผู้เล่นสามารถนำสัตว์เลี้ยงนำทัพท้าชิง BOSS โลก'
	},
	[85002] = {
		id = 85002,
		fmt = '2. ในแต่ละรอบของการท้าชิง BOSS โลก จะบันทึกปริมาณความเสียหายของผู้เล่น เมื่อทำได้ตามเป้าหมายความเสียหาย ผู้เล่นจะได้รับรางวัลจากกล่องของรางวัลทันทีหลังจบรอบ'
	},
	[85003] = {
		id = 85003,
		fmt = '3. BOSS โลกจะบันทึกค่าความเสียหายรวมสูงสุดของผู้เล่นทั่วเซิร์ฟเวอร์ เมื่อบรรลุเป้าหมาย ผู้เล่นที่เข้าร่วมกิจกรรมในวันนั้นจะได้รับรางวัลจากกล่อง รางวัลจะถูกส่งผ่านอีเมลในเวลา 5 โมงของวันถัดไป และข้อมูลความเสียหายสะสมจะถูกรีเซ็ต'
	},
	[85004] = {
		id = 85004,
		fmt = '4. BOSS โลกมีจำนวนครั้งท้าชิงฟรี และสามารถซื้อเพิ่มได้ เมื่อจำนวนครั้งถึงขีดจำกัดในวันนั้น จะไม่สามารถต่อสู้ได้อีกในวันนั้น จำนวนครั้งจะรีเซ็ตเวลา 5 โมงของวันถัดไป'
	},
	[85005] = {
		id = 85005,
		fmt = '5. ความเสียหายสูงสุดที่ผู้เล่นทำได้ในแต่ละรอบท้าชิง BOSS โลกในวันนั้นจะถูกบันทึกในอันดับส่วนบุคคลและอันดับของสโมสร โดยอันดับและข้อมูลความเสียหายจะถูกรีเซ็ตเวลา 5 โมงของวันถัดไป'
	},
	[85006] = {
		id = 85006,
		fmt = '6. ผู้เล่นและสโมสรที่ติดอันดับจะได้รับรางวัลตามอันดับ สามารถดูตัวอย่างรางวัลได้โดยคลิกปุ่มรางวัลอันดับ รางวัลจะถูกส่งผ่านอีเมลในเวลา 5 โมงของวันถัดไป'
	},
	[85007] = {
		id = 85007,
		fmt = '7. ผู้เล่นที่ไม่ได้เข้าร่วมสโมสรจะไม่เข้าร่วมอันดับสโมสร หากเข้าร่วมสโมสรก่อนข้อมูลรีเซ็ต จะบันทึกเฉพาะข้อมูลการท้าชิง BOSS โลกหลังจากเข้าร่วมสโมสรใหม่เท่านั้น'
	},
	[85008] = {
		id = 85008,
		fmt = '8. หากผู้เล่นที่อยู่ในสโมสรแล้วเข้าไปต่อสู้กับ BOSS โลกแล้วออกจากสโมสร และเข้าร่วมสโมสรอีกครั้งก่อนข้อมูลรีเซ็ต ข้อมูลความเสียหายของผู้เล่นจะไม่ถูกบันทึกในสโมสรใหม่'
	},
	[86001] = {
		id = 86001,
		fmt = '1. ในสนามแข่งขันข้ามเซิร์ฟเวอร์ต้องรอการจับคู่ระหว่างเซิร์ฟเวอร์ เมื่อจับคู่สำเร็จแล้ว สถานะ  #C0xF76B45#จับคู่สำเร็จ รอเริ่มการแข่งขัน#C0x5B545B#  จะแสดงบนหน้าจอ'
	},
	[86002] = {
		id = 86002,
		fmt = '2. กระบวนการของฤดูกาล:  #C0xF76B45#เริ่มฤดูกาล (14 วันสองสัปดาห์) —— สิ้นสุดฤดูกาล, ผู้เล่นจะแสดงผล (ต่อเนื่อง 5 วัน) —— เตรียมเริ่มการแข่งขัน (ประกาศล่วงหน้า 2 วัน) '
	},
	[86003] = {
		id = 86003,
		fmt = '3. ในช่วงฤดูกาลมีการคำนวณอันดับ 2 ครั้ง คือในวันที่ 7 ของฤดูกาลเวลา 22:00 สำหรับการคำนวณระยะกลาง และวันที่ 14 เวลา 22:00 สำหรับการคำนวณสิ้นสุดฤดูกาล'
	},
	[86004] = {
		id = 86004,
		fmt = '4. ในช่วงฤดูกาล มีจำนวนครั้งท้าชิงฟรีทุกวัน และสามารถซื้อเพิ่มได้ด้วยเพชร โดยจำนวนครั้งจะรีเซ็ตเวลา 5 โมงของทุกวัน'
	},
	[86005] = {
		id = 86005,
		fmt = '5. ผู้เล่นสามารถรีเฟรชคู่ต่อสู้ที่สามารถท้าชิงได้ด้วยตนเอง โดยมีจำนวนครั้งรีเฟรชฟรี เมื่อจำนวนครั้งฟรีหมดแล้ว ต้องใช้เหรียญทองในการรีเฟรช จำนวนครั้งรีเฟรชฟรีจะรีเซ็ตเวลา 5 โมงของทุกวัน'
	},
	[86006] = {
		id = 86006,
		fmt = '6. ในช่วงฤดูกาลมีการแสดงระดับใหญ่และระดับย่อย โดยระดับใหญ่จะเรียงตาม  #C0xF76B45#ทองแดง—เงิน—ทอง—แพลตตินัม—เพชร—เซียนผู้กล้าหาญ—ราชาแห่งสุดยอด#C0x5B545B#  จากน้อยไปมาก ส่วนระดับย่อยจะเรียงตามตัวเลข โดยตัวเลขที่น้อยกว่าจะอยู่บนสุด (สำหรับ เซียนผู้กล้าหาญ และ ราชาแห่งสุดยอด จะไม่มีระดับย่อย)'
	},
	[86007] = {
		id = 86007,
		fmt = '7. ในแต่ละระดับย่อยจะมีการจัดอันดับ โดยแต่ละอันดับมีจำนวนที่จำกัด ผู้เทรนเนอร์ทุกคนจะถูกจัดอันดับรวมตามระดับใหญ่และอันดับในระดับย่อย (สำหรับผู้ที่ไม่มีระดับย่อยจะถูกจัดอันดับตามระดับใหญ่)'
	},
	[86008] = {
		id = 86008,
		fmt = '8. ในส่วนข้อมูลการแข่งขัน สามารถดูวิดีโอการแข่งขันระหว่างผู้เล่นระดับสูงในช่วงเวลาล่าสุดได้'
	},
	[87001] = {
		id = 87001,
		fmt = '1. ก่อนการแข่งขัน ผู้เล่นสามารถจัดวางทีมได้ 2 ทีม โดยจำนวนสัตว์เลี้ยงที่ขึ้นสนามต้องไม่น้อยกว่า 2 และไม่เกิน 12 ตัว'
	},
	[87002] = {
		id = 87002,
		fmt = '2. การต่อสู้จะเป็นแบบ 6 ต่อ 6 แบบหมุนเวียน สูงสุด 3 รอบ โดยทีมที่ชนะในรอบแรกจะรักษาสถานะปัจจุบันและท้าชิงทีมถัดไปของฝ่ายตรงข้าม'
	},
	[87003] = {
		id = 87003,
		fmt = '3. หากสัตว์เลี้ยงทั้ง 2 ทีมของฝ่ายใดแพ้หมด จะถือว่าฝ่ายนั้นแพ้ แต่ถ้ารอบจบแล้วยังไม่ชัดเจน ผู้ที่มีพลังชีวิตรวมสูงกว่าจะเป็นผู้ชนะ'
	},
	[87004] = {
		id = 87004,
		fmt = '4. รูปแบบการต่อสู้ในสนามแข่งขันข้ามเซิร์ฟเวอร์คือ  #C0xF76B45#การต่อสู้แบบอัตโนมัติที่ล็อคเป้าหมาย#C0x5B545B#'
	},
	[87005] = {
		id = 87005,
		fmt = '5. หากผู้เล่นท้าชิงฝ่ายตรงข้ามด้วยตนเองและชนะ จะสลับอันดับกับฝ่ายตรงข้าม แต่ถ้าแพ้ อันดับจะไม่เปลี่ยนแปลง'
	},
	[87006] = {
		id = 87006,
		fmt = '6. เมื่อฝ่ายตรงข้ามท้าชิงผู้เล่นด้วยตนเอง จะส่งทีมป้องกันของผู้เล่นมาเผชิญหน้า การเปลี่ยนแปลงอันดับจะเป็นไปตามที่กล่าวไว้ในข้อก่อนหน้า'
	},
	[88001] = {
		id = 88001,
		fmt = '1. หลังจากทำภารกิจครบจำนวนที่กำหนดในแต่ละวัน ผู้เล่นสามารถรับรางวัลได้ด้วยตนเองในแท็บ  รางวัลรายวันในสนามแข่งขัน  โดยภารกิจจะรีเซ็ตเวลา 5 โมงของทุกวัน'
	},
	[88002] = {
		id = 88002,
		fmt = '2. เมื่อบันทึกระดับสูงสุดมีการอัปเดต ผู้เล่นสามารถรับรางวัลได้ด้วยตนเองในแท็บ  รางวัลระดับในสนามแข่งขัน  โดยรางวัลนี้จะรีเซ็ตหลังจบฤดูกาลแต่ละครั้ง'
	},
	[88003] = {
		id = 88003,
		fmt = '3. ในช่วงฤดูกาลที่มีการคำนวณอันดับ 2 ครั้ง รางวัลจะถูกแจกผ่านอีเมลตามระดับ รายละเอียดรางวัลสามารถดูได้ในแท็บ  รางวัล 7 วันในฤดูกาล  และ  รางวัลสิ้นสุดฤดูกาล'
	},
	[89001] = {
		id = 89001,
		fmt = '1. การแลกเปลี่ยนความสัมพันธ์ต้องมีเงื่อนไขจำกัดบางประการ\n เงื่อนไข①: สัตว์เลี้ยงของทั้งสองฝ่ายในรูปแบบเริ่มต้นต้องมีความหายากเดียวกัน\n เงื่อนไข②: วัสดุที่ใช้ในการฝึกฝนความสัมพันธ์ของทั้งสองฝ่ายต้องเหมือนกัน'
	},
	[89002] = {
		id = 89002,
		fmt = '2. ในการแลกเปลี่ยนความสัมพันธ์ เพียงแค่สัตว์เลี้ยงที่ตรงตามเงื่อนไขในแคตาล็อกถูกเปิดใช้งานแล้ว ก็สามารถแลกเปลี่ยนได้ แม้ในกระเป๋าจะไม่มีสัตว์เลี้ยงที่ตรงกัน'
	},
	[90001] = {
		id = 90001,
		fmt = '1. ในแต่ละรอบของกิจกรรม ประเภทหินเวทย์ที่อัปเกรดแบบจำกัดจะมีการเปลี่ยนแปลง'
	},
	[90002] = {
		id = 90002,
		fmt = '2. ทุกวันมีโอกาสสุ่มแบบจำกัดฟรีหนึ่งครั้ง จำนวนครั้งฟรีจะรีเซ็ตเวลา 5 โมงของวันถัดไป'
	},
	[90003] = {
		id = 90003,
		fmt = '3. จำนวนครั้งในการสุ่มในแต่ละวันมีข้อจำกัด โดยไม่รวมจำนวนครั้งสุ่มฟรี'
	},
	[91001] = {
		id = 91001,
		fmt = '1. จำนวนครั้งในการแลกเปลี่ยนหินเวทย์ในกิจกรรมจำกัดแต่ละรอบจะมีข้อจำกัด เมื่อเกินจำนวนที่กำหนดแล้ว จะไม่สามารถแลกเปลี่ยนได้อีกในช่วงเวลาของกิจกรรมรอบนี้'
	},
	[91002] = {
		id = 91002,
		fmt = '2. การแลกเปลี่ยนหินเวทย์จำกัดเฉพาะหินเวทย์สีม่วงและสีที่สูงกว่า และต้องเป็นหินเวทย์ที่มีคุณภาพเดียวกัน'
	},
	[91003] = {
		id = 91003,
		fmt = '3. การแลกเปลี่ยนหินเวทย์ต้องใช้หินเวทย์คุณภาพเดียวกันอย่างน้อย 2 หรือ 3 อัน; #C0xF76B45##L10# ใช้หินเวทย์คุณภาพเดียวกัน 2 อันแลกเปลี่ยนได้เพียง 1 อันใหม่ในคุณภาพเดียวกัน, ใช้ 3 อันแลกเปลี่ยนได้ 2 อันใหม่ในคุณภาพเดียวกัน'
	},
	[91004] = {
		id = 91004,
		fmt = '4. มี 3 วิธีในการแลกเปลี่ยนหินเวทย์:'
	},
	[91005] = {
		id = 91005,
		fmt = '① เมื่อทั้ง [ประเภทจำกัด] และ [หมายเลขจำกัด] ไม่ถูกเลือก การแลกเปลี่ยนแบบสุ่มจะเกิดขึ้นภายในคุณภาพเดียวกันโดยมีค่าเท่ากัน'
	},
	[91006] = {
		id = 91006,
		fmt = '② เมื่อเลือก [ประเภทจำกัด] จะทำการแลกเปลี่ยนแบบสุ่มระหว่างคุณภาพเดียวกันและประเภทเดียวกันเท่านั้น'
	},
	[91007] = {
		id = 91007,
		fmt = '③ เมื่อเลือก [หมายเลขจำกัด] จะทำการแลกเปลี่ยนแบบสุ่มระหว่างคุณภาพเดียวกันและหมายเลขเดียวกันเท่านั้น'
	},
	[91008] = {
		id = 91008,
		fmt = '5. สามารถเลือกได้เพียงหนึ่งใน [ประเภทจำกัด] หรือ [หมายเลขจำกัด] เท่านั้น'
	},
	[91009] = {
		id = 91009,
		fmt = '6. การแลกเปลี่ยนสัญลักษณ์จะใช้เพชร การแลกเปลี่ยนหลายครั้งจะใช้เพชรมากขึ้น; ยิ่งเลือกแลกเปลี่ยนสัญลักษณ์ที่มีคุณภาพสูงขึ้นจะใช้เพชรมากขึ้น'
	},
	[91010] = {
		id = 91010,
		fmt = '7. เมื่อเลือกแลกเปลี่ยนสัญลักษณ์ที่ได้รับการเสริมแกร่งแล้ว วัสดุเสริมแกร่งที่ตรงกับระดับการเสริมแกร่งจะได้รับการคืนโดยไม่คิดค่าใช้จ่าย'
	},
	[91011] = {
		id = 91011,
		fmt = '8. ในหน้าจอการแลกเปลี่ยนสัญลักษณ์ จะแสดงเฉพาะสัญลักษณ์ที่มีคุณภาพไม่ต่ำกว่าระดับสีม่วงและไม่ได้ฝังอยู่ในภูต ภูตที่มีสัญลักษณ์ฝังอยู่แล้วจะไม่แสดง'
	},
	[92001] = {
		id = 92001,
		fmt = '1. ในระหว่างกิจกรรม ผู้เล่นสามารถใช้ชุดวัตถุดิบที่สะสมในกิจกรรม  ข้าวหลามหอม  เพื่อทำข้าวหลาม'
	},
	[92002] = {
		id = 92002,
		fmt = '2. วัตถุดิบจะมีสองประเภท ได้แก่ วัตถุดิบหลักและวัตถุดิบเสริม โดยการใช้ #C0xF76B45#กล่องของขวัญวัตถุดิบข้าวหลาม#C0x5B545B# สามารถสุ่มรับวัตถุดิบได้ สำหรับกิจกรรมที่มีระยะเวลาจำกัด #C0xF76B45#ผู้เล่นสามารถได้รับวัตถุดิบจากการล็อกอินติดต่อกันและทำภารกิจได้'
	},
	[92003] = {
		id = 92003,
		fmt = '3. ในการทำข้าวหลาม ต้องใส่วัตถุดิบหลักและวัตถุดิบเสริมพร้อมกัน หากขาดอย่างใดอย่างหนึ่ง จะไม่สามารถทำข้าวหลามได้'
	},
	[92004] = {
		id = 92004,
		fmt = '4. ผู้เล่นสามารถเลือกวัตถุดิบหลักและเสริมได้ตามต้องการ #C0xF76B45#เพื่อทำข้าวหลามรสชาติที่แตกต่างกัน #C0x5B545B#'
	},
	[92005] = {
		id = 92005,
		fmt = '5. เมื่อได้รับข้าวหลามแล้ว ผู้เล่นสามารถใช้งานในหน้ากิจกรรมหรือในกระเป๋าได้ โดยทั้งวัตถุดิบและข้าวหลามจะมีระยะเวลาการใช้งาน #C0xF76B45#โปรดทำการทำข้าวหลามและรับประทานภายในระยะเวลา #C0x5B545B#หลังจากหมดเวลาไอเท็มจะถูกลบออกจากระบบ'
	},
	[93001] = {
		id = 93001,
		fmt = '1. การตกปลามีจำนวนครั้งจำกัดต่อวัน การจำกัดจำนวนครั้งจะรีเซ็ตทุกวันเวลา 5:00 น. เมื่อใช้จำนวนครั้งทั้งหมดแล้วจะไม่สามารถตกปลาได้ในวันนั้น'
	},
	[93002] = {
		id = 93002,
		fmt = '2. ทุกครั้งในการตกปลาจะต้องใช้เหยื่อ 1 ตัว'
	},
	[93003] = {
		id = 93003,
		fmt = '3. เมื่อปลาหมุดเข้าหมายต้องควบคุมให้เหยื่อและปลาตรงกัน โดยคลิก/กดค้างเพื่อดึงสายขึ้นและปล่อยเพื่อดึงลง'
	},
	[93004] = {
		id = 93004,
		fmt = '4. เมื่อเหยื่อและปลาตรงกัน ความคืบหน้าการตกปลาจะเพิ่มขึ้น แต่ถ้าไม่ตรงจะลดลง'
	},
	[93005] = {
		id = 93005,
		fmt = '5. เมื่อแถบความคืบหน้าถึงขีดสูงสุด จะตกปลาสำเร็จ หากแถบความคืบหน้าถึงขีดต่ำสุด จะตกปลาล้มเหลว โดยไม่ว่าจะสำเร็จหรือไม่จะต้องเสียจำนวนครั้งและเหยื่อ'
	},
	[93006] = {
		id = 93006,
		fmt = '6. การเลือกเบ็ดและเหยื่อที่มีคุณภาพสูงขึ้นสามารถลดความยากในการตกปลาและเพิ่มอัตราความสำเร็จในการตกปลาอัตโนมัติ'
	},
	[93007] = {
		id = 93007,
		fmt = '7. การเพิ่มระดับการตกปลาในแต่ละครั้งจะช่วยเพิ่มค่าพื้นฐานของภูตทั้งหมดและลดความยากในการทำการตกปลา'
	},
	[93008] = {
		id = 93008,
		fmt = '8. การเพิ่มระดับการตกปลาต้องทำการจับปลาให้ได้ตามจำนวนที่กำหนด เมื่อครบตามจำนวนแล้วจะอัปเกรดระดับ โดยเริ่มต้นการนับจำนวนใหม่หลังจากอัปเกรด'
	},
	[93009] = {
		id = 93009,
		fmt = '9. บางครั้งอาจจะมีภูตลึกลับปรากฏขึ้น ภูตเหล่านี้จะไม่นับรวมในการนับจำนวนสำหรับการอัปเกรด'
	},
	[93010] = {
		id = 93010,
		fmt = '10. เมื่อระดับการฝึกฝนของเทรนเนอร์ถึง Lv.68 จะสามารถใช้ฟังก์ชันตกปลาอัตโนมัติได้ โดยคลิกที่ภูตคู่ใจในหน้าจอเพื่อเข้าสู่การตกปลาอัตโนมัติ ซึ่งมีโอกาสล้มเหลวได้'
	},
	[93011] = {
		id = 93011,
		fmt = '11. คำอธิบายเกี่ยวกับคุณสมบัติบางประการที่เกี่ยวข้องกับการตกปลา:'
	},
	[93012] = {
		id = 93012,
		fmt = '① อัตราความสำเร็จในการตกปลาอัตโนมัติ — อัตราความสำเร็จของการตกปลาอัตโนมัติจะขึ้นอยู่กับคุณภาพของปลาและได้รับผลกระทบจากอุปกรณ์ตกปลา'
	},
	[93013] = {
		id = 93013,
		fmt = '② ความเร็วในการเพิ่มความคืบหน้า — เมื่อเหยื่อและปลาตรงกันในหน้าจอการตกปลา ความเร็วในการเพิ่มความคืบหน้าจะแสดงที่ด้านขวา'
	},
	[93014] = {
		id = 93014,
		fmt = '③ ความเร็วในการลดความคืบหน้า — เมื่อเหยื่อและปลามีการเคลื่อนไหวที่ไม่ตรงกันในหน้าจอการตกปลา ความเร็วในการลดความคืบหน้าจะแสดงที่ด้านขวา'
	},
	[93015] = {
		id = 93015,
		fmt = '④ ขอบเขตการตัดสินเหยื่อ — ขนาดของกรอบที่ใช้ในการตัดสินว่าหมายถูกต้องหรือไม่ ขึ้นอยู่กับเหยื่อที่เลือก'
	},
	[93016] = {
		id = 93016,
		fmt = '⑤ เวลารอการตกปลา — เวลาที่ต้องรอจากการโยนเบ็ดจนปลาจับได้'
	},
	[93017] = {
		id = 93017,
		fmt = '⑥ ขอบเขตการเคลื่อนไหวของปลา — ระยะทางที่ปลาจะเคลื่อนที่ขึ้นลงในหน้าจอการตกปลา'
	},
	[94001] = {
		id = 94001,
		fmt = '1. การแข่งขันตกปลาจัดขึ้นทุกสองสัปดาห์ในวันอาทิตย์ เวลา 5:00-23:00 น.'
	},
	[94002] = {
		id = 94002,
		fmt = '2. การแข่งขันจะมีการจับคู่เซิร์ฟเวอร์แบบสุ่มเพื่อทำการแข่งขัน โดยจะจัดอันดับจากคะแนนที่ได้จากการตกปลา'
	},
	[94003] = {
		id = 94003,
		fmt = '3. เมื่อการแข่งขันสิ้นสุดลง จะมีการแจกของรางวัลตามอันดับจากคะแนนสุดท้าย'
	},
	[94004] = {
		id = 94004,
		fmt = '4. การจัดอันดับสำหรับเทรนเนอร์ที่มีคะแนนเท่ากันจะจัดอันดับตามเวลาที่มาถึง'
	},
	[94005] = {
		id = 94005,
		fmt = '5. ในการแข่งขันจะมีการปรากฏตัวของเกโอคา ที่มีคะแนนสูงกว่า'
	},
	[94006] = {
		id = 94006,
		fmt = '6. การใช้เหยื่อพิเศษในกิจกรรมจะเพิ่มโอกาสในการพบเกโอคา'
	},
	[94007] = {
		id = 94007,
		fmt = '7. ขอให้โชคดีในการแข่งขัน!'
	},
	[95001] = {
		id = 95001,
		fmt = '1. ภายในโปเกเดกซ์ ภูตบางตัวสามารถทำการวิวัฒนาการขั้นสูงได้ใน  ห้องวิวัฒนาการขั้นสูง'
	},
	[95002] = {
		id = 95002,
		fmt = '2. เมื่อวิวัฒนาการแล้ว คุณสมบัติพื้นฐานของภูตจะเพิ่มขึ้น และคุณสมบัติที่ได้รับการฝึกจะถูกถ่ายทอดทั้งหมด; คุณสมบัติและระดับความหายาก #C0xF76B45##L10# อาจมีการเปลี่ยนแปลง #C0x5B545B# ด้วย'
	},
	[95003] = {
		id = 95003,
		fmt = '3. ภูตต้องผ่านการฝึกจนถึงระดับที่กำหนดก่อนจึงจะสามารถวิวัฒนาการขั้นสูงได้ และจะต้องใช้วัตถุดิบพิเศษสองประเภทคือ  กุญแจวิวัฒนาการ  และ  หินวิวัฒนาการเฉพาะ'
	},
	[95004] = {
		id = 95004,
		fmt = '4. กุญแจวิวัฒนาการและหินวิวัฒนาการเฉพาะสามารถได้มาจากการแลกเปลี่ยนในห้องวิวัฒนาการขั้นสูงทุกวัน'
	},
	[95005] = {
		id = 95005,
		fmt = '5. ห้องวิวัฒนาการขั้นสูงจะมีการเปิดตัวภูตใหม่ ๆ ที่สามารถวิวัฒนาการได้ โปรดติดตาม!'
	},
	[96001] = {
		id = 96001,
		fmt = '1. กุญแจวิวัฒนาการสามารถแลกได้จากการใช้ภูตที่มีระดับหายากเดียวกัน #C0xF76B45##L10# หรือชิ้นส่วนของภูตที่มีระดับหายากเดียวกัน #C0x5B545B# โดยมีกฎการแลกเปลี่ยนดังนี้:'
	},
	[96002] = {
		id = 96002,
		fmt = '① ภูตระดับ A หรือกูอี้ม่วงสามารถแลกได้ 10 กุญแจวิวัฒนาการสีม่วง, โดยการแลกชิ้นส่วนของภูตระดับ A 3 ชิ้นจะได้กุญแจวิวัฒนาการสีม่วง 1 ชิ้น'
	},
	[96003] = {
		id = 96003,
		fmt = '② ภูตระดับ S หรือกูอี้สีส้มสามารถแลกได้ 10 กุญแจวิวัฒนาการสีส้ม, โดยการแลกชิ้นส่วนของภูตระดับ S 5 ชิ้นจะได้กุญแจวิวัฒนาการสีส้ม 1 ชิ้น'
	},
	[96004] = {
		id = 96004,
		fmt = '③ ภูตระดับ S+ หรือกูอี้แดงสามารถแลกได้ 10 กุญแจวิวัฒนาการสีแดง, โดยการแลกชิ้นส่วนของภูตระดับ S+ 8 ชิ้นจะได้กุญแจวิวัฒนาการสีแดง 1 ชิ้น'
	},
	[96005] = {
		id = 96005,
		fmt = '2. ทุกวันเวลา 05:00 น. ระบบจะเพิ่มจำนวนการแลกกุญแจวิวัฒนาการที่สามารถแลกได้และสามารถสะสมได้ตลอดไป แต่ไม่สามารถเกินขีดจำกัด'
	},
	[97001] = {
		id = 97001,
		fmt = '1. หินวิวัฒนาการเฉพาะสามารถแลกได้จากการใช้ภูตที่มีลักษณะและระดับหายากเดียวกัน #C0xF76B45##L10# หรือชิ้นส่วนของภูตที่มีลักษณะและระดับหายากเดียวกัน #C0x5B545B# โดยมีกฎการแลกเปลี่ยนดังนี้:'
	},
	[97002] = {
		id = 97002,
		fmt = '① ภูตระดับ A และลักษณะเดียวกันหรือกูอี้สีม่วงสามารถแลกได้ 10 หินวิวัฒนาการสีม่วง, โดยการแลกชิ้นส่วนของภูตระดับ A 3 ชิ้นจะได้หินวิวัฒนาการสีม่วง 1 ชิ้น'
	},
	[97003] = {
		id = 97003,
		fmt = '② ภูตระดับ S และลักษณะเดียวกันหรือกูอี้สีส้มสามารถแลกได้ 10 หินวิวัฒนาการสีส้ม, โดยการแลกชิ้นส่วนของภูตระดับ S 5 ชิ้นจะได้หินวิวัฒนาการสีส้ม 1 ชิ้น'
	},
	[97004] = {
		id = 97004,
		fmt = '③ ภูตระดับ S+ และลักษณะเดียวกันหรือกูอี้แดงสามารถแลกได้ 10 หินวิวัฒนาการสีแดง, โดยการแลกชิ้นส่วนของภูตระดับ S+ 8 ชิ้นจะได้หินวิวัฒนาการสีแดง 1 ชิ้น'
	},
	[97005] = {
		id = 97005,
		fmt = '3. ระบบจะบันทึกจำนวนการแลกหินวิวัฒนาการเฉพาะแต่ละชนิดแยกจากกัน'
	},
	[97006] = {
		id = 97006,
		fmt = '4. ทุกวันเวลา 05:00 น. ระบบจะเพิ่มจำนวนการแลกหินวิวัฒนาการเฉพาะที่สามารถแลกได้และสามารถสะสมได้ตลอดไป แต่ไม่สามารถเกินขีดจำกัด'
	},
	[98001] = {
		id = 98001,
		fmt = '1. สนามแข่งการต่อสู้เป็น #C0xF76B45#การจับคู่ข้ามเซิร์ฟเวอร์#C0x5B545B# ดังนั้นจึงต้องรอการจับคู่เซิร์ฟเวอร์และเมื่อจับคู่สำเร็จจะมีสถานะ #C0xF76B45#การจับคู่สำเร็จ รอเริ่มการแข่งขัน'
	},
	[98002] = {
		id = 98002,
		fmt = '2. การแข่งขันจะจัดเป็นฤดูกาล โดยมีขั้นตอน: #C0xF76B45#ประกาศเริ่มฤดูกาล→การแข่งขันฤดูกาลดำเนินต่อ→การสิ้นสุดฤดูกาลและการแสดงอันดับ, ฤดูกาลมักจะใช้เวลาหลายสัปดาห์ สามารถดูรายละเอียดได้ที่ด้านบนของหน้าต่าง'
	},
	[98003] = {
		id = 98003,
		fmt = '3. ในแต่ละสัปดาห์มีการจับคู่ที่สามารถทำได้ไม่จำกัดจำนวนในช่วงเวลาเปิดการจับคู่ เมื่อจับคู่ไม่ได้ก็ไม่สามารถทำการต่อสู้ได้ #C0xF76B45#เวลาจับคู่ดูได้ที่ปุ่มเริ่มจับคู่'
	},
	[98004] = {
		id = 98004,
		fmt = '4. การแข่งขันมี #C0xF76B45#การจับคู่แบบสด#C0x5B545B# ผู้เล่นต้องคลิกเริ่มจับคู่และรอการจับคู่กับคู่แข่งที่สมดุล โดยต้องออนไลน์ตลอดในระหว่างการต่อสู้'
	},
	[98005] = {
		id = 98005,
		fmt = '5. ใช้ #C0xF76B45#ระบบคะแนน#C0x5B545B# หากผู้เล่นชนะจะได้คะแนนที่สูงขึ้น อันดับจะจัดจากคะแนนรวมของผู้เล่นในทุกๆ การแข่งขัน โดย #C0xF76B45#ทั้งสองโหมดจะแยกคำนวณคะแนนและจัดอันดับ'
	},
	[98006] = {
		id = 98006,
		fmt = '6. เมื่อเริ่มฤดูกาลใหม่ ระบบจะล้างข้อมูลคะแนนสูงสุดของฤดูกาลที่ผ่านมาและคะแนนจากโหมดทั้งสอง'
	},
	[99001] = {
		id = 99001,
		fmt = '1. ในสนามแข่งจะมี 2 โหมดเกมเปิดให้เล่น #C0xF76B45#โหมดการแข่งขันไม่มีข้อจำกัด และ โหมดการแข่งขันแบบยุติธรรม#C0x5B545B#'
	},
	[99002] = {
		id = 99002,
		fmt = '2. โหมดการแข่งขันไม่มีข้อจำกัด ต้องตั้งทีมให้พร้อมก่อนเริ่มการจับคู่ #C0xF76B45#และสามารถควบคุมการต่อสู้ได้ด้วยมือเองหลังเข้าร่วมแล้ว#C0x5B545B#'
	},
	[99003] = {
		id = 99003,
		fmt = '3. โหมดการแข่งขันแบบยุติธรรมจะมีการตั้งธีมสำหรับแต่ละสัปดาห์ #C0xF76B45#การเปลี่ยนธีมจะเปลี่ยนทุกสัปดาห์หรือทุกสองสัปดาห์ (ธีมจะเปลี่ยน แต่คะแนนสะสมยังคงคำนวณ)'
	},
	[99004] = {
		id = 99004,
		fmt = '4. โหมดการแข่งขันแบบยุติธรรมจะแบ่งออกเป็น #C0xF76B45#ระบบเลือกภูตและระบบ BAN#C0x5B545B# เมื่อคะแนนถึงระดับหนึ่งจะเปลี่ยนเป็นระบบ BAN อัตโนมัติ (ธีมจะไม่เปลี่ยน) รายละเอียดสามารถดูได้ที่ปุ่ม i'
	},
	[99005] = {
		id = 99005,
		fmt = '5. โหมดการแข่งขันแบบยุติธรรมต้องตั้งทีมสำรองไว้ล่วงหน้า #C0xF76B45#หากจำนวนภูตไม่ครบตามที่กำหนดจะไม่สามารถจับคู่ได้ ทีมสำรองจะกำหนดภูตที่สามารถใช้ในโหมด BAN ได้'
	},
	[99006] = {
		id = 99006,
		fmt = '6. โหมดการแข่งขันทั้งสองจะใช้ระบบ #C0xF76B45#6V6#C0x5B545B# โดยในการต่อสู้แบบยุติธรรมจะมีการปรับคุณสมบัติของภูตทั้งหมดให้เป็นระดับเดียวกัน รวมถึงปรับคุณสมบัติความเร็วที่กำหนดการเดินเกม'
	},
	[99007] = {
		id = 99007,
		fmt = '7. ในการต่อสู้แบบยุติธรรม #C0xF76B45#ไอเทม, รัน, และลักษณะพิเศษต่าง ๆ #C0x5B545B#จะไม่ได้รับการปรับและจะถูกปรับให้เป็นระดับเดียวกันระหว่างทั้งสองฝ่าย เช่นเดียวกับทักษะจากกิลด์และทักษะพิเศษจากการผจญภัย'
	},
	[99008] = {
		id = 99008,
		fmt = '8. การต่อสู้ทั้งสองโหมดจะใช้ #C0xF76B45#โหมดควบคุมด้วยมือ#C0x5B545B# โดยผู้เล่นต้องทำการควบคุมทักษะภูตภายในเวลานับถอยหลัง หากเวลาหมดจะเข้าสู่การต่อสู้แบบอัตโนมัติ'
	},
	[99009] = {
		id = 99009,
		fmt = '9. โหมดทั้งสองมีการต่อสู้สูงสุด 20 รอบ หากฝ่ายใดฝ่ายหนึ่งหมดภูตทั้งหมดจะถือว่าแพ้ หากจบการแข่งขันโดยไม่มีฝ่ายใดชนะ ฝ่ายที่มีพลังชีวิตมากที่สุดจะเป็นฝ่ายชนะ'
	},
	[100001] = {
		id = 100001,
		fmt = '1. ระหว่างการจับคู่ #C0xF76B45#หลังจากการต่อสู้ 6 รอบแรกทุกวัน#C0x5B545B# ผู้เล่นจะได้รับรางวัลการจัดอันดับไม่ว่าจะชนะหรือแพ้'
	},
	[100002] = {
		id = 100002,
		fmt = '2. ในแต่ละสัปดาห์จะมีการตั้งรางวัล #C0xF76B45#สำหรับเป้าหมายเล็ก ๆ ผู้เล่นสามารถรับรางวัลได้จากปุ่มของขวัญที่มุมขวาล่าง'
	},
	[100003] = {
		id = 100003,
		fmt = '3. ในช่วงฤดูกาล #C0xF76B45#จะมีการแจกของรางวัลเมื่อสิ้นสุดสัปดาห์ โดยรางวัลจะถูกคำนวณจากคะแนนที่สูงที่สุดในทั้งสองโหมดของผู้เล่น และผู้เล่นต้องเข้าร่วมการจับคู่ 3 ครั้งขึ้นไปเพื่อรับรางวัล'
	},
	[100004] = {
		id = 100004,
		fmt = '4. เมื่อสิ้นสุดฤดูกาล #C0xF76B45#ผู้เล่นจะได้รับรางวัลจากการจัดอันดับ โดยรางวัลจะมอบให้หลังจากสิ้นสุดการแข่งขันในวันสุดท้าย 30 นาที หลังจากนั้นจะมีการแจกของรางวัลตามอันดับสูงสุดที่ได้จากโหมดทั้งสอง'
	},
	[100005] = {
		id = 100005,
		fmt = '5. เงินในระบบสามารถนำไปใช้ในร้านค้าในการแข่งขันระหว่างเซิร์ฟเวอร์ เมื่อมีการปลดล็อกร้านค้าที่เกี่ยวข้อง #C0xF76B45#โดยการบรรลุคะแนนที่กำหนด ผลิตภัณฑ์จะถูกปลดล็อคถาวร'
	},
	[101001] = {
		id = 101001,
		fmt = '1. ในช่วงกิจกรรม ผู้เล่นที่กลับมาสามารถผูกกับ #C0xF76B45#เทรนเนอร์ประสบการณ์ 1 คน#C0x5B545B# เพื่อร่วมกิจกรรมได้ #C0xF76B45#ไม่สามารถยกเลิกการผูกได้'
	},
	[101002] = {
		id = 101002,
		fmt = '2. เทรนเนอร์ประสบการณ์ต้องมีระดับ 55 และพลังการต่อสู้ 150,000 ขึ้นไปจึงจะสามารถผูกกับเทรนเนอร์กลับมาได้'
	},
	[101003] = {
		id = 101003,
		fmt = '3. เมื่อทั้งสองเทรนเนอร์ผูกพันกันแล้ว ระบบจะเปิดภารกิจที่ต้องทำร่วมกัน โดยจะมีภารกิจสองประเภทคือภารกิจร่วมมือและภารกิจเดี่ยว #C0xF76B45#เทรนเนอร์ที่กลับมาจะสามารถทำภารกิจทั้งหมดได้'
	},
	[101004] = {
		id = 101004,
		fmt = '4. เมื่อเสร็จสิ้นภารกิจแต่ละครั้ง #C0xF76B45#ทั้งสองเทรนเนอร์จะได้รับคะแนนภารกิจ #C0x5B545B#เมื่อสะสมคะแนนได้ถึงจำนวนที่กำหนดจะสามารถเปิดกล่องการรวมตัวได้'
	},
	[101005] = {
		id = 101005,
		fmt = '5. เทรนเนอร์ทั้งสอง #C0xF76B45#สามารถผูกกันได้เพียง 1 ครั้งในกิจกรรมนี้ #C0x5B545B#เมื่อกิจกรรมการรวมตัวสิ้นสุดลง เทรนเนอร์ประสบการณ์จะมีช่วงเวลาเย็นตัวที่จะไม่สามารถเข้าร่วมกิจกรรมใหม่ได้'
	},
	[101006] = {
		id = 101006,
		fmt = '6. หากกิจกรรมไม่เสร็จสิ้นเนื่องจากเทรนเนอร์กลับมาไม่ได้เข้าสู่ระบบเป็นเวลานาน เทรนเนอร์ประสบการณ์ที่ผูกพันจะได้รับช่วงเวลาเย็นตัวที่สั้นลงหลังสิ้นสุดกิจกรรม'
	},
	[101007] = {
		id = 101007,
		fmt = '7. หลังจากสิ้นสุดกิจกรรม #C0xF76B45#รางวัลที่ยังไม่ได้รับทั้งหมดจะไม่ถูกส่งทางอีเมล #C0x5B545B#โปรดอย่าลืมรับรางวัลเมื่อมันมี!'
	},
	[102001] = {
		id = 102001,
		fmt = '#C0xF76B45#【กฎพื้นฐานของยิม】'
	},
	[102002] = {
		id = 102002,
		fmt = '1. เวลาเปิดของยิม: #C0xF76B45#ทุกวันจันทร์ 10:00 น.#C0x5B545B# ถึง #C0xF76B45#ทุกวันอาทิตย์ 21:45 น.#C0x5B545B#; เวลาฉะนั้นเป็นเวลาปิดยิม ซึ่งไม่สามารถท้าทายดันเจี้ยนหรือชิงตำแหน่งเจ้าของยิมได้ ทุกวันจันทร์ 05:00 น. จะรีเซ็ตยิมทั้งหมด'
	},
	[102003] = {
		id = 102003,
		fmt = '2. ดันเจี้ยนของยิมแต่ละวันมีจำนวนการท้าทายที่สำเร็จที่จำกัด โดยจะหักจำนวนการท้าทายเมื่อสำเร็จ และจะไม่หักเมื่อท้าทายแล้วแพ้; ทุกวัน 05:00 น. จะรีเซ็ตจำนวนการท้าทาย'
	},
	[102004] = {
		id = 102004,
		fmt = '3. ในแต่ละรอบจะมียิม 8 แห่ง โดยแต่ละยิมจะมี 5 ดันเจี้ยนยิม'
	},
	[102005] = {
		id = 102005,
		fmt = '4. ดันเจี้ยนของยิมเป็นดันเจี้ยนแบบครั้งเดียว ไม่สามารถท้าทายซ้ำได้; และคุณสมบัติของมอนสเตอร์ในยิมจะสัมพันธ์กับพลังการต่อสู้ของผู้เล่น เมื่อรีเซ็ตในแต่ละสัปดาห์ มอนสเตอร์และคุณสมบัติของมันจะถูกรีเฟรชใหม่'
	},
	[102006] = {
		id = 102006,
		fmt = '5. เมื่อผ่านดันเจี้ยนทุกระดับในยิมแล้ว ผู้เล่นสามารถท้าทายเพื่อเป็นเจ้าของยิมเกียรติได้'
	},
	[102007] = {
		id = 102007,
		fmt = '6. ยิมแต่ละแห่งมีเจ้าของยิมเกียรติ 1 คนเท่านั้น; และผู้เล่นแต่ละคนสามารถเป็นเจ้าของยิมเกียรติได้เพียง 1 แห่ง เมื่อเป็นเจ้าของยิมแห่งใหม่ ระบบจะล้างตำแหน่งของภูตในยิมอื่น ๆ'
	},
	[102008] = {
		id = 102008,
		fmt = '7. การท้าทายของเจ้าของยิมเกียรติมีเวลาในการพักฟื้นจำกัด หลังจากการท้าทายสำเร็จต้องรอช่วงพักฟื้นก่อนจึงจะสามารถท้าทายใหม่ได้; แต่ไม่มีข้อจำกัดในการท้าทายจำนวนครั้ง'
	},
	[102009] = {
		id = 102009,
		fmt = '8. การท้าทายเจ้าของยิมต้องมีภูตที่มีคุณสมบัติที่กำหนด (ไม่ว่าจะเป็นคุณสมบัติที่ 1 หรือที่ 2 ก็สามารถใช้ได้) หากไม่มีภูตที่มีคุณสมบัติที่กำหนด จะไม่สามารถท้าทายได้'
	},
	[102010] = {
		id = 102010,
		fmt = '#C0xF76B45#【คำอธิบายบันทึกยิม】'
	},
	[102011] = {
		id = 102011,
		fmt = '1. บันทึกยิมจะบันทึกข้อมูลการท้าทาย PVP ทั้งหมดที่เกี่ยวข้องกับ #C0xF76B45#และตัวผู้เล่นเอง รวมถึงข้อมูลการผ่านดันเจี้ยนของยิม'
	},
	[102012] = {
		id = 102012,
		fmt = '2. ข้อมูลในบันทึกยิมจะมีเฉพาะข้อมูลจากสัปดาห์ที่แล้วและสัปดาห์นี้'
	},
	[102013] = {
		id = 102013,
		fmt = '#C0xF76B45#【คำอธิบายโบนัสจากการท้าทาย】'
	},
	[102014] = {
		id = 102014,
		fmt = '1. โบนัสจากการท้าทายที่เปิดใช้งานจะมีผลเฉพาะในดันเจี้ยนของยิม'
	},
	[102015] = {
		id = 102015,
		fmt = '2. โบนัสทักษะการท้าทายสามารถเปิดใช้งานได้โดยการใช้คะแนนโบนัส'
	},
	[102016] = {
		id = 102016,
		fmt = '3. คะแนนโบนัสจะเพิ่มขึ้นเล็กน้อยทุกวันเวลา 05:00 น. หรือสามารถใช้เพชรในการซื้อคะแนนเพิ่มเติมได้ โดยสามารถซื้อได้จำนวนจำกัดในแต่ละวัน; การผ่านดันเจี้ยนยิมยังสามารถให้คะแนนโบนัสได้'
	},
	[102017] = {
		id = 102017,
		fmt = '4. เมื่อรีเซ็ตในแต่ละสัปดาห์ คะแนนโบนัสและระดับโบนัสจะถูกล้างทั้งหมด'
	},
	[102018] = {
		id = 102018,
		fmt = '#C0xF76B45#【การแสดงตัวอย่างรางวัลเจ้าของยิม】'
	},
	[103001] = {
		id = 103001,
		fmt = '1. ยิมระหว่างเซิร์ฟเวอร์จะมี 8 ยิมที่แตกต่างกัน และในแต่ละยิมระหว่างเซิร์ฟเวอร์จะมีเจ้าของยิมระหว่างเซิร์ฟเวอร์ 1 คนและสมาชิกยิมระหว่างเซิร์ฟเวอร์ 7 คน'
	},
	[103002] = {
		id = 103002,
		fmt = '2. เมื่อผ่านดันเจี้ยนยิมของเซิร์ฟเวอร์ทั้งหมดได้ทุกระดับแล้ว ผู้เล่นสามารถท้าทายเพื่อเป็นเจ้าของยิมระหว่างเซิร์ฟเวอร์หรือสมาชิกยิมระหว่างเซิร์ฟเวอร์ได้'
	},
	[103003] = {
		id = 103003,
		fmt = '3. ผู้เล่นสามารถเป็นเจ้าของยิมระหว่างเซิร์ฟเวอร์หรือสมาชิกยิมระหว่างเซิร์ฟเวอร์ได้เพียง 1 ที่เท่านั้น เมื่อเป็นเจ้าของยิมหรือสมาชิกใหม่ ระบบจะล้างภูตในยิมเก่าอัตโนมัติ'
	},
	[103004] = {
		id = 103004,
		fmt = '4. การท้าทายเจ้าของยิมระหว่างเซิร์ฟเวอร์มีเวลาในการพักฟื้นจำกัด เช่นเดียวกับเจ้าของยิมธรรมดา และหลังจากท้าทายสำเร็จจะต้องพักฟื้นก่อนท้าทายใหม่ได้ แต่ไม่มีข้อจำกัดในการท้าทายจำนวนครั้ง'
	},
	[103005] = {
		id = 103005,
		fmt = '5. การท้าทายเจ้าของยิมระหว่างเซิร์ฟเวอร์ต้องใช้ภูตที่มีคุณสมบัติตามที่กำหนด (คุณสมบัติที่ 1 หรือที่ 2 ก็ได้) หากไม่มีภูตที่ตรงตามคุณสมบัติที่กำหนด จะไม่สามารถท้าทายได้'
	},
	[103006] = {
		id = 103006,
		fmt = '#C0xF76B45#【การแสดงตัวอย่างรางวัลยิมระหว่างเซิร์ฟเวอร์】'
	},
	[104001] = {
		id = 104001,
		fmt = '1. ในระหว่างกิจกรรม ผู้เล่นสามารถเล่นเกมพลิกการ์ดเพื่อรับไอเท็มที่พลิกออกมา'
	},
	[104002] = {
		id = 104002,
		fmt = '2. กิจกรรมนี้มีหลายรอบในการพลิกการ์ด โดยในแต่ละรอบจะมีรางวัลใหญ่ที่สามารถชนะได้ รางวัลใหญ่อาจจะอยู่ใต้การ์ดใดก็ได้ เมื่อพลิกเจอจะได้รับรางวัลทันทีและสามารถเล่นเกมพลิกการ์ดรอบถัดไป'
	},
	[104003] = {
		id = 104003,
		fmt = '3. การพลิกการ์ดจะใช้จำนวนครั้ง โดยจะใช้ครั้งฟรีเป็นลำดับแรก จำนวนครั้งฟรีจะรีเซ็ตทุกวันเวลา 5:00 น. หากใช้ครบแล้วจะใช้จำนวนครั้งจากภารกิจแทน โดยจำนวนครั้งภารกิจจะไม่รีเซ็ตและสามารถได้รับจากการทำภารกิจ'
	},
	[104004] = {
		id = 104004,
		fmt = '4. รางวัลใหญ่ในแต่ละรอบของการพลิกการ์ดจะถูกแสดงในหน้ากิจกรรม โปรดติดตามโชคดีของคุณ!'
	},
	[105001] = {
		id = 105001,
		fmt = '1. เมื่อเงื่อนไขครบถ้วน เจ้าของห้องสามารถเชิญผู้เล่นคนอื่นออกจากห้องได้ และผู้เล่นคนอื่นก็สามารถลงคะแนนเพื่อเชิญเจ้าของห้องออกจากห้องได้'
	},
	[105002] = {
		id = 105002,
		fmt = '2. ต้องมี 3 เงื่อนไขคือ: 1. ในห้องต้องมีผู้เล่นอย่างน้อย 3 คนที่ทำภารกิจสำเร็จ; 2. ผู้เล่นที่ถูกเชิญออกจากห้องต้องอยู่ในห้องอย่างน้อย 3 ชั่วโมง; 3. ผู้เล่นนั้นต้องมีจำนวนภารกิจสำเร็จเป็น 0 หรือยังไม่ทำภารกิจ'
	},
	[105003] = {
		id = 105003,
		fmt = '3. เมื่อเจ้าของห้องเชิญผู้เล่นออกจากห้อง ตนเองต้องทำภารกิจสำเร็จอย่างน้อย 1 ครั้ง'
	},
	[105004] = {
		id = 105004,
		fmt = '4. เมื่อผู้เล่นคนอื่นลงคะแนนเพื่อเชิญเจ้าของห้องออกจากห้อง ผู้เล่นคนนั้นต้องทำภารกิจสำเร็จ 3 ครั้งเพื่อมีสิทธิ์ลงคะแนน และคะแนนเสียงที่เชิญเจ้าของห้องออกต้องมีมากกว่าคะแนนเสียงให้เจ้าของห้องอยู่'
	},
	[105005] = {
		id = 105005,
		fmt = '5. ผู้เล่นที่ถูกเชิญออกจากห้องครบ 3 ครั้งในระหว่างที่การท้าทายยังไม่รีเซ็ตจะไม่สามารถเข้าร่วมการท้าทายของช่วงนี้ได้ และสามารถเข้าร่วมได้ในครั้งถัดไป'
	},
	[106001] = {
		id = 106001,
		fmt = '1. ในระหว่างกิจกรรม ผู้เล่นสามารถแลกชิ้นส่วนที่มีคุณภาพเดียวกันได้สำเร็จ เมื่อแลกชิ้นส่วนแล้ว ชิ้นส่วนเดิมในกระเป๋าจะหายไปและได้รับชิ้นส่วนที่เลือกแทน'
	},
	[106002] = {
		id = 106002,
		fmt = '2. สำหรับแต่ละกิจกรรม จำนวนการแลกชิ้นส่วนที่มีคุณภาพแตกต่างกันจะคำนวณแยกกัน และมีจำนวนครั้งในการแลกที่จำกัด'
	},
	[106003] = {
		id = 106003,
		fmt = '3. เมื่อผู้เล่นมีระดับ VIP ที่สูงขึ้น จะสามารถเพิ่มจำนวนการแลกชิ้นส่วนได้'
	},
	[106004] = {
		id = 106004,
		fmt = '4. ชิ้นส่วนที่สามารถแลกในแต่ละกิจกรรมอาจมีความแตกต่างกัน หากในกิจกรรมนี้ไม่มีชิ้นส่วนที่ต้องการแลก โปรดรอในกิจกรรมครั้งถัดไป!'
	},
	[107001] = {
		id = 107001,
		fmt = '1. สำหรับบอสเทศกาลแต่ละตัว ผู้เล่นสามารถท้าทายได้เพียง 1 ครั้ง'
	},
	[107002] = {
		id = 107002,
		fmt = '2. ทุกๆ ดันเจี้ยนเทศกาลจะมีจำนวนครั้งในการท้าทายที่จำกัด หากครบแล้วจะไม่สามารถท้าทายได้'
	},
	[107003] = {
		id = 107003,
		fmt = '3. ผู้เล่นสามารถท้าทายบอสเทศกาลที่พบด้วยตัวเองได้ 1 ครั้ง การท้าทายนี้จะไม่ถูกนับรวมกับจำนวนครั้งที่คนอื่นท้าทาย'
	},
	[107004] = {
		id = 107004,
		fmt = '4. ดันเจี้ยนเทศกาลมีการแบ่งความยาก 3 ระดับ โดยระดับสูงสุดคือ SSS'
	},
	[107005] = {
		id = 107005,
		fmt = '5. ทุกบอสเทศกาลมีการนับเวลาถอยหลัง หากเวลาหมดการท้าทายจะหายไปทันที'
	},
	[107006] = {
		id = 107006,
		fmt = '6. เมื่อชนะการท้าทายจะได้รับรางวัล และหากแพ้จะไม่ได้รับรางวัลและไม่หักจำนวนครั้งในการท้าทาย'
	},
	[107007] = {
		id = 107007,
		fmt = '7. ทุกวันจะมีจำนวนครั้งที่สามารถท้าทายบอสเทศกาลได้ และมีเวลารอการรีเซ็ตก่อนที่จะสามารถท้าทายใหม่ได้'
	},
	[108001] = {
		id = 108001,
		fmt = '1. ทุกวันจะเปิดห้องเล่นเกม  ตกลงมาเป็นซองแดง  ที่ผู้เล่นสามารถเข้าร่วมและรับคูปองรางวัล ซึ่งมีโอกาสได้รับรางวัลใหญ่'
	},
	[108002] = {
		id = 108002,
		fmt = '2. ห้องเล่นเกม  ตกลงมาเป็นซองแดง  จะเปิดในเวลาที่กำหนดทุกวัน โปรดติดตามข้อมูลในหน้าจอหลักของกิจกรรม หากเลยเวลาจะปิดและไม่สามารถรับคูปองรางวัลได้'
	},
	[108003] = {
		id = 108003,
		fmt = '3. ในเกม  ตกลงมาเป็นซองแดง  ผู้เล่นจะต้องคลิกที่ซองแดงที่ตกลงมาบนหน้าจอในเวลาที่กำหนด เมื่อหมดเวลา ผู้เล่นจะได้รับรางวัลตามจำนวนที่คลิกได้'
	},
	[108004] = {
		id = 108004,
		fmt = '4. ซองแดงในแต่ละรอบจะมีเนื้อหาที่ไม่เหมือนกัน โปรดติดตามข้อมูลในหน้าจอหลักของกิจกรรม'
	},
	[108005] = {
		id = 108005,
		fmt = '5. หลังจากได้รับคูปองรางวัล ผู้เล่นสามารถนำไปขูดรางวัลในช่องรางวัล ซึ่งจะมีการแสดงผลรางวัลให้เห็นที่ช่องนี้'
	},
	[108006] = {
		id = 108006,
		fmt = '6. หลังจากขูดรางวัลแล้ว รางวัลจะถูกส่งทางอีเมลให้ผู้เล่นเมื่อจบเกม  ตกลงมาเป็นซองแดง  โปรดตรวจสอบอีเมลของคุณ'
	},
	[108007] = {
		id = 108007,
		fmt = '7. หากผู้เล่นได้รับคูปองรางวัล แต่ไม่ได้ขูดรางวัลภายในเวลาที่กำหนด ระบบจะขูดรางวัลและส่งอีเมลรางวัลให้ผู้เล่นโดยอัตโนมัติ'
	},
	[109001] = {
		id = 109001,
		fmt = '1. เกมมินิ  สร้างตุ๊กตาหิมะ  ผู้เล่นต้องสร้างตุ๊กตาหิมะที่มีระดับ และเมื่อระดับสูงขึ้นจะสามารถปลดล็อคการตกแต่งและการแต่งกายให้กับตุ๊กตาหิมะได้'
	},
	[109002] = {
		id = 109002,
		fmt = '2. ผู้เล่นต้องสะสมหิมะพิเศษในกิจกรรมเพื่อสร้างตุ๊กตาหิมะของพิกาจู ซึ่งแต่ละครั้งที่ใช้หิมะพิเศษจะได้รับรางวัลสุ่ม และพิกาจูจะเพิ่มระดับสูงขึ้น'
	},
	[109003] = {
		id = 109003,
		fmt = '3. เมื่อพิกาจูมีระดับสูงขึ้นแล้ว จะสามารถปลดล็อคการตกแต่งใหม่ ๆ รวมถึงการเปลี่ยนสีของการตกแต่งและจะปลดล็อคการตกแต่งบรรยากาศคริสต์มาสตามมา'
	},
	[109004] = {
		id = 109004,
		fmt = '4. เมื่อพิกาจูถึงระดับสูงสุดแล้ว ทุกการตกแต่งจะเปิดให้ใช้งานได้ทั้งหมด แต่ยังสามารถใช้หิมะพิเศษเพื่อรับรางวัลได้อย่างต่อเนื่อง'
	},
	[110001] = {
		id = 110001,
		fmt = '1. เกมมินิจะให้ผู้เล่นเลือกภูตที่มี 3 ค่าเลือด ความเร็วในการเคลื่อนที่ และขนาดตัวที่แตกต่างกัน ผู้เล่นสามารถเลือกภูตที่ถนัดก่อนเริ่มเกม'
	},
	[110002] = {
		id = 110002,
		fmt = '2. หลังจากเริ่มเกม ลูกหิมะและกล่องของขวัญจะตกลงมา หากโดนลูกหิมะ 1 ครั้งจะลดพลังชีวิต 1 จุด และหากเก็บกล่องของขวัญได้จะได้รับคะแนน เกมจะสิ้นสุดเมื่อเวลาหมดหรือพลังชีวิตเหลือ 0'
	},
	[110003] = {
		id = 110003,
		fmt = '3. #C0xF76B45#ลูกหิมะตกลงมาเร็วมาก ระวังเงาที่เท้า; เมื่อกล่องของขวัญตกลงจะหายไปในเวลาไม่นาน ต้องรีบเก็บเพื่อรับคะแนน; หากภูตอยู่ในสนามนานขึ้นจะได้รับโบนัสคะแนนเพิ่มเติมด้วย'
	},
	[110004] = {
		id = 110004,
		fmt = '4. เกมมินิเกมเปิดให้เล่นฟรีทุกวันตามจำนวนครั้งที่จำกัด หรือสามารถใช้เพชรเพื่อซื้อจำนวนครั้งเพิ่มเติมได้'
	},
	[110005] = {
		id = 110005,
		fmt = '5. เกมมินิเกมมีการจัดอันดับ คะแนนที่ได้จากแต่ละรอบจะถูกบันทึกและจัดอันดับแสดงผล'
	},
	[110006] = {
		id = 110006,
		fmt = '6. คะแนนที่ได้จากเกมมินิเกมจะถูกสะสมและเมื่อถึงจำนวนที่กำหนดสามารถรับรางวัลได้'
	},
	[111001] = {
		id = 111001,
		fmt = '1. การฝึกเครื่องหมายจะเพิ่มคุณสมบัติให้กับภูตทั้งหมด รีบไปท้าทายยิมเพื่อรับวัสดุการฝึกกันเถอะ!'
	},
	[111002] = {
		id = 111002,
		fmt = '2. จำนวนเครื่องหมายมีจำนวนเท่ากับจำนวนยิมที่เปิดให้เล่น โดยจะเปิดเครื่องหมาย 4 ชิ้นเป็นค่าเริ่มต้น; เมื่อเครื่องหมายมีการสะสมถึงระดับหนึ่ง จะสามารถปลดล็อกเครื่องหมายใหม่ได้'
	},
	[111003] = {
		id = 111003,
		fmt = '3. ทุกเครื่องหมายต้องตั้งภูตคุ้มครอง โดยสามารถให้โบนัสเพิ่มเติมขึ้นอยู่กับการฝึกภูตที่ตั้งคุ้มครองไว้'
	},
	[111004] = {
		id = 111004,
		fmt = '4. เมื่อเครื่องหมายปลุกพลังไปถึงระดับสูง จะสามารถปลดล็อกภูตคุ้มครองใหม่ ๆ เพิ่มเติมได้'
	},
	[112001] = {
		id = 112001,
		fmt = '#C0xF76B45##L10#【กฎพื้นฐาน】'
	},
	[112002] = {
		id = 112002,
		fmt = '1. เวลาเปิดสำหรับการถามคำถามภูต: #C0xF76B45#วันเสาร์ 5:00 น.#C0x5B545B# ถึง #C0xF76B45#วันอาทิตย์ 24:00 น.#C0x5B545B#; เปิดทุกๆ สองสัปดาห์'
	},
	[112003] = {
		id = 112003,
		fmt = '2. เมื่อเปิดคำถามภูตแล้ว ผู้เล่นจะได้รับโอกาสตอบคำถามฟรี 1 ครั้ง โดยการเข้าไปตอบคำถามจะหักจำนวนครั้ง #C0xF76B45#(การออกกลางทางจะถือว่าใช้โอกาสแล้ว)#C0x5B545B#; การรีเซ็ตโอกาสจะเกิดขึ้นในวันถัดไปเวลา 05:00'
	},
	[112004] = {
		id = 112004,
		fmt = '3. ผู้เล่นสามารถใช้เพชรเพื่อรับโอกาสในการตอบคำถามเพิ่มเติม 1 ครั้ง แต่คะแนนที่ได้จากทั้งสองรอบจะใช้คะแนนที่สูงที่สุดในการจัดอันดับ'
	},
	[112005] = {
		id = 112005,
		fmt = '4. ผลการตอบคำถามในวันเสาร์และวันอาทิตย์จะถูกแสดงในอันดับและสมาชิกในกิลด์สามารถเห็นอันดับของตนเองและของกิลด์ได้'
	},
	[112006] = {
		id = 112006,
		fmt = '#C0xF76B45##L10#【กฎการตอบคำถาม】'
	},
	[112007] = {
		id = 112007,
		fmt = '1. การตอบคำถามทั้งหมดมี 15 ข้อ หากตอบผิดหรือไม่ตอบจะได้คะแนน 0 หากตอบถูกจะได้รับคะแนนตามที่กำหนด โดยเวลาที่ตอบเร็วและถูกต้องจะได้คะแนนสูงขึ้น'
	},
	[112008] = {
		id = 112008,
		fmt = '2. ทุกคำถามมีเวลา 15 วินาทีในการตอบ หากเวลานับถอยหลังหมดหรือผู้เล่นยืนยันคำตอบ จะย้ายไปคำถามถัดไป'
	},
	[112009] = {
		id = 112009,
		fmt = '3. คำถามมีทั้งคำถามแบบข้อความ, คำถามแบบรูปภาพ, และคำถามแบบมินิเกม; เมื่อเจอคำถามมินิเกมจะมีคำอธิบายกฎการเล่น'
	},
	[112010] = {
		id = 112010,
		fmt = '4. คะแนนจากการตอบคำถามจะถูกใช้ในการจัดอันดับในกระดาน โดยการจัดอันดับของกิลด์จะคิดจากคะแนนรวมของสมาชิกในกิลด์ (สมาชิกที่ออกจากกิลด์แล้วจะยังคงคะแนนเก่าในกิลด์เก่า)'
	},
	[112011] = {
		id = 112011,
		fmt = '#C0xF76B45##L10#【กฎรางวัลจากการตอบคำถาม】'
	},
	[112012] = {
		id = 112012,
		fmt = 'ทุกครั้งที่ตอบคำถามถูกต้อง ผู้เล่นจะได้รับกระเป๋ารางวัล 1 ใบ โดยสามารถได้รับสูงสุด 15 ใบ และจะเปิดกระเป๋ารางวัลทั้งหมดเมื่อการตอบคำถามสิ้นสุด'
	},
	[112013] = {
		id = 112013,
		fmt = '#C0xF76B45##L10#【กฎการจัดอันดับกิลด์】'
	},
	[112101] = {
		id = 112101,
		fmt = '#C0xF76B45##L10#【กฎการจัดอันดับส่วนบุคคล】'
	},
	[113001] = {
		id = 113001,
		fmt = '1. ในย่านการค้าระหว่างเซิร์ฟเวอร์จะต้องรอการจับคู่จากเซิร์ฟเวอร์ เมื่อจับคู่สำเร็จ จะมีการแสดงสถานะ#C0xF76B45#จับคู่สำเร็จ รอเริ่มการแข่งขัน#C0x5B545B#'
	},
	[113002] = {
		id = 113002,
		fmt = '2. ขั้นตอนในฤดูกาล: #C0xF76B45#การแจ้งเตือนฤดูกาล (1 วัน) — การเริ่มฤดูกาล (วันถัดไปเวลา 10:00 น., ใช้เวลา 3 วัน) — การแสดงผลการสรุปฤดูกาล (เวลาปิดฤดูกาลตอน 22:00 น. ถึงก่อนการแข่งขันครั้งถัดไป)'
	},
	[113003] = {
		id = 113003,
		fmt = '3. ในแต่ละวันเวลา #C0xF76B45#22:00 น. และเมื่อสิ้นสุดฤดูกาลในเวลา #C0xF76B45#22:00 น. จะมีการแจกของรางวัลส่วนบุคคลตามอันดับ#C0x5B545B# และเมื่อสิ้นสุดฤดูกาล ยังมีการแจกของรางวัลจากเซิร์ฟเวอร์ #C0x5B545B#'
	},
	[113004] = {
		id = 113004,
		fmt = '4. การประมูลสามารถทำได้ระหว่างเวลา 10:00-22:00 ทุกวัน ระหว่างเวลาที่เหลือจะเป็นช่วงหยุดพัก โดยร้านค้าจะปิด และไม่สามารถประมูลหรือแก้แค้นได้'
	},
	[113005] = {
		id = 113005,
		fmt = '5. ผู้เล่นจะได้รับการประมูลฟรีจำนวนครั้ง สำหรับการรีเฟรชผู้เล่นในการประมูลหรือการแก้แค้น จะมีการใช้เพชรหรือเหรียญทองในการซื้อมากขึ้น'
	},
	[113006] = {
		id = 113006,
		fmt = '6. ย่านการค้าจะถูกแบ่งเป็น#C0xF76B45#ย่านการค้าระดับสูง และ #C0x5B545B#ย่านการค้าธรรมดา โดยผู้เล่นที่ได้อันดับ 1-10 จะได้รับการจัดอยู่ในย่านการค้าระดับสูง ส่วนที่เหลือจะจัดอยู่ในย่านการค้าธรรมดา'
	},
	[113007] = {
		id = 113007,
		fmt = '8. ในข้อมูลการต่อสู้ จะสามารถดูวิดีโอการต่อสู้ระหว่างผู้เล่นระดับสูงในช่วงเวลาที่ผ่านมา'
	},
	[113008] = {
		id = 113008,
		fmt = '9. ในช่วงฤดูกาล#C0xF76B45#ทุกวันและสิ้นสุดฤดูกาลในเวลา 22:00 น.#C0x5B545B# จะมีการแจกชื่อเรื่องตามอันดับ และผู้เล่น 3 อันดับแรกในกระดาน#C0xF76B45#จะได้รับชื่อเรื่องนั้น ๆ'
	},
	[113020] = {
		id = 113020,
		fmt = '1. อันดับมีความสัมพันธ์กับความเร็วในการผลิตเหรียญทรัพยากรและคะแนนโบนัส โดยเมื่อผู้เล่นครอบครองอันดับนั้นๆ #C0xF76B45#เหรียญทรัพยากรจะผลิตตามความเร็วที่มีอยู่ และจะได้รับคะแนนโบนัสจากอันดับนั้น ๆ การเปลี่ยนแปลงอันดับจะเปลี่ยนความเร็วในการผลิตและคะแนนโบนัสโดยตรง และไม่รวมการคำนวณแบบสะสม'
	},
	[113021] = {
		id = 113021,
		fmt = '2. เหรียญทรัพยากรจะผลิตตลอดทั้งวันตามความเร็วของอันดับ รวมทั้งช่วงที่ไม่ใช่เวลาหยุดพัก และผู้เล่นสามารถประมูลกับผู้เล่นคนอื่นเพื่อรับเหรียญทรัพยากรบางส่วน #C0xF76B45#ซึ่งสามารถใช้ในการซื้อไอเท็มจากร้านหรือใช้ในการพัฒนาคุณสมบัติในคำอวยพร'
	},
	[113022] = {
		id = 113022,
		fmt = '3. คะแนนจะถูกสร้างจากการเปลี่ยนแปลงอันดับ และรางวัลจากการต่อสู้กับบอสในช่วงเวลาจำกัด #C0xF76B45#คะแนนจะถูกนำไปใช้ในการจัดอันดับเมื่อฤดูกาลสิ้นสุด โดยจะใช้คะแนนรวมของผู้เล่น 100 อันดับแรกจากแต่ละเซิร์ฟเวอร์ในการจัดอันดับ'
	},
	[113040] = {
		id = 113040,
		fmt = '1. ก่อนเริ่มการต่อสู้ ผู้เล่นสามารถ #C0xF76B45#จัดทัพทีม 3 ทีม โดยแต่ละทีมสามารถใส่ภูตได้สูงสุด 4 ตัว'
	},
	[113041] = {
		id = 113041,
		fmt = '2. การต่อสู้จะใช้ระบบการนับคะแนนต่อทีม #C0xF76B45#การชนะ 3 รอบจาก 2 จะถือเป็นการชนะสุดท้าย โดยจะต่อสู้สูงสุด 3 รอบ การต่อสู้รอบก่อนหน้าจะไม่ส่งผลต่อรอบถัดไป'
	},
	[113042] = {
		id = 113042,
		fmt = '3. หากภูตทั้ง 2 ทีมจากฝ่ายหนึ่งพ่ายแพ้ จะถือว่าฝ่ายนั้นแพ้ หากรอบการต่อสู้ของทีมย่อยจบโดยไม่สามารถตัดสินผลได้ #C0xF76B45#จะถือว่าทีมป้องกันชนะในรอบนั้น ๆ'
	},
	[113043] = {
		id = 113043,
		fmt = '4. การต่อสู้ในย่านการค้าระหว่างเซิร์ฟเวอร์จะเป็น #C0xF76B45#การต่อสู้แบบอัตโนมัติ#C0x5B545B#'
	},
	[113044] = {
		id = 113044,
		fmt = '5. หากคู่แข่งท้าทายผู้เล่น ระบบจะใช้ทีมป้องกันของผู้เล่นในการต่อสู้'
	},
	[113080] = {
		id = 113080,
		fmt = '1. ผู้เล่นเริ่มต้นการประมูล หาก#C0xF76B45#ชนะการต่อสู้ จะแลกตำแหน่งกับผู้เล่นที่อยู่สูงกว่าตน และรับความเร็วในการผลิตและคะแนนโบนัสจากอันดับใหม่ รวมทั้งบางส่วนของเหรียญทรัพยากรจากคู่แข่ง; หากสู้กับคู่แข่งที่อยู่ต่ำกว่าระดับ จะไม่ได้รับการแลกเปลี่ยนตำแหน่งหรือข้อมูลอื่น ๆ แต่จะได้รับเหรียญทรัพยากรบางส่วนจากคู่แข่ง'
	},
	[113081] = {
		id = 113081,
		fmt = '2. หากคู่แข่งเริ่มการต่อสู้และชนะ สามารถแก้แค้นได้ โดย#C0xF76B45#สามารถแก้แค้นกับเป้าหมายเดิมได้ตามจำนวนจำกัด แก้แค้นยังสามารถได้รับเหรียญทรัพยากรบางส่วนจากเป้าหมาย แต่ไม่สามารถแลกเปลี่ยนตำแหน่งได้ และอาจจะทำให้เป้าหมายเริ่มการแก้แค้นกลับ'
	},
	[113082] = {
		id = 113082,
		fmt = '3. เมื่อเกิดสถานการณ์ดังต่อไปนี้ การประมูลหรือการแก้แค้นแม้จะสำเร็จ ก็ไม่สามารถรับเหรียญทรัพยากรได้:'
	},
	[113083] = {
		id = 113083,
		fmt = '#C0xF76B45#①เมื่อถึงขีดจำกัดจำนวนการประมูลใน 1 ชั่วโมง การต่อสู้ครั้งล่าสุดที่ห่างจากเวลาปัจจุบันเกิน 1 ชั่วโมงจะยกเลิกสถานะนี้'
	},
	[113084] = {
		id = 113084,
		fmt = '#C0xF76B45#②เมื่อทั้งสองฝ่ายมีความแตกต่างของพลังการต่อสู้ที่มีสัดส่วนเกินกำหนด'
	},
	[113085] = {
		id = 113085,
		fmt = '#C0xF76B45#③เมื่อทั้งสองฝ่ายอยู่ในเซิร์ฟเวอร์เดียวกัน'
	},
	[113086] = {
		id = 113086,
		fmt = '#C0xF76B45#④เมื่อถึงขีดจำกัดจำนวนการประมูลในแต่ละวัน'
	},
	[113087] = {
		id = 113087,
		fmt = '4. เป้าหมายที่ถูกประมูล (แย่งเหรียญทรัพยากร) หรือที่ถูกแก้แค้นสำเร็จจะได้รับ#C0xF76B45#การปกป้องจากการประมูลเป็นเวลา 5 นาที ซึ่งในระยะเวลา 5 นาทีนี้จะไม่สามารถถูกโจมตีได้'
	},
	[114001] = {
		id = 114001,
		fmt = '1. ในช่วงเวลาของกิจกรรม จะมีการรีเฟรชบอสจากทีม Rocket ที่สามารถท้าทายในย่านการค้า'
	},
	[114002] = {
		id = 114002,
		fmt = '2. เวลารีเฟรชบอสคือเวลา 12:30 น. และ 18:30 น. ในแต่ละวัน โดยบอสในแต่ละช่วงเวลามีความยากต่างกัน'
	},
	[114003] = {
		id = 114003,
		fmt = '3. ผู้เล่นสามารถท้าทายบอสได้จำนวนครั้งที่ฟรี หรือสามารถซื้อการท้าทายเพิ่มเติมได้'
	},
	[114004] = {
		id = 114004,
		fmt = '4. เมื่อผู้เล่นทำการท้าทายบอสสำเร็จ จะทำการหักพลังชีวิตของบอสและได้รับรางวัลสุ่ม ผู้เล่นที่ทำการฆ่าบอสจะได้รับรางวัลพิเศษ และการฆ่าบอสจะมีการจัดอันดับตามความเสียหายที่ทำได้'
	},
	[114005] = {
		id = 114005,
		fmt = '5. เซิร์ฟเวอร์ที่ผู้เล่นฆ่าบอสจะได้รับโบนัสเพิ่มเติม เช่น การเพิ่มคุณสมบัติ, การเพิ่มผลผลิต, การเพิ่มโอกาสในการแย่งทรัพยากร'
	},
	[114006] = {
		id = 114006,
		fmt = '6. บอสในช่วงเวลากลางคืนจะมีความแข็งแกร่งเป็นพิเศษ และเมื่อฆ่าบอสในช่วงนี้ เซิร์ฟเวอร์ของผู้เล่นที่ฆ่าบอสจะได้รับโบนัสพิเศษอีกด้วย'
	},
	[115001] = {
		id = 115001,
		fmt = '1. กิจกรรมจำกัดปีใหม่เปิดตัวแล้ว! ในช่วงเวลาของกิจกรรม ผู้เล่นสามารถทำภารกิจเพื่อรับรางวัลมากมาย'
	},
	[115002] = {
		id = 115002,
		fmt = '2. ในช่วงกิจกรรมนี้ จะมี 16 ภารกิจที่ต้องสะสมคะแนน ทุกภารกิจมีหมายเลขและหมายเลขเหล่านั้นจะตรงกับหมายเลขของปริศนาภาพทางขวา'
	},
	[115003] = {
		id = 115003,
		fmt = '3. เมื่อทำภารกิจที่ตรงกับหมายเลขแล้ว ผู้เล่นจะได้รับรางวัลจากภารกิจนั้น และจะเปิดไพ่ที่เกี่ยวข้อง'
	},
	[115004] = {
		id = 115004,
		fmt = '4. ด้านขวาของปริศนาและด้านล่างจะแสดงถุงของขวัญ 8 ใบ โดยการทำภารกิจที่ตรงกับหมายเลขในแถว จะเปิดไพ่และได้รับรางวัลจากถุงของขวัญ'
	},
	[115005] = {
		id = 115005,
		fmt = '5. เมื่อหมายเลขทั้ง 16 ตัวถูกเปิดครบ จะได้รับรางวัลถุงของขวัญใหญ่'
	},
	[116001] = {
		id = 116001,
		fmt = '1. ในระหว่างกิจกรรม ผู้เล่นสามารถเข้าร่วมเกมสร้างตึกสูงในแต่ละวันตามจำนวนครั้งที่จำกัด'
	},
	[116002] = {
		id = 116002,
		fmt = '2. เกมมินิเกมต้องการให้ผู้เล่นสร้างชั้นตึกให้สมบูรณ์ภายในเวลาที่กำหนด เพื่อทำการสร้างตึกสูง โดยเกมจะให้โอกาสการสร้าง 3 ครั้งในแต่ละรอบ เกมต้องใช้การวางแผนให้ดี'
	},
	[116003] = {
		id = 116003,
		fmt = '3. ในระหว่างการสร้างจะมีการสุ่มรางวัลการสร้าง ถ้าสามารถสร้างชั้นได้สำเร็จจะได้รับรางวัลนั้น รางวัลจะถูกแสดงเมื่อเกมจบ'
	},
	[116004] = {
		id = 116004,
		fmt = '4. การสร้างยังมีการให้คะแนน โดย#C0xF76B45#ชั้นที่สูงขึ้นและการสร้างที่สมบูรณ์จะได้รับคะแนนที่สูงขึ้น'
	},
	[116005] = {
		id = 116005,
		fmt = '5. คะแนนจากมินิเกมการสร้างตึก, ชั้นที่สร้างได้สำเร็จ, และจำนวนครั้งที่สร้างได้สมบูรณ์จะถูกบันทึกในภารกิจเหรียญตรา การทำภารกิจสำเร็จจะได้รับรางวัลจากภารกิจและคะแนนเหรียญตราเพื่อการอัปเกรดเหรียญตรา'
	},
	[116006] = {
		id = 116006,
		fmt = '6. กระดานคะแนนจะแสดงคะแนนจากผู้เล่นในหลายเซิร์ฟเวอร์ โดยการจัดอันดับจะพิจารณาจากคะแนนการสร้างและจำนวนชั้นที่สร้างสำเร็จ'
	},
	[117001] = {
		id = 117001,
		fmt = '1. การทำภารกิจประจำวันจะได้รับความกระตือรือร้น ซึ่งคะแนนความกระตือรือร้นที่สะสมจะปลดล็อกรางวัลจากตั๋วผ่าน'
	},
	[117002] = {
		id = 117002,
		fmt = '2. การซื้อบัตรผ่านหรูหรา จะสามารถปลดล็อกรางวัลพิเศษเพิ่มเติมได้'
	},
	[117003] = {
		id = 117003,
		fmt = '3. บัตรผ่านหรูหราแต่ละช่วงจะมีผลภายในกิจกรรมช่วงนั้นเท่านั้น ในกิจกรรมครั้งถัดไปต้องซื้อใหม่ และคะแนนความกระตือรือร้นจะถูกรีเซ็ตเมื่อกิจกรรมสิ้นสุด'
	},
	[117004] = {
		id = 117004,
		fmt = '4. เมื่อกิจกรรมบัตรผ่านสิ้นสุด รางวัลที่ยังไม่ได้รับจะถูกส่งทางอีเมล'
	},
	[118001] = {
		id = 118001,
		fmt = '1. ทุกวันผ่านสวนสนุกเอเธอร์ ผู้เล่นจะสะสมชั้นที่ผ่าน(ต้องจบการท้าทายบอสในแต่ละชั้น) และสามารถปลดล็อกรางวัลที่ยอดเยี่ยมจากบัตรผ่าน'
	},
	[118002] = {
		id = 118002,
		fmt = '2. การซื้อบัตรผ่านหรูหรา จะสามารถปลดล็อกรางวัลพิเศษเพิ่มเติมได้'
	},
	[118003] = {
		id = 118003,
		fmt = '3. บัตรผ่านหรูหราแต่ละช่วงจะมีผลภายในกิจกรรมช่วงนั้นเท่านั้น และต้องซื้อใหม่ในกิจกรรมครั้งถัดไป คะแนนจากการผ่านชั้นจะถูกรีเซ็ตเมื่อกิจกรรมสิ้นสุด'
	},
	[118004] = {
		id = 118004,
		fmt = '4. เมื่อกิจกรรมบัตรผ่านสิ้นสุด รางวัลที่ยังไม่ได้รับจะถูกส่งทางอีเมล'
	},
	[119001] = {
		id = 119001,
		fmt = '#C0xFF5B545B#1. การท้าทายดันเจี้ยนแต่ละครั้งจะสะสมจำนวนครั้ง (#C0xF76B45#การท้าทายดันเจี้ยนของผู้เล่นจะไม่ถูกนับครั้ง#C0xFF5B545B#); ยิ่งท้าทายดันเจี้ยนมากขึ้น รางวัลที่ปลดล็อคก็จะยิ่งมีค่ามากขึ้น'
	},
	[119002] = {
		id = 119002,
		fmt = '2. การซื้อบัตรผ่านหรูหรา จะสามารถปลดล็อกรางวัลพิเศษเพิ่มเติมได้'
	},
	[119003] = {
		id = 119003,
		fmt = '3. บัตรผ่านหรูหราแต่ละช่วงจะมีผลภายในกิจกรรมช่วงนั้นเท่านั้น และต้องซื้อใหม่ในกิจกรรมครั้งถัดไป คะแนนจากการท้าทายดันเจี้ยนจะถูกรีเซ็ตเมื่อกิจกรรมสิ้นสุด'
	},
	[119004] = {
		id = 119004,
		fmt = '4. เมื่อกิจกรรมบัตรผ่านสิ้นสุด รางวัลที่ยังไม่ได้รับจะถูกส่งทางอีเมล'
	},
	[120001] = {
		id = 120001,
		fmt = '1. ขว้างลูกเต๋าเพื่อเดินไปข้างหน้า บนแผนที่มีสมบัติ#C0xF76B45#ที่รางวัลมากมาย และหลังจากได้รับแล้ว จะปรากฏอีกครั้งแบบสุ่มบนแผนที่ ใช้การตามหากล่องสมบัติเป็นเป้าหมายของคุณ!'
	},
	[120002] = {
		id = 120002,
		fmt = '2. เมื่อเดินไปบนแผนที่ คุณยังอาจพบกับช่องเหตุการณ์อื่น ๆ บนแผนที่ โดย#C0xF76B45#คลิกที่ช่องเหตุการณ์บนแผนที่เพื่อดูคำอธิบายเพิ่มเติม'
	},
	[120003] = {
		id = 120003,
		fmt = '3. ในช่องเหตุการณ์#C0xF76B45#ร้านค้าและกล่องสมบัติจะถูกเปิดเมื่อผ่านจุดนั้นไป#C0x5B545B#หลังจากเหตุการณ์สิ้นสุดลง หากยังสามารถเคลื่อนที่ได้ เทรนเนอร์จะเดินต่อไป; #C0xF76B45#ช่องเหตุการณ์อื่น ๆ จะต้องหยุดเพื่อเปิดใช้งาน'
	},
	[120004] = {
		id = 120004,
		fmt = '4. ในการผจญภัย คุณสามารถรับ#C0xF76B45#เหรียญตรานักผจญภัย#C0x5B545B#ซึ่งจะช่วยให้คุณสามารถซื้อไอเท็มจากร้านค้าได้เมื่อผ่านจุดนั้น โปรดทราบว่าเหรียญตรานี้ใช้ได้เฉพาะในการซื้อไอเท็มที่ใช้ในการผจญภัย'
	},
	[120005] = {
		id = 120005,
		fmt = '5. ในระหว่างการผจญภัย คุณจะได้รับการ์ดไอเท็มและลูกเต๋าที่มีคุณสมบัติพิเศษ หากคุณไม่แน่ใจว่าใช้งานอย่างไร#C0xF76B45#สามารถดูคำอธิบายไอเท็มด้านล่างได้'
	},
	[121001] = {
		id = 121001,
		fmt = '#L10##C0xF76B45# ร่วมกันที่นี่ในวันนี้ ดอกไม้ยังงดงามกว่าปีที่ผ่านมา 。#C0xFF5B545B#—จากเทรนเนอร์ทั่วโลกที่นำภูตของพวกเขามาเริ่มฤดูกาลการแข่งโปเกม่อนประจำปี'
	},
	[121002] = {
		id = 121002,
		fmt = 'ฤดูกาลการแข่งโปเกม่อนทั้งหมดประกอบด้วย: การทายผลมีรางวัล, การเตรียมตัวก่อนการแข่งขัน, การแข่งขันกำลังดำเนินการ, และการประกาศผล'
	},
	[121003] = {
		id = 121003,
		fmt = '#L10##C0xF76B45#【การทายผลมีรางวัล】:'
	},
	[121004] = {
		id = 121004,
		fmt = '1. ในระหว่างกิจกรรมจะมีการแข่งขันสองรอบต่อวัน (เวลา 12:00 และ 20:00) ทุกการแข่งขันจะเลือกโปเกม่อน 4 ตัวแบบสุ่มเข้าร่วมการแข่งขัน'
	},
	[121005] = {
		id = 121005,
		fmt = '2. แม้ว่าเทรนเนอร์จะไม่สามารถร่วมฝึกกับโปเกม่อนได้ แต่สามารถทายผลล่วงหน้าก่อนการแข่งขันได้; ผลการทายผลจะประกาศเมื่อการแข่งขันสิ้นสุด'
	},
	[121006] = {
		id = 121006,
		fmt = '3. เวลาการทายผลมีรางวัลจะอยู่ระหว่าง: ทุกวันเวลา 05:00-11:57 และ 13:00-19:57; จะไม่สามารถทายผลในช่วงเวลาอื่นได้'
	},
	[121007] = {
		id = 121007,
		fmt = '4. การทายผลต้องใช้เพชรในการลงเดิมพัน โดยแต่ละครั้งสามารถเลือกได้เพียงโปเกม่อนตัวเดียวในการทายผล'
	},
	[121008] = {
		id = 121008,
		fmt = '#L10##C0xF76B45#【การเตรียมตัวก่อนการแข่งขัน】'
	},
	[121009] = {
		id = 121009,
		fmt = '1. ในช่วงการเตรียมตัวก่อนการแข่งขันจะใช้เวลา 3 นาที และในระหว่างนี้การทายผลจะถูกปิด'
	},
	[121010] = {
		id = 121010,
		fmt = '#L10##C0xF76B45#【ระหว่างการแข่งขัน】:'
	},
	[121011] = {
		id = 121011,
		fmt = '1. การแข่งขันจะเริ่มตรงเวลา 12:00 และ 20:00 ทุกวัน โดยใช้เวลาทั้งหมด 3 นาที'
	},
	[121012] = {
		id = 121012,
		fmt = '2. โปเกม่อนแต่ละตัวมีค่าพื้นฐานต่างกัน โดยความเร็วและอัตราการวิ่งพิเศษจะเป็นสองตัวชี้วัดที่สำคัญ'
	},
	[121013] = {
		id = 121013,
		fmt = '3. คำอธิบายตัวชี้วัดต่าง ๆ:'
	},
	[121014] = {
		id = 121014,
		fmt = 'a. ความเร็ว, ความเร็วเริ่มต้นของโปเกม่อนในการแข่งขัน'
	},
	[121015] = {
		id = 121015,
		fmt = 'b. ความทนทาน, โปเกม่อนจะใช้พลังงานในระหว่างการแข่งขัน หากพลังงานหมด จะเข้าสู่สถานะอ่อนแอ (ในสถานะนี้ความเร็วจะลดลง); เมื่อพลังงานฟื้นกลับมา สถานะอ่อนแอจะหายไป'
	},
	[121016] = {
		id = 121016,
		fmt = 'c. อัตราการวิ่งพิเศษ, โปเกม่อนจะมีโอกาสพิเศษในการวิ่งเร็วขึ้นในระหว่างการแข่งขัน ความเร็วจริงจะเพิ่มขึ้นตามอัตรานี้'
	},
	[121017] = {
		id = 121017,
		fmt = 'd. ระยะเวลาการวิ่งพิเศษ, ระยะเวลาที่โปเกม่อนจะวิ่งเร็วเมื่อเกิดอัตราการวิ่งพิเศษ'
	},
	[121018] = {
		id = 121018,
		fmt = '#L10##C0xF76B45#【การประกาศผล】:'
	},
	[121019] = {
		id = 121019,
		fmt = '1. การแข่งขันจะสิ้นสุดเมื่อภูตทั้งหมดถึงจุดหมาย'
	},
	[121020] = {
		id = 121020,
		fmt = '2. เมื่อการแข่งขันสิ้นสุดลง เทรนเนอร์สามารถรับรางวัลจากการทายผลใน【ประวัติการแข่งขัน】(เทรนเนอร์ที่ไม่เคยทายผลจะไม่ได้รับรางวัลใด ๆ) และยังสามารถชมการแข่งขันย้อนหลังได้'
	},
	[121021] = {
		id = 121021,
		fmt = '3. รางวัลจากการทายผลประกอบด้วยสองส่วน: คะแนนจากการทายผลและรางวัลไอเท็ม; เมื่อสะสมคะแนนจากการทายผลถึงจำนวนหนึ่งแล้ว สามารถรับรางวัลตามขั้นใน【รางวัลคะแนน】ได้'
	},
	[121022] = {
		id = 121022,
		fmt = '#L10#4. ตัวอย่างรางวัลจากการทายผล:'
	},
	[122001] = {
		id = 122001,
		fmt = '#C0xF76B45#【กฎพื้นฐาน】'
	},
	[122002] = {
		id = 122002,
		fmt = '1. ในระหว่างกิจกรรมจะฟื้นฟูจำนวนการท้าทาย 3 ครั้งต่อวัน โดยเวลาฟื้นฟูคือเวลา 5:00 น. และจำนวนครั้งสูงสุดที่สะสมได้คือ 10 ครั้ง'
	},
	[122003] = {
		id = 122003,
		fmt = '2. เมื่อเริ่มท้าทายภูต สามารถเลือกภูต 3 ตัวเพื่อเป็นตัวเริ่มต้น'
	},
	[122004] = {
		id = 122004,
		fmt = '3. ภูตเริ่มต้นพิเศษมีเงื่อนไขการปลดล็อกพิเศษ ต้องปลดล็อกก่อนจึงจะสามารถใช้งานได้'
	},
	[122005] = {
		id = 122005,
		fmt = '4. ก่อนเริ่มท้าทายสามารถปรับเปลี่ยนภูตที่เข้าร่วมได้ตามข้อมูลของฝ่ายตรงข้าม'
	},
	[122006] = {
		id = 122006,
		fmt = '5. หลังจากชนะในแต่ละการต่อสู้ ผู้เล่นสามารถเลือกเหรียญตราได้จาก 3 ตัวเลือก'
	},
	[122007] = {
		id = 122007,
		fmt = '6. หากใช้ชุดภูตเริ่มต้นเดียวกัน 3 ครั้งติดต่อกัน จะได้รับรางวัลเหรียญตราในตอนเริ่มต้น; การท้าทายในครั้งแรกของแต่ละวันจะได้รับรางวัลเหรียญตราเพิ่มเติม อย่าพลาดโอกาสนี้'
	},
	[122008] = {
		id = 122008,
		fmt = '7. เหรียญตรามีบทบาทสำคัญในผลการต่อสู้ ดังนั้นควรเลือกให้ดี'
	},
	[122009] = {
		id = 122009,
		fmt = '8. การเอาชนะบอสสุดท้ายจะถือเป็นการผ่านด่านในรอบนั้น ๆ และจะบันทึกจำนวนครั้งที่ผ่านด่านและรอบการท้าทาย'
	},
	[122010] = {
		id = 122010,
		fmt = '9. ในระหว่างกิจกรรมจะมีการบันทึกความคืบหน้าในการท้าทาย หากผ่านด่านหรือแพ้ จะมีการรีเซ็ตกระบวนการ'
	},
	[122011] = {
		id = 122011,
		fmt = '10. ในระหว่างกิจกรรม ผู้เล่นสามารถท้าทายซ้ำได้และยังคงได้รับรางวัลสำหรับความสำเร็จใหม่ ๆ ที่เกิดขึ้น'
	},
	[122012] = {
		id = 122012,
		fmt = '#C0xF76B45#【กฎการต่อสู้】'
	},
	[122013] = {
		id = 122013,
		fmt = '1. หลังจากการต่อสู้จะรักษาค่าพลังชีวิตทั้งหมดของภูตที่ยังมีชีวิตอยู่และค่าพลังโกรธของภูตที่เริ่มต้นไว้ โดยภูตที่เข้าร่วมหลังจะมีค่าพลังโกรธคงที่'
	},
	[122014] = {
		id = 122014,
		fmt = '2. ในระหว่างการต่อสู้ หากภูตตายจะไม่สามารถนำกลับมาใช้ได้อีก'
	},
	[122015] = {
		id = 122015,
		fmt = '3. ด่านที่ชนะแล้วจะไม่สามารถท้าทายซ้ำได้'
	},
	[122016] = {
		id = 122016,
		fmt = '#C0xF76B45#【กฎรางวัล】'
	},
	[122017] = {
		id = 122017,
		fmt = '1. #C0xF76B45#เมื่อกิจกรรมสิ้นสุดลง รางวัลจากความสำเร็จทั้งหมดจะไม่ถูกส่งให้ โปรดรับรางวัลก่อนกิจกรรมจะสิ้นสุด#C0x5B545B#'
	},
	[122018] = {
		id = 122018,
		fmt = '2. เมื่อผ่านด่านครั้งแรก ผู้เล่นจะได้รับรางวัลจากการผ่านด่านครั้งแรก และการท้าทายในครั้งถัดไปจะได้รับรางวัลการท้าทาย'
	},
	[122019] = {
		id = 122019,
		fmt = '3. ในระหว่างกิจกรรม ผู้เล่นจะสามารถรับรางวัลทองคำจากการท้าทายในด่านได้สูงสุด #Icommon/icon/icon_gold.png-56-56# 8000000'
	},
	[123001] = {
		id = 123001,
		fmt = '#L10##C0xF76B45#【กฎชุดของขวัญ】'
	},
	[123002] = {
		id = 123002,
		fmt = '1. การจัดชุดของขวัญพิเศษจะถูกกำหนดตามสถานะของเทรนเนอร์ก่อนที่ชุดของขวัญจะถูกเปิดใช้งาน'
	},
	[123003] = {
		id = 123003,
		fmt = '2. ชุดของขวัญจะจำหน่ายในช่วงเวลาจำกัด เทรนเนอร์อย่าพลาดโอกาสดี ๆ'
	},
	[123004] = {
		id = 123004,
		fmt = '3. ชุดของขวัญนี้จะถูกส่งออกมาเพียงครั้งเดียว และจะไม่มีชุดของขวัญใหม่เพิ่มเข้ามาในรายการของขวัญพิเศษ'
	},
	[123005] = {
		id = 123005,
		fmt = '4. เมื่อเทรนเนอร์พัฒนาความสามารถของตัวเองในอนาคต ชุดของขวัญที่ดีกว่าจะแสดงให้เห็นในครั้งถัดไปของการเปิดใช้งานชุดของขวัญพิเศษ โปรดติดตาม'
	},
	[124001] = {
		id = 124001,
		fmt = '#C0xF76B45#【กฎพื้นฐาน】'
	},
	[124002] = {
		id = 124002,
		fmt = '1. การปลุกพลัง Z สามารถเพิ่มคุณสมบัติของภูตได้'
	},
	[124003] = {
		id = 124003,
		fmt = '2. การปลุกพลัง Z จะเสริมความสามารถของทักษะของภูตในระดับหนึ่ง'
	},
	[124004] = {
		id = 124004,
		fmt = '3. การปลุกพลัง Z ของภูตที่อยู่ในสายวิวัฒนาการเดียวกัน (ไม่รวมวิวัฒนาการระดับสูง) จะใช้การฝึกเดียวกันได้'
	},
	[124005] = {
		id = 124005,
		fmt = '4. เมื่อภูตทำการปลุกพลัง Z แล้ว จะสามารถเพิ่มระดับพลังการปลุกพลัง และได้รับโบนัสคุณสมบัติเพิ่มเติมสำหรับทั้งทีม'
	},
	[124006] = {
		id = 124006,
		fmt = '5. เมื่อวิวัฒนาการเป็นระดับสูงแล้ว การปลุกพลัง Z ที่เคยทำไว้จะถูกรีเซ็ตและภูตที่วิวัฒนาการใหม่ต้องเริ่มต้นการปลุกพลัง Z ใหม่'
	},
	[124007] = {
		id = 124007,
		fmt = '6. เศษชิ้นส่วนการปลุกพลัง Z เป็นชิ้นส่วนใหม่ที่ไม่สามารถรวมกันเป็นภูตที่สมบูรณ์ได้'
	},
	[124008] = {
		id = 124008,
		fmt = '7. เศษชิ้นส่วนการปลุกพลัง Z ของภูตที่อยู่ในสายวิวัฒนาการที่แตกต่างกันจะไม่เหมือนกัน'
	},
	[124009] = {
		id = 124009,
		fmt = '8. เศษชิ้นส่วนการปลุกพลัง Z สามารถใช้ในการฝึกปลุกพลัง Z ของภูต, การฝึกคุณสมบัติสุดขีด หรือเป็นวัสดุในการวิวัฒนาการระดับสูง'
	},
	[124010] = {
		id = 124010,
		fmt = '9. คำอธิบายการรีเซ็ตการปลุกพลัง Z:'
	},
	[124011] = {
		id = 124011,
		fmt = '① การรีเซ็ตจะคืนทรัพยากรการฝึกพลัง Z กลับมา 100% โดยชิ้นส่วนการปลุกพลัง Z ที่ได้คืนจะยังคงเป็นชิ้นส่วนการปลุกพลัง Z และจะไม่เปลี่ยนเป็นภูตหรือเศษชิ้นส่วนภูต'
	},
	[124012] = {
		id = 124012,
		fmt = '② ชิ้นส่วนภูตหรือเศษชิ้นส่วนภูตที่ถูกใช้ไปแล้วจะถูกแปลงกลับเป็นชิ้นส่วนการปลุกพลัง Z'
	},
	[124101] = {
		id = 124101,
		fmt = '#C0xF76B45#【คำอธิบายพลังปลุกพลัง】'
	},
	[124102] = {
		id = 124102,
		fmt = '1. ค่าประสบการณ์ของระดับพลังปลุกพลังมาจากการปลุกพลัง Z ของทุกสายวิวัฒนาการของภูต'
	},
	[124103] = {
		id = 124103,
		fmt = '2. ทุกครั้งที่ปลุกพลัง Z เสร็จ จะได้รับค่าประสบการณ์บางส่วน'
	},
	[124104] = {
		id = 124104,
		fmt = '3. เมื่อค่าประสบการณ์เพียงพอ ระดับพลังปลุกพลังจะเพิ่มขึ้นโดยอัตโนมัติ'
	},
	[124105] = {
		id = 124105,
		fmt = '4. หากการปลุกพลัง Z ของภูตถูกรีเซ็ต ค่าประสบการณ์ของพลังปลุกพลังจะถูกลดลงตามที่ได้ใช้ไว้'
	},
	[124106] = {
		id = 124106,
		fmt = '5. เมื่อค่าประสบการณ์หายไป ระดับและผลประโยชน์ที่ได้รับจากพลังปลุกพลังก็จะไม่สามารถใช้งานได้'
	},
	[124201] = {
		id = 124201,
		fmt = '1. ในระหว่างกิจกรรม ผู้เล่นสามารถมอบหมายให้ภูตทำภารกิจ และเมื่อเสร็จสิ้นภารกิจจะได้รับรางวัลมากมาย'
	},
	[124202] = {
		id = 124202,
		fmt = '2. การทำภารกิจต้องส่งภูตที่ตรงตามข้อกำหนดของภารกิจ โดยจะหักคะแนนการเคลื่อนไหวและใช้เวลาบางส่วน หาก#C0xF76B45#ทำภารกิจสำเร็จตามข้อกำหนด จะได้รับรางวัลพิเศษเพิ่มเติม!'
	},
	[124203] = {
		id = 124203,
		fmt = '3. ภารกิจแบ่งเป็นภารกิจหลักและภารกิจเสริม ซึ่งจะแสดงอยู่ในแผนที่ตามลำดับ จำเป็นต้อง#C0xF76B45#ทำภารกิจที่มีเงื่อนไขก่อนจึงจะสามารถทำภารกิจถัดไปได้'
	},
	[124204] = {
		id = 124204,
		fmt = '4. ภารกิจเสริมมี#C0xF76B45#บางภารกิจที่สามารถทำซ้ำได้ และยังมี#C0x5B545B#รางวัลกล่องสมบัติที่#C0xF76B45#ให้รางวัลโดยไม่ต้องใช้เวลา#C0x5B545B# ส่วนภารกิจที่สามารถทำซ้ำ#C0xF76B45#จะได้รับรางวัลที่ดีมาก'
	},
	[124205] = {
		id = 124205,
		fmt = '5. ภารกิจทั้งหมดที่แสดงบนแผนที่ (รวมถึงกล่องสมบัติ) หากยังไม่เสร็จสามารถคลิกเพื่อดูรายละเอียดได้'
	},
	[124206] = {
		id = 124206,
		fmt = '4. ผู้เล่นต้องมอบหมายภูตทำภารกิจด้วยตนเอง เมื่อเสร็จภารกิจอย่าลืม#C0xF76B45#รับรางวัลด้วยตัวเอง#C0x5B545B#และสามารถทำภารกิจได้สูงสุด 3 ภารกิจพร้อมกัน (รวมภารกิจที่ทำเสร็จแล้วแต่ยังไม่ได้รับรางวัล)'
	},
	[124207] = {
		id = 124207,
		fmt = '5. ขณะทำภารกิจ ผู้เล่นสามารถยกเลิกภารกิจได้ หากยกเลิกภารกิจแล้ว การนับเวลาจะรีเซ็ตกลับเป็นศูนย์ และคะแนนการเคลื่อนไหวจะได้รับคืน แต่จะไม่ได้รับรางวัลจากภารกิจนั้น ๆ'
	},
	[124301] = {
		id = 124301,
		fmt = '1. ยินดีต้อนรับสู่เขตล่าสัตว์ ตามตำนาน วิธีการล่าที่ดีที่สุดคือการทำให้ตัวเองกลายเป็นเหยื่อ'
	},
	[124302] = {
		id = 124302,
		fmt = '2. ในเขตล่าสัตว์ ผลของการเพิ่มพลังที่ได้รับจากการชนะการต่อสู้ การเลือกการรักษาและการเติมเต็มที่เหมาะสมจะช่วยให้ผ่านด่านได้'
	},
	[124303] = {
		id = 124303,
		fmt = '3. เขตล่าสัตว์แบ่งออกเป็นสองเส้นทาง ได้แก่ เส้นทางปกติและเส้นทางขั้นสูง ซึ่งเนื้อหา ความก้าวหน้า และผลการเพิ่มพลังจะเป็นอิสระและไม่ส่งผลกระทบต่อกัน'
	},
	[124304] = {
		id = 124304,
		fmt = '4. เส้นทางปกติจะฟื้นฟูการท้าทายทุก 48 ชั่วโมง และเส้นทางขั้นสูงจะฟื้นฟูการท้าทายทุก 96 ชั่วโมง; เวลาฟื้นฟูคือเวลา 5:00 น. โดยการฟื้นฟูจะสะสมได้สูงสุด 5 ครั้ง'
	},
	[124305] = {
		id = 124305,
		fmt = '5. เมื่อเปิดเส้นทางแล้วจนถึงจุดฟื้นฟูการท้าทายของเส้นทางนั้น จะสามารถบันทึกสถานะการท้าทายของเส้นทางได้ ระบบจะรีเซ็ตเนื้อหาของเส้นทางนั้นเมื่อถึงจุดฟื้นฟูการท้าทาย'
	},
	[124306] = {
		id = 124306,
		fmt = '6. ในระหว่างการท้าทายหรือหลังจากผ่านด่านแล้ว ผู้เล่นสามารถเลือกที่จะจบการท้าทายด้วยตนเองหรือรอให้ระบบรีเซ็ตเนื้อหาของเส้นทาง'
	},
	[124307] = {
		id = 124307,
		fmt = '7. เมื่อผู้เล่นถึงระดับที่กำหนดแล้ว การขับเคลื่อนจะเปิดใช้งาน โดยผู้เล่นสามารถขับเคลื่อนการต่อสู้ที่มีคะแนนสูงสุดตามผลการแสดงที่ดีที่สุดของตนในอดีต การขับเคลื่อนจะช่วยให้ผ่านด่านได้โดยไม่มีความเสียหายและได้รับรางวัลทั้งหมด'
	},
	[124401] = {
		id = 124401,
		fmt = '#F40##L10#คำอธิบายการล้างคุณสมบัติ：'
	},
	[124402] = {
		id = 124402,
		fmt = '#F36#1. ชิปแต่ละตัวสามารถเลือกคุณสมบัติในการล้างได้สูงสุด 2 รายการ'
	},
	[124403] = {
		id = 124403,
		fmt = '#F36#2. เมื่อเลือกคุณสมบัติในการล้างแล้ว รายการคุณสมบัติที่เลือกจะถูกล็อก และไม่สามารถยกเลิกหรือเปลี่ยนแปลงเป้าหมายในการล้างได้ การกระทำนี้ไม่สามารถย้อนกลับได้ โปรดเลือกคุณสมบัติที่ต้องการล้างอย่างระมัดระวัง'
	},
	[124404] = {
		id = 124404,
		fmt = '#F36#3. เมื่อทำการล้างคุณสมบัติ จะมีการรีเซ็ตประเภทของคุณสมบัติสุ่มที่เลือกในการล้างและจำนวนครั้งการเสริมพลังของคุณสมบัติสุ่มทั้งหมด'
	},
	[124501] = {
		id = 124501,
		fmt = '1. ในการฟื้นฟูชิปเรียนรู้ ผู้เล่นสามารถรีเซ็ตชิปเรียนรู้ที่ได้ฝึกฝนแล้วกลับสู่สถานะเริ่มต้นระดับ 1'
	},
	[124502] = {
		id = 124502,
		fmt = '2. หลังจากฟื้นฟูชิปเรียนรู้แล้ว จะได้รับทรัพยากรการฝึกฝนระดับ 100% กลับคืน ผู้เล่นสามารถใช้ทรัพยากรเหล่านี้ในการฝึกชิปเรียนรู้อื่น ๆ ใหม่ได้'
	},
	[124503] = {
		id = 124503,
		fmt = '3. หลังจากฟื้นฟูชิปเรียนรู้แล้ว เมื่อเสริมพลังจนถึงระดับเดิม ค่าพลังและจำนวนครั้งในการเสริมพลังจะไม่เปลี่ยนแปลง กล่าวคือ การฟื้นฟูจะคืนทรัพยากรเท่านั้น จะไม่สุ่มคุณสมบัติใหม่'
	},
	[124504] = {
		id = 124504,
		fmt = '4. การฟื้นฟูชิปเรียนรู้ต้องใช้เพชร จำนวนเพชรที่ใช้จะเพิ่มขึ้นตามระดับการฝึกฝนของชิปเรียนรู้ที่ฟื้นฟู; จำนวนเพชรสูงสุดที่ใช้ในการฟื้นฟูชิปเรียนรู้ 1 ตัวคือ 100 #Icommon/icon/icon_diamond.png-56-56#'
	},
	[124505] = {
		id = 124505,
		fmt = '5. ชิปเรียนรู้ที่ยังไม่ได้ฝึกไม่สามารถฟื้นฟูได้ และจะไม่ปรากฏในหน้าจอชิปเรียนรู้ที่สามารถฟื้นฟูได้'
	},
	[124601] = {
		id = 124601,
		fmt = '1. การใส่ชิปจะเพิ่มพลังการต่อสู้ของภูต'
	},
	[124602] = {
		id = 124602,
		fmt = '2. ทุกชิปมีคุณสมบัติคงที่ 1-2 รายการ และคุณสมบัติสุ่มจำนวนหนึ่ง'
	},
	[124603] = {
		id = 124603,
		fmt = '3. ชิปมีชุดคุณสมบัติที่เกี่ยวข้อง หากใส่ชิปจากชุดเดียวกัน 2/4 ชิ้น จะสามารถเปิดใช้งานชุดคุณสมบัติของชุดนั้นได้ ยิ่งชิปมีคุณภาพสูง ชุดคุณสมบัติจะยิ่งดีขึ้น'
	},
	[124604] = {
