	},
	[124620] = {
		id = 124620,
		fmt = 'ความเร็วในการฟื้นฟูพลังงาน, การโจมตีทั้งสอง, การป้องกันทั้งสอง, ความต้านทานการวิจารณ์, ความเสียหายวิจารณ์, การดูดเลือด, การทำลายการป้องกัน, การเพิ่มความเสียหาย, การเพิ่มการโจมตีพิเศษ'
	},
	[124701] = {
		id = 124701,
		fmt = '1. การเสริมพลังสามารถเพิ่มระดับของชิปได้ โดยระดับที่สูงขึ้นจะทำให้ค่าสถานะหลักสูงขึ้น'
	},
	[124702] = {
		id = 124702,
		fmt = '2. การเสริมพลังต้องใช้เหรียญทอง และชิปอื่นหรือวัสดุเสริมพลังเฉพาะ'
	},
	[124703] = {
		id = 124703,
		fmt = '3. หากใช้ชิปที่มีระดับสูงกว่า 1 เป็นวัสดุในการเสริมพลัง เมื่อการเสริมพลังสำเร็จ เหรียญทองที่ใช้ในการเสริมพลังชิปที่ใช้เป็นวัสดุจะถูกส่งคืน'
	},
	[124704] = {
		id = 124704,
		fmt = '4. การเพิ่มระดับยังสามารถปลดล็อกคุณสมบัติสุ่มใหม่และการเสริมพลังของคุณสมบัติสุ่มที่ได้รับแล้ว โดยการเสริมพลังแต่ละคุณสมบัติสุ่มจะมีขีดจำกัดในการเสริมพลัง'
	},
	[124705] = {
		id = 124705,
		fmt = '5. คำอธิบายระดับคุณสมบัติของชิป:'
	},
	[124706] = {
		id = 124706,
		fmt = '#C0x5B545B#คุณภาพ'
	},
	[124707] = {
		id = 124707,
		fmt = 'ระดับการปลดล็อกคุณสมบัติ'
	},
	[124708] = {
		id = 124708,
		fmt = 'ระดับการเสริมพลังคุณสมบัติ'
	},
	[124801] = {
		id = 124801,
		fmt = '#L10##C0xF76B45# หน้าร้อนที่แผดเผา มาทำไอศกรีมเกล็ดหิมะเย็นๆ เพื่อคลายความร้อนในใจ'
	},
	[124802] = {
		id = 124802,
		fmt = '#L10##C0xF76B45#【กฎกิจกรรม】:'
	},
	[124803] = {
		id = 124803,
		fmt = '1. เมื่อกิจกรรมเริ่มต้น เทรนเนอร์จะต้องทำไอศกรีมเกล็ดหิมะให้โปเกม่อนเพื่อช่วยคลายร้อน'
	},
	[124804] = {
		id = 124804,
		fmt = '2. เมื่อโปเกม่อนขึ้นสนามจะบอกรสชาติไอศกรีมที่ชอบ เทรนเนอร์ต้องจำความต้องการของโปเกม่อนให้ได้ก่อนที่แถบความคืบหน้าจะสิ้นสุด'
	},
	[124805] = {
		id = 124805,
		fmt = '3. เมื่อแถบความคืบหน้าจบลง โปเกม่อนจะซ่อนความต้องการที่ได้บอกไว้ก่อนหน้านี้ ผู้เล่นต้องเลือกตามความจำที่มี'
	},
	[124806] = {
		id = 124806,
		fmt = '4. เมื่อโปเกม่อนตัวแรกบอกความต้องการแล้ว ผู้เล่นต้องคลิกที่【เริ่มทำ】เพื่อเปิดตู้เย็นและทำไอศกรีมเกล็ดหิมะให้กับโปเกม่อน'
	},
	[124807] = {
		id = 124807,
		fmt = '5. หลังจากเลือกเสร็จแล้ว โปเกม่อนจะให้คะแนนการเลือกของผู้เล่น โดยแบ่งเป็น 3 ระดับ'
	},
	[124808] = {
		id = 124808,
		fmt = '#C0xF76B45#บริการสมบูรณ์แบบ: #C0x5B545B#ไม่มีข้อผิดพลาดและไม่มีข้อผิดพลาดในลำดับ'
	},
	[124809] = {
		id = 124809,
		fmt = '#C0xF76B45#บริการดี: #C0x5B545B#ไม่มีข้อผิดพลาดแต่ลำดับผิด'
	},
	[124810] = {
		id = 124810,
		fmt = '#C0xF76B45#บริการมีข้อบกพร่อง: #C0x5B545B#มีความต้องการที่เลือกผิด'
	},
	[124811] = {
		id = 124811,
		fmt = '6. หลังจากบริการจะมีการแสดงผลการบริการ, #C0xF76B45#แต่โปรดระวัง ลูกค้าต่อไปจะขึ้นมาเสนอความต้องการอย่างรวดเร็ว อย่าลืมเวลาจำได้นะ#C0x5B545B#'
	},
	[124812] = {
		id = 124812,
		fmt = '7. เมื่อจำนวนรอบบริการเพิ่มขึ้น ความต้องการของโปเกม่อนอาจจะมากขึ้น'
	},
	[124813] = {
		id = 124813,
		fmt = '8. เมื่อเวลานับถอยหลังสิ้นสุด จะหยุดให้บริการ และจะคำนวณรางวัลสุดท้ายตามสถานะการบริการของเทรนเนอร์'
	},
	[124901] = {
		id = 124901,
		fmt = '#L10##C0xF76B45# เงาของการเคลื่อนไหวบนชายหาด การเล่นวอลเลย์บอลของโปเกม่อนเริ่มต้นแล้ว!'
	},
	[124902] = {
		id = 124902,
		fmt = '#L10##C0xF76B45#【กิจกรรมกฎ】:'
	},
	[124903] = {
		id = 124903,
		fmt = '1. หลังจากกิจกรรมเริ่มต้น ผู้เล่นสามารถเล่นวอลเลย์บอลบนชายหาดได้โดยไม่มีการจำกัดจำนวนครั้งต่อวัน'
	},
	[124904] = {
		id = 124904,
		fmt = '2. หลังจากเข้าสู่เกม ผู้เล่นต้องเลือกคุณสมบัติ 1 จาก 3 ประเภทที่จะเป็นคุณสมบัติเด่นของภูตที่ใช้'
	},
	[124905] = {
		id = 124905,
		fmt = '3. หลังจากเลือกแล้ว ระบบจะส่งภูตที่เกี่ยวข้องไปต่อสู้'
	},
	[124906] = {
		id = 124906,
		fmt = '4. พื้นที่สนามด้านซ้ายจะเป็นฝั่งของเรา และฝั่งขวาจะเป็นของฝ่ายตรงข้าม'
	},
	[124907] = {
		id = 124907,
		fmt = '5. ผู้เล่นสามารถขยับภูตไปทางซ้ายหรือขวา และภูตจะใช้หัวโหม่งลูกบอลที่ฝ่ายตรงข้ามส่งมา ผู้เล่นยังสามารถใช้ 3 วิธีด้านล่างในการแสดงทักษะ'
	},
	[124908] = {
		id = 124908,
		fmt = '6. หากลูกบอลกลับไปในฝั่งของฝ่ายตรงข้ามและฝ่ายตรงข้ามไม่ได้รับลูกบอล ผู้เล่นจะได้รับ 1 คะแนน'
	},
	[124909] = {
		id = 124909,
		fmt = '7. หากลูกบอลไปออกนอกเขตของฝ่ายตรงข้าม หรือเกิดข้อผิดพลาดที่ทำให้ลูกบอลออกนอกเขตของฝ่ายเรา จะทำให้ฝ่ายตรงข้ามได้รับ 1 คะแนน'
	},
	[124910] = {
		id = 124910,
		fmt = '8. ฝ่ายที่ได้รับ 3 คะแนนก่อนจะเป็นฝ่ายชนะ'
	},
	[124911] = {
		id = 124911,
		fmt = '9. การทำภารกิจที่กำหนดให้สำเร็จสามารถรับรางวัลที่คุ้มค่า'
	},
	[125001] = {
		id = 125001,
		fmt = '#L10##C0xF76B45#ยินดีต้อนรับสู่การผจญภัยเทศกาลฤดูร้อน'
	},
	[125002] = {
		id = 125002,
		fmt = '#C0xF76B45#ตำนานกล่าวว่าในวิหารกลางทะเลสาบ อาศัยอยู่โปเกม่อนที่สวยที่สุดในโลก……#C0x5B545B#'
	},
	[125003] = {
		id = 125003,
		fmt = '#C0xF76B45#คำอธิบายพื้นฐาน：#C0x5B545B#'
	},
	[125004] = {
		id = 125004,
		fmt = '1. ทุกวันจะเปิดด่านจำนวนจำกัด ผู้เล่นสามารถพยายามท้าทายซ้ำจนกว่าจะผ่านด่าน'
	},
	[125005] = {
		id = 125005,
		fmt = '2. หลังจากผ่านด่านครั้งแรกแล้วไม่สามารถท้าทายซ้ำได้ ต้องผ่านด่านก่อนหน้านี้ถึงจะสามารถเปิดการท้าทายด่านถัดไปได้'
	},
	[125006] = {
		id = 125006,
		fmt = '3. การสนทนาในด่านจะมีเทคนิคในการผ่านด่านซ่อนอยู่ สามารถดูภาพรวมเนื้อเรื่องได้หลังจากผ่านด่านในหน้าข้อมูล'
	},
	[125007] = {
		id = 125007,
		fmt = '#C0xF76B45#เทคนิคการผ่านด่าน: #C0x5B545B#ให้สังเกตเนื้อหาการสนทนา'
	},
	[125008] = {
		id = 125008,
		fmt = '#C0xF76B45#รางวัลจากการผ่านด่าน: #C0x5B545B#ได้รับรางวัลการผ่านด่านแรก'
	},
	[125101] = {
		id = 125101,
		fmt = '#C0x5E565D#*การเพิ่มพลังทั้งหมดจะต้องฝึกภูตในกระเป๋าภูตจากซีรีส์เดียวกันจนถึงระดับดาวที่กำหนดจึงจะสามารถใช้ได้โดยอัตโนมัติ'
