	[125301] = {
		id = 125301,
		fmt = '1. ในระหว่างกิจกรรม เมื่อทำภารกิจเสร็จแล้ว สามารถทำการขอพรในหน้าจอกิจกรรม'
	},
	[125302] = {
		id = 125302,
		fmt = '2. ในการขอพรสามารถได้รับพรธรรมดาสุ่ม หรือพรโชคดี'
	},
	[125303] = {
		id = 125303,
		fmt = '3. ทุกครั้งที่ขอพร หากไม่ได้พรโชคดี จะสามารถส่องโชคดีได้ 1 ครั้ง โดยจำนวนที่ส่องโชคดีจะมากขึ้น โอกาสในการได้รับพรโชคดีจะยิ่งสูงขึ้น และเมื่อส่องโชคดีครบทุกอันในหน้าจอแล้ว การขอพรครั้งถัดไปจะได้พรโชคดีอย่างแน่นอน'
	},
	[125304] = {
		id = 125304,
		fmt = '4. ภารกิจจะรีเซ็ตทุกวันตามเวลาที่กำหนด โปรดทำภารกิจและรับรางวัลให้ทัน ภารกิจที่ได้รับแล้วจะไม่ถูกรีเซ็ต และจะคงอยู่จนกว่ากิจกรรมจะสิ้นสุด'
	},
	[125305] = {
		id = 125305,
		fmt = '5. ในหน้าจอภารกิจขอพรสามารถดูบันทึกพรที่ได้รับจากกิจกรรมในครั้งนี้'
	},
	[125401] = {
		id = 125401,
		fmt = '1. ขีดจำกัดของอีเมลคือ #C0xF76B45#60#C0x5B545B# ฉบับ'
	},
	[125402] = {
		id = 125402,
		fmt = '2. เมื่อเกินขีดจำกัดของอีเมล อีเมลเก่าอาจหายไป โปรดจัดการอีเมลให้ทันเวลา'
	},
	[125501] = {
		id = 125501,
		fmt = '#L10##C0xF76B45#นักรบทั้งหลาย ยินดีต้อนรับสู่การประลองใหญ่ของห้อง'
	},
	[125502] = {
		id = 125502,
		fmt = '#L10##C0xF76B45#【กฎการคัดเลือก】'
	},
	[125503] = {
		id = 125503,
		fmt = '1. โครงการในห้องจะต้องมีการแข่งขันระหว่างกิลด์ที่แข็งแกร่ง 16 กิลด์จากหลายเซิร์ฟ'
	},
	[125504] = {
		id = 125504,
		fmt = '2. การคัดเลือกกิลด์จะอิงจากคะแนนสะสมจากการต่อสู้ของกิลด์ในสามสัปดาห์ (สามารถดูได้ในหน้าจอการประลองใหญ่ของห้อง) โดยกิลด์ที่ได้อันดับ #C0xF76B45#1#C0x5B545B# และ #C0xF76B45#2#C0x5B545B# จะถูกคัดเลือกโดยตรง'
	},
	[125505] = {
		id = 125505,
		fmt = '3. หากในกลุ่มข้ามเซิร์ฟไม่สามารถจัดตั้งจำนวนโครงการที่ต้องการได้ จะเลือกจากกิลด์ที่มีคะแนนการต่อสู้จากอันดับที่ 3 ถึง 5 โดยจะเลือกกิลด์ที่มีพลังการต่อสู้รวมสูงกว่าเป็นอันดับแรก'
	},
	[125506] = {
		id = 125506,
		fmt = '4. เมื่อการแข่งขันสามสัปดาห์ของการต่อสู้ของกิลด์สิ้นสุดลง กิลด์และสมาชิกที่เข้าร่วมการแข่งขันจะถูกล็อกไว้ สมาชิกที่เข้าร่วมกิลด์ที่ได้รับการคัดเลือกหลังจากนั้นจะไม่สามารถเข้าร่วมการประลองใหญ่ของห้องในครั้งนี้ได้'
	},
	[125507] = {
		id = 125507,
		fmt = '#L10##C0xF76B45#【กฎพื้นฐาน】'
	},
	[125508] = {
		id = 125508,
		fmt = '1. การประลองใหญ่ของห้องจะเป็นฤดูกาลหนึ่งที่ใช้#C0xF76B45#สี่สัปดาห์#C0x5B545B# โดยหลังจากเก็บข้อมูลคะแนนการต่อสู้ของกิลด์จากสามสัปดาห์ ระบบจะเริ่มสัปดาห์ที่สี่'
	},
	[125509] = {
		id = 125509,
		fmt = '2. การประลองใหญ่ของห้องแบ่งออกเป็นสองขั้นตอน ได้แก่ รอบคัดเลือกและรอบชิงชนะเลิศ โดยรอบคัดเลือกจะจัดใน#C0xF76B45#วันศุกร์#C0x5B545B# ของสัปดาห์ที่เริ่มต้น และรอบชิงชนะเลิศจะจัดใน#C0xF76B45#วันอาทิตย์#C0x5B545B# ของสัปดาห์ที่เริ่มต้น'
	},
	[125510] = {
		id = 125510,
		fmt = '3. กิลด์ที่ได้รับการคัดเลือก ระบบจะทำการสมัครสมาชิกกิลด์ให้โดยอัตโนมัติ สมาชิกในกิลด์ต้องเลือกกลุ่มงานและการจัดวางทีมที่ต้องการในช่วงเวลา#C0xF76B45#9:00~20:50#C0x5B545B#'
	},
	[125511] = {
		id = 125511,
		fmt = '4. ผู้เล่นที่ไม่เลือกสนามรบภายใน 10 นาทีของการแข่งขัน ระบบจะทำการจัดสนามรบและเลือกภูตที่มีพลังการต่อสู้สูงที่สุดในการจัดวางทีมโดยอัตโนมัติ'
	},
	[125512] = {
		id = 125512,
		fmt = '5. เวลาเริ่มการแข่งขันอย่างเป็นทางการ: #C0xF76B45#21:00#C0x5B545B#'
	},
	[125513] = {
		id = 125513,
		fmt = '#L10##C0xF76B45#【กฎการคัดเลือก】'
	},
	[125514] = {
		id = 125514,
		fmt = '1. ในรอบคัดเลือก: กิลด์ที่ได้รับการคัดเลือก 16 กิลด์จะถูกแบ่งเป็น 4 กลุ่มตามอันดับพลังการต่อสู้ สมาชิกของแต่ละกิลด์ต้องสมัครเข้าร่วมกลุ่มงานที่ต้องการภายในเวลาที่กำหนด'
	},
	[125515] = {
		id = 125515,
		fmt = '2. กลุ่มงานมีทั้งหมด 3 ประเภท'
	},
	[125516] = {
		id = 125516,
		fmt = 'กลุ่มงาน 6 คน: สามารถส่งทีมได้ 2 ทีม โดยแต่ละทีมประกอบด้วยภูต 6 ตัว'
	},
	[125517] = {
		id = 125517,
		fmt = 'กลุ่มงาน 4 คน: สามารถส่งทีมได้ 3 ทีม โดยแต่ละทีมประกอบด้วยภูต 4 ตัว'
	},
	[125518] = {
		id = 125518,
		fmt = 'กลุ่มงาน 1 คน: สามารถส่งทีมได้ 3 ทีม โดยแต่ละทีมประกอบด้วยภูต 3 ตัว'
	},
	[125519] = {
		id = 125519,
		fmt = 'ผู้เล่นที่เข้าร่วมการแข่งขันสามารถเลือกได้เพียงหนึ่งสนามในการเข้าร่วมการแข่งขัน และหลังจากหมดเวลาสมัครกลุ่มงานและภูตที่เลือกจะถูกล็อกไว้ ไม่สามารถเปลี่ยนแปลงได้เมื่อการต่อสู้เริ่มขึ้น'
	},
	[125520] = {
		id = 125520,
		fmt = '3. ในระหว่างการต่อสู้ เมื่อทีมแรกถูกโจมตีจนพ่ายแพ้ ทีมที่สองสามารถเข้าร่วมต่อสู้ในรอบถัดไป'
	},
	[125521] = {
		id = 125521,
		fmt = '4. รูปแบบการแข่งขันคือโหมดการต่อสู้แบบปะทะกัน ผู้เล่นจะถูกจับคู่กับผู้เล่นที่ไม่ใช่สมาชิกของกิลด์ตัวเองเป็นอันดับแรก (เมื่อเหลือผู้เล่นจากกิลด์เดียวกันทั้งหมด การต่อสู้จะสิ้นสุดลง)'
	},
	[125522] = {
		id = 125522,
		fmt = '5. ผู้เล่นที่ชนะจะสามารถดำเนินการต่อไปยังรอบถัดไปและต่อสู้กับผู้เล่นจากกิลด์อื่น ๆ ต่อไป'
	},
	[125523] = {
		id = 125523,
		fmt = '6. ผู้เล่นที่ไม่มีภูตที่จะเข้าร่วมการต่อสู้จะถูกคัดออกชั่วคราว หากกิลด์ของผู้เล่นที่ถูกคัดออกสามารถผ่านเข้าสู่รอบชิงชนะเลิศได้ ผู้เล่นนั้นจะได้เข้าสู่รอบชิงชนะเลิศด้วย หากกิลด์ไม่สามารถผ่านเข้ารอบได้ ผู้เล่นจะไม่ได้เข้าร่วมการชิงแชมป์ครั้งนี้'
	},
	[125524] = {
		id = 125524,
		fmt = '7. หลังจากแต่ละการต่อสู้ จะมีการเก็บค่าชีวิตและค่าพลังโกรธของภูตไว้'
	},
	[125525] = {
		id = 125525,
		fmt = '8. การประลองใหญ่ของห้องมีระบบคะแนนที่ต่างกันสำหรับแต่ละกลุ่มงาน ผลการแข่งขันชนะหรือแพ้ของแต่ละกลุ่มจะได้รับคะแนนต่างกัน'
	},
	[125526] = {
		id = 125526,
		fmt = 'กลุ่มงาน 6 คน: ชนะจะได้รับ#C0xF76B45#9#C0x5B545B# คะแนน, แพ้จะได้รับ#C0xF76B45#3#C0x5B545B# คะแนน'
	},
	[125527] = {
		id = 125527,
		fmt = 'กลุ่มงาน 4 คน: ชนะจะได้รับ#C0xF76B45#8#C0x5B545B# คะแนน, แพ้จะได้รับ#C0xF76B45#2#C0x5B545B# คะแนน'
	},
	[125528] = {
		id = 125528,
		fmt = 'กลุ่มงาน 1 คน: ชนะจะได้รับ#C0xF76B45#10#C0x5B545B# คะแนน, แพ้จะได้รับ#C0xF76B45#4#C0x5B545B# คะแนน'
	},
	[125529] = {
		id = 125529,
		fmt = '9. หลังจากการต่อสู้ จะมีการให้คะแนนเพิ่มเติมตามจำนวนผู้เล่นที่ยังมีชีวิตของแต่ละกิลด์'
	},
	[125530] = {
		id = 125530,
		fmt = '10. การเข้าสู่รอบชิงชนะเลิศจะขึ้นอยู่กับคะแนนรวมของสมาชิกกิลด์ที่อยู่ในกลุ่มงานต่าง ๆ ในวันนั้น'
	},
	[125531] = {
		id = 125531,
		fmt = '11. ทั้งสองฝ่ายจะสามารถต่อสู้ได้สูงสุด 10 รอบ หากยังไม่สามารถตัดสินผู้ชนะได้ ภาพรวมของเปอร์เซ็นต์เลือดที่เหลือจะเป็นตัวตัดสินผู้ชนะ'
	},
	[125532] = {
		id = 125532,
		fmt = '12. หลังจากรอบคัดเลือกสิ้นสุดลง จะเลือกผู้ชนะจากแต่ละกลุ่มงาน 4 กลุ่มเพื่อเข้าสู่รอบชิงชนะเลิศ กิลด์ที่เหลือจะถูกคัดออก'
	},
	[125533] = {
		id = 125533,
		fmt = '#L10##C0xF76B45#【กฎการชิงชนะเลิศ】'
	},
	[125534] = {
		id = 125534,
		fmt = '1. ตามผลคะแนนในรอบคัดเลือก จะเลือกกิลด์ที่แข็งแกร่งที่สุด 4 กิลด์เข้าสู่การแข่งขันแชมป์สุดท้าย'
	},
	[125535] = {
		id = 125535,
		fmt = '2. กติกาการแข่งขันในรอบชิงชนะเลิศจะเหมือนกับรอบคัดเลือก'
	},
	[125536] = {
		id = 125536,
		fmt = '3. ในที่สุด การจัดอันดับรอบชิงชนะเลิศจะทำตามระบบคะแนนเดียวกับรอบคัดเลือก โดยจะจัดอันดับจากที่ 1 ถึง 4'
	},
	[125537] = {
		id = 125537,
		fmt = '4. กิลด์แชมป์จะได้รับเกียรติยศสูงสุดที่สามารถมองเห็นได้จากทุกกิลด์ในกลุ่มข้ามเซิร์ฟ'
	},
	[125538] = {
		id = 125538,
		fmt = '#L10##C0xF76B45#【การเปลี่ยนแปลงความสามารถของโปเกมอน】'
	},
	[125539] = {
		id = 125539,
		fmt = '1. ในระหว่างการประลองใหญ่ของห้อง ทุกครั้งที่เริ่มการต่อสู้ในแต่ละรอบ ทุกภูตในทีมที่เข้าร่วมการต่อสู้ครั้งแรกจะได้รับการเพิ่มค่าพลังบางอย่าง เช่น การโจมตี การป้องกัน ความเร็ว และคุณสมบัติอื่น ๆ'
	},
	[125540] = {
		id = 125540,
		fmt = '2. เมื่อการต่อสู้ดำเนินไป ค่าพลังที่ได้รับจะค่อย ๆ ลดลง และภูตจะเริ่มรู้สึกเหนื่อยล้า ความสามารถในการต่อสู้จะลดลงเรื่อย ๆ'
	},
	[125541] = {
		id = 125541,
		fmt = '3. หลังจากนั้น ทุกครั้งที่เข้าร่วมการต่อสู้ ค่าพลังต่าง ๆ ของภูตในทีม เช่น การโจมตี การป้องกัน ความเร็ว ปริมาณการรักษา ฯลฯ จะลดลงอย่างต่อเนื่อง'
	},
	[125542] = {
		id = 125542,
		fmt = '#L10##C0xF76B45#【กฎการทายผล】'
	},
	[125543] = {
		id = 125543,
		fmt = '1. ผู้เล่นทุกคนในกลุ่มข้ามเซิร์ฟเดียวกันสามารถเข้าร่วมการทายผลได้ (รวมถึงผู้เล่นที่เข้าร่วมการต่อสู้)'
	},
	[125544] = {
		id = 125544,
		fmt = '2. สามารถทายผลได้ทั้งในรอบคัดเลือกและรอบชิงชนะเลิศ'
	},
	[125545] = {
		id = 125545,
		fmt = 'ในช่วงรอบคัดเลือก ผู้เล่นสามารถทายผลได้ 4 ครั้ง (ครั้งละหนึ่งครั้งในแต่ละกลุ่มการต่อสู้) โดยเป้าหมายในการทายผลคือกิลด์ที่จะเข้าสู่รอบชิงชนะเลิศ'
	},
	[125546] = {
		id = 125546,
		fmt = 'ในช่วงรอบชิงชนะเลิศ ผู้เล่นสามารถทายผลได้ 1 ครั้ง โดยเป้าหมายในการทายผลคือกิลด์แชมป์'
	},
	[125547] = {
		id = 125547,
		fmt = '3. การทายผลต้องใช้เหรียญกิลด์ โดยในรอบคัดเลือกจะต้องใช้เหรียญกิลด์ 500 เหรียญต่อการทายผล 1 ครั้ง และในรอบชิงชนะเลิศจะต้องใช้เหรียญกิลด์ 2000 เหรียญต่อการทายผล 1 ครั้ง'
	},
	[125548] = {
		id = 125548,
		fmt = '4. ผู้เล่นที่เข้าร่วมการทายผลจะได้รับรางวัล โดยรางวัลจะถูกส่งผ่านทางอีเมล'
	},
	[125549] = {
		id = 125549,
		fmt = '#L10##C0xF76B45#【กฎการมอบรางวัล】'
	},
	[125550] = {
		id = 125550,
		fmt = '1. หลังจากการแข่งขันสิ้นสุดลง รางวัลทั้งหมดจะถูกส่งผ่านทางอีเมล'
	},
	[125551] = {
		id = 125551,
		fmt = '2. การประลองใหญ่ของห้องคือการแข่งขันที่ใช้กิลด์เป็นหน่วย รางวัลจากการจัดอันดับกิลด์จะมอบให้กับสมาชิกทุกคนที่เข้าร่วมการแข่งขันของกิลด์นั้น'
	},
	[125552] = {
		id = 125552,
		fmt = '3. กิลด์ที่เข้าร่วมทั้งรอบคัดเลือกและรอบชิงชนะเลิศจะได้รับรางวัลหนึ่งรางวัล'
	},
	[125553] = {
		id = 125553,
		fmt = '4. กิลด์ที่ได้รับแชมป์ในรอบชิงชนะเลิศจะได้รับการแสดงเกียรติยศสูงสุดในกลุ่มข้ามเซิร์ฟ'
	},
	[125554] = {
		id = 125554,
		fmt = '5. รางวัลจากการจัดอันดับคะแนนสามารถดูรายละเอียดได้จากการแสดงรางวัลต่อไปนี้'
	},
	[125601] = {
		id = 125601,
		fmt = '#L10##C0xF76B45#【การทายผลรอบคัดเลือกและรอบชิงชนะเลิศ】'
	},
	[125602] = {
		id = 125602,
